INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "包围是从四面八方把一个地方围住。", "primary_collocate": null, "pronunciation": "bāo wéi", "ipa": "pɑʊ⁵⁵ weɪ³⁵", "syllable_count": 2, "sentences": [{"text": "军队从四面八方包围了这座城。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察包围了银行，小偷出不来。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家从东西南北包围了广场。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察包围了整个院子，不让人出入。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人包围了山上的村子。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们悄悄包围了小山洞。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵从各个方向包围了机场。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警车包围了那栋楼。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防队员从四面八方包围了着火的仓库。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水从三面包围了这个小岛。", "target_word": "包围", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "包围了", "label": "体标"}, {"form": "包围着", "label": "体标"}], "register": "中性", "sense_fingerprint": "从各个方向把一个地方围住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ab46821f-b651-4563-9f21-fba4344ba828') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "包围", "is_correct": true, "explanation": "“包围”指从各个方向把城围住，与“从四面八方”的语境一致。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”的对象是食物，不能用于城市。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以城市为宾语。"}, {"text": "煎", "is_correct": false, "explanation": "语义：“煎”是烹饪方式，与“城”无法搭配。"}], "explanations": {"包围": "“包围”指从各个方向把城围住，与“从四面八方”的语境一致。", "烤": "语义：“烤”的对象是食物，不能用于城市。", "唱": "搭配：“唱”不能以城市为宾语。", "煎": "语义：“煎”是烹饪方式，与“城”无法搭配。"}, "sentence_index": 0, "correct_answer": "包围"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师包围了他的错误。", "explanation": "这里应该用〈包容〉。包围指从四周围住，宽容地对待别人的错误要说“包容”。"}, {"text": "这家公司包围了三个部门。", "explanation": "这里应该用〈包括〉。说某个组织下辖哪些部门要用“包括”，包围不能这样用。"}, {"text": "医生包围了他的腿。", "explanation": "这里应该用〈包扎〉。给腿缠绷带要说“包扎”，包围是把人或地方围住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "包围", "is_correct": true, "explanation": "“包围”指从各个方向把机场围住，与句意一致。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”指编织布料或网，不能用于机场。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”的对象是可以擦拭的表面，机场不能被擦。"}, {"text": "编", "is_correct": false, "explanation": "搭配：“编”需要以布、绳等为对象，不能说“编机场”。"}], "explanations": {"包围": "“包围”指从各个方向把机场围住，与句意一致。", "织": "语义：“织”指编织布料或网，不能用于机场。", "擦": "语义：“擦”的对象是可以擦拭的表面，机场不能被擦。", "编": "搭配：“编”需要以布、绳等为对象，不能说“编机场”。"}, "sentence_index": 6, "correct_answer": "包围"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些家务我都包围了。", "explanation": "这里应该用〈包办〉。包围指从四面把人或地方围住，承担全部事务要说“包办”，不能用包围。"}, {"text": "这篇文章包围了很多观点。", "explanation": "这里应该用〈包含〉。文章里收录观点要说“包含”，包围不能指内容的收录。"}, {"text": "这盒点心包围得很精致。", "explanation": "这里应该用〈包装〉。给点心做外包装要说“包装”，包围是围住，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消防员把那片森林包围下来了。", "corrected_sentence": "消防员把那片森林包围起来了。", "error_description": "错误在补语：“包围”后的趋向补语应用“起来”，不能用“下来”，应说“包围起来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93891, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洪水从三面包围着了那个村庄。", "corrected_sentence": "洪水从三面包围了那个村庄。", "error_description": "错误在体标：“包围着”表示持续，后面不能再接“了”；表示完成只用“包围了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a397041-4eb9-4c61-86c8-e714d1e8cd39') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
