INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93895, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "只好是没有别的办法，只能这样做。", "primary_collocate": null, "pronunciation": "zhǐ hǎo", "ipa": "ʈʂɻ̩˨˩˦ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "下雨了，我们只好在家看电影。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "末班车已经走了，他只好走路回家。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，我只好用同学的电话。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店关门了，我们只好明天再来。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有座位，我只好站着听课。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不会开车，只好坐地铁去公司。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "票卖完了，她只好换一个时间。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "忘了带钥匙，我只好在门口等妈妈。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车，老师只好先开始上课。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店没有鱼了，我们只好点鸡肉。", "target_word": "只好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "没有别的办法，只能这样做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1d60f8e-cf7f-4e4e-b486-7bb9d64b7105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93895, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "只好", "is_correct": true, "explanation": "正确：“只好”表示没有别的办法，只能在家看电影，与“下雨了”的原因相合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与句中因下雨而不得已的意思不合。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，与下雨后不得已在家看电影的意思不合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，与下雨之后的必然选择不合。"}], "explanations": {"只好": "正确：“只好”表示没有别的办法，只能在家看电影，与“下雨了”的原因相合。", "偶尔": "语义：“偶尔”表示不常发生，与句中因下雨而不得已的意思不合。", "从来": "语义：“从来”表示一向如此，与下雨后不得已在家看电影的意思不合。", "竟然": "语义：“竟然”表示出乎意料，与下雨之后的必然选择不合。"}, "sentence_index": 0, "correct_answer": "只好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们有的是时间，只好慢慢吃饭。", "explanation": "这里应该用〈索性〉。“只好”表示迫于无奈，有的是时间、从容吃饭时应该用“索性”表示干脆地这样做。"}, {"text": "这个牌子的衣服很便宜，我们只好全部买下了。", "explanation": "这里应该用〈干脆〉。“只好”表示迫于无奈，因为便宜而全部买下应用“干脆”表示果断地决定。"}, {"text": "这部电影我们很喜欢，只好高兴地看了两遍。", "explanation": "这里应该用〈又〉。“只好”带有勉强的语气，喜欢而重复观看应用“又”表示再次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93895, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "只好", "is_correct": true, "explanation": "正确：“只好”表示票卖完后没有别的选择，只能换时间，与句意相合。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与“票卖完了”这一被迫的原因不合。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示持续不变，与“换一个时间”这一改变不合。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”不能修饰“换”这样的动作，只能修饰形容词或心理动词。"}], "explanations": {"只好": "正确：“只好”表示票卖完后没有别的选择，只能换时间，与句意相合。", "故意": "语义：“故意”表示有意为之，与“票卖完了”这一被迫的原因不合。", "一直": "语义：“一直”表示持续不变，与“换一个时间”这一改变不合。", "非常": "搭配：“非常”不能修饰“换”这样的动作，只能修饰形容词或心理动词。"}, "sentence_index": 6, "correct_answer": "只好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气转晴了，我们只好带伞出门。", "explanation": "这里应该用〈仍然〉。“只好”表示迫于无奈，天气转晴后仍带伞出门并非被迫，应用“仍然”表示照旧。"}, {"text": "这本书很有意思，我只好一口气读完了。", "explanation": "这里应该用〈竟然〉。“只好”表示勉强，书很有意思而一口气读完应用“竟然”表示出乎意料。"}, {"text": "今天天气很好，大家只好去公园散步。", "explanation": "这里应该用〈不如〉。“只好”表示迫于无奈，天气好去散步是自愿的选择，应用“不如”提出建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93895, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "票卖完了，我们只好能明天再来。", "corrected_sentence": "票卖完了，我们只好明天再来。", "error_description": "错误在“只好能”。“只好”已表示没有别的办法，后面不能再接“能”这类助动词；应删去“能”，正确为“票卖完了，我们只好明天再来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93895, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨太大了，我们只好了待在屋里。", "corrected_sentence": "雨太大了，我们只好待在屋里。", "error_description": "错误在“只好了”。“了”不能紧跟副词“只好”，应直接接动词；正确为“雨太大了，我们只好待在屋里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
