INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93901, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "丧失是本来有的东西，现在没有了。", "primary_collocate": null, "pronunciation": "sàng shī", "ipa": "sɑŋ˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "经过几次失败，他丧失了信心。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，她丧失了所有的希望。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间不说话，他丧失了说话的勇气。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对工作丧失了兴趣，每天都不想上班。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人丧失了食欲，什么都不想吃。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要丧失信心，只要努力就会成功。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期住院后，他丧失了对生活的热情。", "target_word": "丧失", "complexity_tier": "T3", "furigana": "cháng qī zhù yuàn hòu, tā sàng shī le duì shēng huó de rè qíng", "sentence_source": "generated"}, {"text": "老人丧失了记忆，连家人都不认识。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她丧失了对朋友的信任，不再相信别人。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "失败太多，队员们丧失了斗志。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喪失", "label": "繁体"}, {"form": "丧失了", "label": "体标"}, {"form": "丧失过", "label": "体标"}], "register": "书面", "sense_fingerprint": "本来有的信心、希望等现在没有了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8002c7be-6b02-43d9-b4a1-4844c45b5b72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丧失", "is_correct": true, "explanation": "丧失指本来有的信心失去了，与“经过几次失败”的语境相符。"}, {"text": "测量", "is_correct": false, "explanation": "语义：测量是用仪器量取数值，信心不能被测量。"}, {"text": "发挥", "is_correct": false, "explanation": "搭配：“发挥”多用于作用、才能，不说“发挥信心”。"}, {"text": "报废", "is_correct": false, "explanation": "搭配：“报废”用于设备、物品，不能用于信心。"}], "explanations": {"丧失": "丧失指本来有的信心失去了，与“经过几次失败”的语境相符。", "测量": "语义：测量是用仪器量取数值，信心不能被测量。", "发挥": "搭配：“发挥”多用于作用、才能，不说“发挥信心”。", "报废": "搭配：“报废”用于设备、物品，不能用于信心。"}, "sentence_index": 0, "correct_answer": "丧失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一不小心丧失了一只手套。", "explanation": "这里应该用〈丢失〉。丧失用于能力、信心等抽象的东西，手套这样的具体物品要用“丢失”。"}, {"text": "我的护照丧失了，正在补办。", "explanation": "这里应该用〈遗失〉。丧失不用于证件这类具体物品，丢了证件要用“遗失”。"}, {"text": "他丧失了钥匙，只好找锁匠。", "explanation": "这里应该用〈失去〉。丧失多用于能力、信心等抽象的东西，钥匙是具体物品，用“失去”更自然。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丧失", "is_correct": true, "explanation": "丧失指本来有的热情失去了，与“长期住院后”的语境相符。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物品，不能用于热情。"}, {"text": "估算", "is_correct": false, "explanation": "语义：估算是估计数量，热情不能被估算。"}, {"text": "推销", "is_correct": false, "explanation": "搭配：“推销”是卖东西，不能用于热情。"}], "explanations": {"丧失": "丧失指本来有的热情失去了，与“长期住院后”的语境相符。", "修理": "搭配：“修理”用于机器、物品，不能用于热情。", "估算": "语义：估算是估计数量，热情不能被估算。", "推销": "搭配：“推销”是卖东西，不能用于热情。"}, "sentence_index": 6, "correct_answer": "丧失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他丧失了整整一个下午，什么也没做。", "explanation": "这里应该用〈浪费〉。丧失指原有的能力、信心等失去，不用于白白花掉的时间。"}, {"text": "他丧失了这次比赛。", "explanation": "这里应该用〈错过〉。丧失指原有的能力、信心等失去，比赛时间已到却没参加，应说“错过”。"}, {"text": "他起身时丧失了座位。", "explanation": "这里应该用〈离开〉。丧失指原有的能力、信心等不再具备，起身离开座位只是离开，不是丧失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她渐渐丧失着信念。", "corrected_sentence": "她渐渐丧失了信念。", "error_description": "“丧失”表示一次性失去，不能加持续标记“着”。正确说法是“她渐渐丧失了信念”，用“了”表示已经失去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续失败后，他已经很丧失了斗志。", "corrected_sentence": "连续失败后，他已经完全丧失了斗志。", "error_description": "“很”主要修饰形容词，一般不直接修饰“丧失”这类动词；表示彻底失去要用“完全”，把“很”换成“完全”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93902, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "获得", "is_correct": true, "explanation": "获得与丧失是反义词，指得到原来没有的能力或资格，与丧失相对。"}, {"text": "发明", "is_correct": false, "explanation": "发明是创造新事物，与丧失没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是交换意见，与丧失没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是在水中运动，与丧失没有反义关系。"}], "correct_answer": "获得", "explanations": {"获得": "获得与丧失是反义词，指得到原来没有的能力或资格，与丧失相对。", "发明": "发明是创造新事物，与丧失没有反义关系。", "讨论": "讨论是交换意见，与丧失没有反义关系。", "游泳": "游泳是在水中运动，与丧失没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
