INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93902, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "失去；原有的东西不再具有。", "primary_collocate": null, "pronunciation": "sàng shī", "ipa": "sɑŋ˥˩ ʂɻ̩˥", "syllable_count": 2, "sentences": [{"text": "他出了事故，丧失了工作能力。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人丧失了做医生的资格。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人眼睛不好，已经丧失了视力。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药放太久，会丧失药效。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犯了罪，丧失了投票的权利。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座城市丧失了原来的魅力。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地丧失了肥力，种不出粮食。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战败的国家丧失了很多土地。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话丧失了力量，没有人再听。", "target_word": "丧失", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老照片放久了，已经丧失了原来的光泽。", "target_word": "丧失", "complexity_tier": "T3", "furigana": "lǎo zhào piàn fàng jiǔ le, yǐ jīng sàng shī le yuán lái de guāng zé", "sentence_source": "generated"}], "morphological_forms": [{"form": "喪失", "label": "繁体"}, {"form": "丧失了", "label": "体标"}, {"form": "丧失过", "label": "体标"}], "register": "书面", "sense_fingerprint": "原有的能力、资格、权利等不再具有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8002c7be-6b02-43d9-b4a1-4844c45b5b72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "丧失", "is_correct": true, "explanation": "丧失指原有的能力不再具有，与“出了事故”的语境相符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是烹饪食物的动作，能力不能被煮。"}, {"text": "摆脱", "is_correct": false, "explanation": "搭配：“摆脱”多用于负担、困境，不说“摆脱能力”。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：挑选是选择具体的东西，不能挑选能力。"}], "explanations": {"丧失": "丧失指原有的能力不再具有，与“出了事故”的语境相符。", "煮": "语义：煮是烹饪食物的动作，能力不能被煮。", "摆脱": "搭配：“摆脱”多用于负担、困境，不说“摆脱能力”。", "挑选": "语义：挑选是选择具体的东西，不能挑选能力。"}, "sentence_index": 0, "correct_answer": "丧失"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的行李丧失了，只能重新买衣服。", "explanation": "这里应该用〈丢失〉。丧失用于能力、权利等抽象的东西，行李这样的物品要用“丢失”。"}, {"text": "这把伞丧失在车站了。", "explanation": "这里应该用〈遗失〉。丧失不用于伞这样的具体物品，把东西落在某处要用“遗失”。"}, {"text": "他的证件丧失了，需要去派出所补办。", "explanation": "这里应该用〈丢失〉。证件是具体物品，丢了要用“丢失”，丧失用于抽象的能力或权利。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丧失", "is_correct": true, "explanation": "丧失指原有的肥力不再具有，与“种不出粮食”的语境相符。"}, {"text": "拍照", "is_correct": false, "explanation": "语义：拍照是用相机拍摄，肥力不能被拍照。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”用于景色、作品，不说“欣赏肥力”。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”用于商品，肥力不能被购买。"}], "explanations": {"丧失": "丧失指原有的肥力不再具有，与“种不出粮食”的语境相符。", "拍照": "语义：拍照是用相机拍摄，肥力不能被拍照。", "欣赏": "搭配：“欣赏”用于景色、作品，不说“欣赏肥力”。", "购买": "搭配：“购买”用于商品，肥力不能被购买。"}, "sentence_index": 6, "correct_answer": "丧失"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在车站丧失了钱包。", "explanation": "这里应该用〈失去〉。丧失多用于能力、权利等抽象的东西，钱包是具体物品，用“失去”更自然。"}, {"text": "他一时丧失了朋友的名字，很不好意思。", "explanation": "这里应该用〈遗忘〉。丧失指原有的能力、权利失去，忘记名字要用“遗忘”。"}, {"text": "他丢弃了那些旧书，现在丧失了它们。", "explanation": "这里不能用〈丧失〉。丧失指非自愿地失去原有的东西，自己扔掉旧书是主动的，应说“扔掉”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他因为受伤，丧失着运动能力。", "corrected_sentence": "他因为受伤，丧失了运动能力。", "error_description": "“丧失”表示一次性失去，不能加持续标记“着”。正确说法是“丧失了运动能力”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那棵老树的生命力已经很丧失了。", "corrected_sentence": "那棵老树的生命力已经完全丧失了。", "error_description": "“很”不能修饰动词“丧失”，表示彻底失去要用“完全”。正确说法是“已经完全丧失了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
