INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93909, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专辑是把一个歌手的很多首歌放在一起的一套歌。", "primary_collocate": null, "pronunciation": "zhuān jí", "ipa": "ʈʂuan˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这张专辑一共有十首歌。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下个月要出新专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了他的第一张专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张专辑里的歌我都喜欢。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥每天都听这张专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的专辑卖得很好。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "歌手今天发了一张新专辑。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一张很老的专辑，我听过很多遍。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把这张专辑送给了朋友。", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听过她的这张专辑吗？", "target_word": "专辑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张专辑", "label": "量词"}, {"form": "音乐专辑", "label": "复合词"}, {"form": "專輯", "label": "繁体"}], "register": "通用", "sense_fingerprint": "歌手的一套歌曲合集", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19b15c9f-8226-4dee-a7e1-d0e9710ecd9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93909, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专辑", "is_correct": true, "explanation": "正确答案：专辑，读作 zhuān jí，指收录一位歌手多首歌曲的一套唱片。"}, {"text": "专机", "is_correct": false, "explanation": "zhuān 相同，jī（第一声）与 jí（第二声）声调不同，意思是专门用来载运重要人物的飞机。"}, {"text": "转机", "is_correct": false, "explanation": "zhuǎn（第三声）与 zhuān（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，意思是转乘另一班飞机。"}, {"text": "传记", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuān（第一声）、jì（第四声）与 jí（第二声）声调均不同，意思是记录人物生平的书。"}, {"text": "专职", "is_correct": false, "explanation": "zhí 与 jí 声母不同（zh 与 j），且 zhí 为第二声，意思是专门担任的职务。"}], "explanations": {"专辑": "正确答案：专辑，读作 zhuān jí，指收录一位歌手多首歌曲的一套唱片。", "专机": "zhuān 相同，jī（第一声）与 jí（第二声）声调不同，意思是专门用来载运重要人物的飞机。", "转机": "zhuǎn（第三声）与 zhuān（第一声）声调不同，jī（第一声）与 jí（第二声）声调也不同，意思是转乘另一班飞机。", "传记": "zhuàn（第四声）与 zhuān（第一声）、jì（第四声）与 jí（第二声）声调均不同，意思是记录人物生平的书。", "专职": "zhí 与 jí 声母不同（zh 与 j），且 zhí 为第二声，意思是专门担任的职务。"}, "sentence_index": null, "correct_answer": "专辑"}, "level_3": {"options": [{"text": "专辑", "is_correct": true, "explanation": "正确答案：专辑，指收录一位歌手多首歌的一套唱片，与“一共有十首歌”相符。"}, {"text": "照片", "is_correct": false, "explanation": "语义：“照片”是图像，不收录歌曲，与“一共有十首歌”不符。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”用来标示地理位置，不收录歌曲，与“一共有十首歌”不符。"}, {"text": "歌词", "is_correct": false, "explanation": "搭配：“歌词”指一首歌的文字，通常用“首”或“段”计量，不用“张”，也不能说有十首歌。"}], "explanations": {"专辑": "正确答案：专辑，指收录一位歌手多首歌的一套唱片，与“一共有十首歌”相符。", "照片": "语义：“照片”是图像，不收录歌曲，与“一共有十首歌”不符。", "地图": "语义：“地图”用来标示地理位置，不收录歌曲，与“一共有十首歌”不符。", "歌词": "搭配：“歌词”指一首歌的文字，通常用“首”或“段”计量，不用“张”，也不能说有十首歌。"}, "sentence_index": 0, "correct_answer": "专辑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "专辑唱歌唱得很好听。", "explanation": "这里应该用〈歌手〉。唱歌的是人，专辑是唱片，不能唱歌。"}, {"text": "我买了一只专辑。", "explanation": "这里应该用〈张〉。专辑用“张”计量，“只”用于动物，不能用于专辑。"}, {"text": "这张专辑的门票很贵。", "explanation": "这里应该用〈演唱会〉。门票属于现场演出，专辑是唱片，没有门票，因此不能说“专辑的门票”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93909, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专辑", "is_correct": true, "explanation": "正确答案：专辑，指歌手发行的一套歌曲合集，与“发”和“新”相符。"}, {"text": "病历", "is_correct": false, "explanation": "语义：“病历”是病人的医疗记录，不是音乐作品，与“歌手发”的语境不符。"}, {"text": "发票", "is_correct": false, "explanation": "语义：“发票”是购买凭证，不是歌手发行的作品，与句意不符。"}, {"text": "证件", "is_correct": false, "explanation": "语义：“证件”是证明身份或资格的凭证，歌手不会发放，与“歌手今天发了”的语境不符。"}], "explanations": {"专辑": "正确答案：专辑，指歌手发行的一套歌曲合集，与“发”和“新”相符。", "病历": "语义：“病历”是病人的医疗记录，不是音乐作品，与“歌手发”的语境不符。", "发票": "语义：“发票”是购买凭证，不是歌手发行的作品，与句意不符。", "证件": "语义：“证件”是证明身份或资格的凭证，歌手不会发放，与“歌手今天发了”的语境不符。"}, "sentence_index": 6, "correct_answer": "专辑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作曲家写了很多首歌，专辑也写了很多首歌。", "explanation": "这里把“专辑”当成了写歌的人，应该用〈词曲作者〉。专辑只是收录歌曲的唱片，不会写歌。"}, {"text": "我买了三台专辑。", "explanation": "这里应该用〈张〉。专辑用“张”计量，“台”用于机器，不能用于专辑。"}, {"text": "我一口气把这本专辑喝光了。", "explanation": "搭配：“喝光”用于饮料，“专辑”是唱片或出版物，不能被喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93909, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她下个月要发一只新专辑。", "corrected_sentence": "她下个月要发一张新专辑。", "error_description": "量词错误。专辑用量词“张”，“只”用于动物等，不能用于专辑。应说“一张新专辑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93909, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张很老专辑是我爸爸的。", "corrected_sentence": "这张很老的专辑是我爸爸的。", "error_description": "修饰名词的“很老”后面漏掉了“的”。应说“很老的专辑”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '077c1a37-40d5-40ef-8a16-3f2d772a687f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
