INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93915, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "弹是用手指拨动东西，让它发出声音。", "primary_collocate": null, "pronunciation": "tán", "ipa": "tʰan˧˥", "syllable_count": 1, "sentences": [{"text": "他会弹吉他。", "target_word": "弹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妹妹在家弹钢琴。", "target_word": "弹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我弹过这首歌，不难。", "target_word": "弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她弹得很好，大家都爱听。", "target_word": "弹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一边弹吉他，一边唱歌。", "target_word": "弹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷弹了一首老歌给我们听。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她弹着琴，我在旁边唱歌。", "target_word": "弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把吉他很旧，可是弹出来的声音很好听。", "target_word": "弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你弹一下这根弦，听听是什么声音。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她十岁就开始弹钢琴，现在是老师了。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹了", "label": "完成体"}, {"form": "弹过", "label": "经历体"}, {"form": "弹弹", "label": "重叠"}, {"form": "弹奏", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用手指拨动琴弦或琴键，演奏乐器发出声音", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93915, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹 tán：用手指拨动琴弦或琴键，演奏乐器使其发声，是正确答案。"}, {"text": "毯", "is_correct": false, "explanation": "毯 tǎn（第三声）与 tán（第二声）声调不同，意思是毯子。"}, {"text": "探", "is_correct": false, "explanation": "探 tàn（第四声）与 tán（第二声）声调不同，意思是探望、探索。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tán 韵尾不同（ng 与 n），意思是糖。"}], "explanations": {"弹": "弹 tán：用手指拨动琴弦或琴键，演奏乐器使其发声，是正确答案。", "毯": "毯 tǎn（第三声）与 tán（第二声）声调不同，意思是毯子。", "探": "探 tàn（第四声）与 tán（第二声）声调不同，意思是探望、探索。", "糖": "táng 与 tán 韵尾不同（ng 与 n），意思是糖。"}, "sentence_index": null, "correct_answer": "弹"}, "level_3": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹：用手指拨动弦乐器，演奏吉他，正是这个义项。"}, {"text": "吹", "is_correct": false, "explanation": "搭配：“吹”用于管乐器，吉他是弦乐器，不能说吹吉他。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”多用于鼓、锣等，不用于吉他。"}, {"text": "写", "is_correct": false, "explanation": "语义：写是写字、作画，演奏吉他不能用写。"}], "explanations": {"弹": "弹：用手指拨动弦乐器，演奏吉他，正是这个义项。", "吹": "搭配：“吹”用于管乐器，吉他是弦乐器，不能说吹吉他。", "打": "搭配：“打”多用于鼓、锣等，不用于吉他。", "写": "语义：写是写字、作画，演奏吉他不能用写。"}, "sentence_index": 0, "correct_answer": "弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他会弹笛子，每天练习一个小时。", "explanation": "这里应该用〈吹〉。笛子是吹奏乐器，弹用于拨弦或按键乐器，不能用于笛子，要用吹。"}, {"text": "篮球弹得很高，大家都在看。", "explanation": "这里的弹是另一个义项，指物体借弹力跳起，与“拨动乐器发声”无关。"}, {"text": "他弹二胡，声音很悲伤。", "explanation": "这里应该用〈拉〉。二胡要用弓拉，弹指拨弦或按键，不能用于二胡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93915, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹 tán：用手指拨动琴弦或琴键，演奏乐器使其发声，是正确答案。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tán 韵尾不同（ng 与 n），意思是礼堂、厅堂。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 tán（第二声）声调不同，意思是摊位。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tán（第二声）声调不同，意思是贪心。"}], "explanations": {"弹": "弹 tán：用手指拨动琴弦或琴键，演奏乐器使其发声，是正确答案。", "堂": "táng 与 tán 韵尾不同（ng 与 n），意思是礼堂、厅堂。", "摊": "tān（第一声）与 tán（第二声）声调不同，意思是摊位。", "贪": "tān（第一声）与 tán（第二声）声调不同，意思是贪心。"}, "sentence_index": null, "correct_answer": "弹"}, "level_3": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹：用手指拨动琴弦演奏，正是这个义项。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬要用牙齿，人不能咬着琴发声，与“唱歌”的语境不合。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛出去，琴不能被扔着演奏，与语境不合。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：砍多指用刀斧劈断，不能用于演奏琴。"}], "explanations": {"弹": "弹：用手指拨动琴弦演奏，正是这个义项。", "咬": "语义：咬要用牙齿，人不能咬着琴发声，与“唱歌”的语境不合。", "扔": "语义：扔是抛出去，琴不能被扔着演奏，与语境不合。", "砍": "搭配：砍多指用刀斧劈断，不能用于演奏琴。"}, "sentence_index": 6, "correct_answer": "弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弹了一下锣，声音很响。", "explanation": "这里应该用〈敲〉。锣要敲击，弹指拨动或按键，不能用于锣。"}, {"text": "她弹着手鼓，唱起了歌。", "explanation": "这里应该用〈拍〉。手鼓要用手拍，弹指拨动或按键，不能用于手鼓。"}, {"text": "她弹着沙锤，跟着节奏走。", "explanation": "这里应该用〈摇〉。沙锤要摇，弹不能用于沙锤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93915, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他弹吉他得很好。", "corrected_sentence": "他弹吉他弹得很好。", "error_description": "错误形式：弹吉他得很好；正确形式：弹吉他弹得很好。带宾语的动词作程度补语时，动词要在“得”前再说一次，只说一个“弹”不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93915, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他弹了着吉他，轻轻地哼歌。", "corrected_sentence": "他弹着吉他，轻轻地哼歌。", "error_description": "错误形式：弹了着吉他；正确形式：弹着吉他。“了”和“着”不能同时用在同一个动词后面，表示动作持续要用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
