INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93916, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手指拨动或敲击，使发出声音；也指使物体跳起。", "primary_collocate": null, "pronunciation": "tán", "ipa": "tʰan˧˥", "syllable_count": 1, "sentences": [{"text": "篮球打在篮板上，弹了回来。", "target_word": "弹", "complexity_tier": "T3", "furigana": "lán qiú dǎ zài lán bǎn shàng, tán le huí lái.", "sentence_source": "generated"}, {"text": "她用手指弹了一下我的头。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小球掉在地上，又弹起来了。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "皮球落地后弹得很高。", "target_word": "弹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他用手指弹着桌面，发出清脆的声音。", "target_word": "弹", "complexity_tier": "T3", "furigana": "tā yòng shǒu zhǐ tán zhe zhuō miàn, fā chū qīng cuì de shēng yīn.", "sentence_source": "generated"}, {"text": "风把树枝吹弯了，松开后它又弹了回去。", "target_word": "弹", "complexity_tier": "T3", "furigana": "fēng bǎ shù zhī chuī wān le, sōng kāi hòu tā yòu tán le huí qù.", "sentence_source": "generated"}, {"text": "他轻轻弹了一下琴弦。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种橡胶很有弹性，压下去一松手就弹回来。", "target_word": "弹", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小球从高处掉下来，弹了好几次才停。", "target_word": "弹", "complexity_tier": "T3", "furigana": "xiǎo qiú cóng gāo chù diào xià lái, tán le hǎo jǐ cì cái tíng.", "sentence_source": "generated"}, {"text": "他弹了弹杯子，听里面有没有水。", "target_word": "弹", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹弹", "label": "重叠"}, {"form": "弹了", "label": "完成体"}, {"form": "弹起来", "label": "趋向"}], "register": "中性", "sense_fingerprint": "用手指拨动、敲击或轻弹，使发出声音或使东西跳起、掉落", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹 tán：用手指拨动或敲击，使发出声音，或使东西跳起，是正确答案。"}, {"text": "毯", "is_correct": false, "explanation": "毯 tǎn（第三声）与 tán（第二声）声调不同，意思是毯子。"}, {"text": "炭", "is_correct": false, "explanation": "炭 tàn（第四声）与 tán（第二声）声调不同，意思是木炭。"}, {"text": "糖", "is_correct": false, "explanation": "táng 与 tán 韵尾不同（ng 与 n），意思是糖。"}], "explanations": {"弹": "弹 tán：用手指拨动或敲击，使发出声音，或使东西跳起，是正确答案。", "毯": "毯 tǎn（第三声）与 tán（第二声）声调不同，意思是毯子。", "炭": "炭 tàn（第四声）与 tán（第二声）声调不同，意思是木炭。", "糖": "táng 与 tán 韵尾不同（ng 与 n），意思是糖。"}, "sentence_index": null, "correct_answer": "弹"}, "level_3": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹：篮球撞上篮板后反向弹回，正是这个义项。"}, {"text": "切", "is_correct": false, "explanation": "语义：切是用刀把东西分开，篮球不会被切开，与反弹回来的意思不合。"}, {"text": "抱", "is_correct": false, "explanation": "搭配：抱要求把东西搂在怀里，篮球撞击后不会被抱回来。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬要用牙齿，篮球不能咬，也就不会咬回来。"}], "explanations": {"弹": "弹：篮球撞上篮板后反向弹回，正是这个义项。", "切": "语义：切是用刀把东西分开，篮球不会被切开，与反弹回来的意思不合。", "抱": "搭配：抱要求把东西搂在怀里，篮球撞击后不会被抱回来。", "咬": "语义：咬要用牙齿，篮球不能咬，也就不会咬回来。"}, "sentence_index": 0, "correct_answer": "弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他从二楼弹了下来，还好没受伤。", "explanation": "这里应该用〈跳〉。弹指物体借弹力反跳，人主动从高处跳下要用跳。"}, {"text": "他把书弹给了同学。", "explanation": "这里应该用〈递〉。弹是拨动或借弹力反跳，把东西交给别人要用递。"}, {"text": "他不小心从楼梯上弹了下来，伤得不轻。", "explanation": "这里应该用〈摔〉。弹指物体借弹力反跳，人失足往下跌要用摔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93916, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹 tán：用手指拨动或敲击，使发出声音，或使东西跳起，是正确答案。"}, {"text": "堂", "is_correct": false, "explanation": "táng 与 tán 韵尾不同（ng 与 n），意思是礼堂、厅堂。"}, {"text": "摊", "is_correct": false, "explanation": "tān（第一声）与 tán（第二声）声调不同，意思是摊位。"}, {"text": "叹", "is_correct": false, "explanation": "tàn（第四声）与 tán（第二声）声调不同，意思是叹气。"}, {"text": "贪", "is_correct": false, "explanation": "tān（第一声）与 tán（第二声）声调不同，意思是贪心。"}], "explanations": {"弹": "弹 tán：用手指拨动或敲击，使发出声音，或使东西跳起，是正确答案。", "堂": "táng 与 tán 韵尾不同（ng 与 n），意思是礼堂、厅堂。", "摊": "tān（第一声）与 tán（第二声）声调不同，意思是摊位。", "叹": "tàn（第四声）与 tán（第二声）声调不同，意思是叹气。", "贪": "tān（第一声）与 tán（第二声）声调不同，意思是贪心。"}, "sentence_index": null, "correct_answer": "弹"}, "level_3": {"options": [{"text": "弹", "is_correct": true, "explanation": "弹：拨动琴弦使其发声，正是这个义项。"}, {"text": "砍", "is_correct": false, "explanation": "搭配：砍多指用刀斧猛力劈断，不能搭配“轻轻”和琴弦。"}, {"text": "锯", "is_correct": false, "explanation": "语义：锯是来回拉割木料，与“轻轻拨动琴弦”的意思不合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：踢要用脚，琴弦不能用脚去踢来发声，与语境不合。"}], "explanations": {"弹": "弹：拨动琴弦使其发声，正是这个义项。", "砍": "搭配：砍多指用刀斧猛力劈断，不能搭配“轻轻”和琴弦。", "锯": "语义：锯是来回拉割木料，与“轻轻拨动琴弦”的意思不合。", "踢": "语义：踢要用脚，琴弦不能用脚去踢来发声，与语境不合。"}, "sentence_index": 6, "correct_answer": "弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他蹲下来弹好了鞋带。", "explanation": "这里应该用〈系〉。弹指拨动或借弹力反跳，不能表示把鞋带打结系好，系鞋带要用系。"}, {"text": "他弹上了一块新手表。", "explanation": "这里应该用〈戴〉。弹不能表示把东西戴在身上，戴手表要用戴。"}, {"text": "她弹了一朵花送给妈妈。", "explanation": "这里应该用〈摘〉。弹是拨动或借弹力反跳，不能用来采花，采摘花朵要用摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "篮球落在地上后弹起了来。", "corrected_sentence": "篮球落在地上后弹了起来。", "error_description": "错误形式：弹起了来；正确形式：弹了起来。“起来”是趋向补语，不能拆开，完成的“了”要放在“弹”之后、“起来”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杯子轻轻弹着一下。", "corrected_sentence": "他把杯子轻轻弹了一下。", "error_description": "错误形式：“弹着一下”；正确形式：“弹了一下”。“着”表示动作持续的状态，与表示一次动作完成的动量补语“一下”不合，应用完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
