INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93925, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "晚安是晚上睡觉前说的话，希望你睡得好。", "primary_collocate": null, "pronunciation": "wǎn ān", "ipa": "wan˨˩˦ an˥˥", "syllable_count": 2, "sentences": [{"text": "我每天睡觉前都对妈妈说晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们向爸爸道了晚安，就去睡觉了。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打电话给女朋友，说了一声晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，我们互相说晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶亲了亲小孙子，轻轻说晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十点了，我给朋友发了一条晚安短信。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她关上灯，对我说了声晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在睡觉前总要跟家人说晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说完晚安，就关灯睡觉了。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天晚上，老师会在群里说晚安。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "睡觉前对人说晚安这个动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早安", "is_correct": false, "explanation": "搭配：“早安”指早上的问候，与“睡觉前”的语境不搭。"}, {"text": "早上好", "is_correct": false, "explanation": "语义：早上好是早上的问候，睡觉前说不合时间。"}, {"text": "晚安", "is_correct": true, "explanation": "正确：晚安是睡觉前对人说的道别语，句中“对妈妈说”的语境吻合。"}, {"text": "谎话", "is_correct": false, "explanation": "语义：对妈妈说谎话与睡觉前的道别无关，句意不合。"}], "explanations": {"早安": "搭配：“早安”指早上的问候，与“睡觉前”的语境不搭。", "早上好": "语义：早上好是早上的问候，睡觉前说不合时间。", "晚安": "正确：晚安是睡觉前对人说的道别语，句中“对妈妈说”的语境吻合。", "谎话": "语义：对妈妈说谎话与睡觉前的道别无关，句意不合。"}, "sentence_index": 0, "correct_answer": "晚安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上课时，老师对同学们说了一句晚安。", "explanation": "这里应该用〈同学们好〉。上课开始时的问候要说“同学们好”，“晚安”只用于睡前。"}, {"text": "早上起床时我们互相说晚安。", "explanation": "这里应该用〈早安〉。晚安只用于睡前，早上起床要说“早安”。"}, {"text": "见面时我们互相说晚安。", "explanation": "这里应该用〈问好〉。见面时要问好，晚安只用于睡前道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "午安", "is_correct": false, "explanation": "语义：午安是中午的问候，关灯睡觉时说不合时间。"}, {"text": "你好", "is_correct": false, "explanation": "语义：关灯时说“你好”不合语境，句意不通。"}, {"text": "好运", "is_correct": false, "explanation": "搭配：“说了声”后接好运不自然，应说“祝你好运”。"}, {"text": "晚安", "is_correct": true, "explanation": "正确：关灯后对人说的是晚安，与句中的“关上灯”吻合。"}], "explanations": {"午安": "语义：午安是中午的问候，关灯睡觉时说不合时间。", "你好": "语义：关灯时说“你好”不合语境，句意不通。", "好运": "搭配：“说了声”后接好运不自然，应说“祝你好运”。", "晚安": "正确：关灯后对人说的是晚安，与句中的“关上灯”吻合。"}, "sentence_index": 6, "correct_answer": "晚安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在饭店里碰杯时互相说晚安。", "explanation": "这里应该用〈干杯〉。碰杯时要说“干杯”，“晚安”只用于睡前道别。"}, {"text": "中午我们在食堂互相说晚安。", "explanation": "这里应该用〈午安〉。中午的问候要说“午安”，晚安只用于睡前。"}, {"text": "晚会开始时大家互相说晚安。", "explanation": "这里应该用〈晚上好〉。晚会开始时的问候是“晚上好”，晚安只用于睡前道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在门口对我说了个晚安，然后关上了门。", "corrected_sentence": "妈妈在门口对我说了声晚安，然后关上了门。", "error_description": "量词错误：“晚安”作为说的话，量词应用“声”，不能用“个”。正确说法是“说了声晚安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每晚都对我说早安。", "corrected_sentence": "他每晚都对我说晚安。", "error_description": "用词错误：“早安”是早上的问候，与“每晚都”睡前的语境不符，应为“晚安”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
