INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "夜晚睡觉前互相致意的问候语。", "primary_collocate": null, "pronunciation": "wǎn ān", "ipa": "wan˨˩˦ an˥˥", "syllable_count": 2, "sentences": [{"text": "“晚安！”妈妈说，“明天见。”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们，晚安，明天见！", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“晚安，好梦！”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，她给我发了一句“晚安”。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“晚安，宝贝！”爸爸关上了灯。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十一点了，我先睡了，大家晚安！", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话里，他轻轻地说：“晚安，早点睡。”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“晚安！”我挥挥手，回房间去了。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说：“晚安，同学们，明天见。”", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在朋友圈写了一句“晚安”，就睡了。", "target_word": "晚安", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "夜晚睡前互相致意的问候语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "早安", "is_correct": false, "explanation": "语义：早安是早上的问候，与“晚安！”的睡前语境不符。"}, {"text": "午安", "is_correct": false, "explanation": "语义：午安是中午的问候，与妈妈说“明天见”的睡前语境不符。"}, {"text": "你好", "is_correct": false, "explanation": "语义：“你好”是见面时的问候，与“明天见”的道别语境不合，不是睡前互相致意的用语。"}, {"text": "晚安", "is_correct": true, "explanation": "正确：晚安是夜晚睡前互相致意的问候语，与后文“明天见”呼应。"}], "explanations": {"早安": "语义：早安是早上的问候，与“晚安！”的睡前语境不符。", "午安": "语义：午安是中午的问候，与妈妈说“明天见”的睡前语境不符。", "你好": "语义：“你好”是见面时的问候，与“明天见”的道别语境不合，不是睡前互相致意的用语。", "晚安": "正确：晚安是夜晚睡前互相致意的问候语，与后文“明天见”呼应。"}, "sentence_index": 0, "correct_answer": "晚安"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "上午十点开会时，她说了一句晚安。", "explanation": "这里应该用〈大家好〉。开会时的问候要说“大家好”，“晚安”只用于夜晚睡前。"}, {"text": "早上她向我问了一句晚安。", "explanation": "这里应该用〈早安〉。早上的问候要用“早安”，“晚安”只用于夜晚睡前。"}, {"text": "见面时她向我说了一句晚安。", "explanation": "这里应该用〈你好〉。见面要说“你好”，“晚安”只用于夜晚睡前。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "您好", "is_correct": false, "explanation": "语域：对家人说“您好”过于客气，与睡前的口语语境不符。"}, {"text": "早上好", "is_correct": false, "explanation": "语义：早上好是早上的问候，与“早点睡”的睡前语境矛盾。"}, {"text": "大家好", "is_correct": false, "explanation": "语义：大家好是见面问候，与“早点睡”的语境不合。"}, {"text": "晚安", "is_correct": true, "explanation": "正确：晚安是睡前致意的问候语，与“早点睡”呼应。"}], "explanations": {"您好": "语域：对家人说“您好”过于客气，与睡前的口语语境不符。", "早上好": "语义：早上好是早上的问候，与“早点睡”的睡前语境矛盾。", "大家好": "语义：大家好是见面问候，与“早点睡”的语境不合。", "晚安": "正确：晚安是睡前致意的问候语，与“早点睡”呼应。"}, "sentence_index": 6, "correct_answer": "晚安"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动会开幕式上，队长对我们说了一句晚安。", "explanation": "这里应该用〈加油〉。运动会上为选手鼓劲要说“加油”，“晚安”只用于睡前问候。"}, {"text": "中午她向我说了一句晚安。", "explanation": "这里应该用〈午安〉。中午的问候要说“午安”，“晚安”只用于夜晚。"}, {"text": "晚会开始时她向大家说了一句晚安。", "explanation": "这里应该用〈晚上好〉。晚会开始时的问候是“晚上好”，“晚安”只用于睡前道别。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在门口轻轻说了一个“晚安”。", "corrected_sentence": "妈妈在门口轻轻说了一句“晚安”。", "error_description": "量词错误：“晚安”作为一句话，量词应用“句”，不能用“个”。正确说法是“一句晚安”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我对她说：“晚安着！”", "corrected_sentence": "我对她说：“晚安！”", "error_description": "体标错误：“着”只能附在动词或形容词之后，固定问候语“晚安”不能带“着”，应直接说“晚安！”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "示威是很多人站出来大声表示自己不同意。", "primary_collocate": null, "pronunciation": "shì wēi", "ipa": "ʂɨ˥˩ weɪ˥", "syllable_count": 2, "sentences": [{"text": "工人们在公司门口示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们为了反对涨价而示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多市民走上街头示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们站在广场上大声示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们去市政府前面示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机们因为工资太低，一起示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天下午，有人在大楼外示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们举着牌子，向政府示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们为了保护公园，天天示威。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家不满意这个决定，所以去示威了。", "target_word": "示威", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "示威者", "label": "复合"}, {"form": "示威游行", "label": "复合"}], "register": "中性", "sense_fingerprint": "许多人公开站出来，大声表示不同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1707862d-56f8-4d46-b687-e41761f8e4cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。"}, {"text": "视为", "is_correct": false, "explanation": "视为 的第二个音节是第二声 wéi，示威 是第一声 wēi，声调不同，意思是“当作”。"}, {"text": "市委", "is_correct": false, "explanation": "市委 的第二个音节是第三声 wěi，示威 是第一声 wēi，声调不同，意思是“市的党委”。"}, {"text": "世卫", "is_correct": false, "explanation": "世卫 的第二个音节是第四声 wèi，示威 是第一声 wēi，声调不同，意思是“世界卫生组织”的简称。"}], "explanations": {"示威": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。", "视为": "视为 的第二个音节是第二声 wéi，示威 是第一声 wēi，声调不同，意思是“当作”。", "市委": "市委 的第二个音节是第三声 wěi，示威 是第一声 wēi，声调不同，意思是“市的党委”。", "世卫": "世卫 的第二个音节是第四声 wèi，示威 是第一声 wēi，声调不同，意思是“世界卫生组织”的简称。"}, "sentence_index": null, "correct_answer": "示威"}, "level_3": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威：许多人公开站出来表示不同意，与“工人们在公司门口”的场景相符。"}, {"text": "飞", "is_correct": false, "explanation": "语义：人不能在公司门口“飞”，与“工人们”的动作不相符。"}, {"text": "送", "is_correct": false, "explanation": "语法：“送”是及物动词，须带宾语（送什么人或物），句中没有宾语，成分不完整。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水域，公司门口没有可以游泳的地方，语义不通。"}], "explanations": {"示威": "示威：许多人公开站出来表示不同意，与“工人们在公司门口”的场景相符。", "飞": "语义：人不能在公司门口“飞”，与“工人们”的动作不相符。", "送": "语法：“送”是及物动词，须带宾语（送什么人或物），句中没有宾语，成分不完整。", "游泳": "语义：“游泳”需要水域，公司门口没有可以游泳的地方，语义不通。"}, "sentence_index": 0, "correct_answer": "示威"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一个人在家里示威，没有人看见。", "explanation": "这里应该用〈发脾气〉。示威指多人公开站出来表示不同意，一个人在家里生气不能称为示威。"}, {"text": "大家都为他的成功示威。", "explanation": "这里应该用〈祝贺〉。示威表示不同意或抗议，不用来表示祝贺。"}, {"text": "他一直在图书馆里示威，写完了论文。", "explanation": "这里应该用〈写作〉。示威指为表达抗议或要求而集会游行，在图书馆里写论文不叫示威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。"}, {"text": "十位", "is_correct": false, "explanation": "十位 的两个音节声调都与示威 不同：shí 为第二声，wèi 为第四声，意思是“十位数字的位置”。"}, {"text": "实为", "is_correct": false, "explanation": "实为 的两个音节声调都与示威 不同：shí 为第二声，wéi 为第二声，意思是“实际上是”。"}, {"text": "施威", "is_correct": false, "explanation": "施威 的第一个音节是第一声 shī，示威 是第四声 shì，声调不同，意思是“施加威力”。"}], "explanations": {"示威": "示威 shì wēi 是正确答案，意思是许多人公开站出来，大声表示不同意。", "十位": "十位 的两个音节声调都与示威 不同：shí 为第二声，wèi 为第四声，意思是“十位数字的位置”。", "实为": "实为 的两个音节声调都与示威 不同：shí 为第二声，wéi 为第二声，意思是“实际上是”。", "施威": "施威 的第一个音节是第一声 shī，示威 是第四声 shì，声调不同，意思是“施加威力”。"}, "sentence_index": null, "correct_answer": "示威"}, "level_3": {"options": [{"text": "示威", "is_correct": true, "explanation": "示威：许多人公开站出来表示不同意，与“昨天下午，有人在大楼外”的语境相符。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，多用于尊贵的客人，用在这里语域不合。"}, {"text": "莅临", "is_correct": false, "explanation": "语域：“莅临”是书面敬语，用于描述普通人在大楼外的行为，语域不合。"}, {"text": "打烊", "is_correct": false, "explanation": "搭配：“打烊”多指商店收工，不用于描述“有人在大楼外”。"}], "explanations": {"示威": "示威：许多人公开站出来表示不同意，与“昨天下午，有人在大楼外”的语境相符。", "驾临": "语域：“驾临”是敬辞，多用于尊贵的客人，用在这里语域不合。", "莅临": "语域：“莅临”是书面敬语，用于描述普通人在大楼外的行为，语域不合。", "打烊": "搭配：“打烊”多指商店收工，不用于描述“有人在大楼外”。"}, "sentence_index": 6, "correct_answer": "示威"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们在教室里示威，聊得很开心。", "explanation": "这里应该用〈聊天〉。示威是为表达抗议或要求而集会游行，同学们在教室里聊天不叫示威。"}, {"text": "我周末去医院示威，祝朋友早日康复。", "explanation": "这里应该用〈探望〉。示威是为表达抗议或要求而集会游行，不用于去医院探望朋友。"}, {"text": "老师在办公室里示威，批改了三十份卷子。", "explanation": "这里应该用〈批改〉。示威指为表达抗议或要求而集会游行，在办公室批改卷子不叫示威。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们公司示威，要求涨工资。", "corrected_sentence": "工人们向公司示威，要求涨工资。", "error_description": "“示威”是不及物动词，其对象或地点须用介词引出（如“向公司示威”“在公司门口示威”）；漏掉介词后直接说“公司示威”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "同学们在校门口大声示威者。", "corrected_sentence": "同学们在校门口大声示威。", "error_description": "“示威”是动词，“示威者”是名词，这里应用动词“示威”，不能加“者”变成名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
