INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93943, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "秀是在大家面前表演，让大家看。", "primary_collocate": null, "pronunciation": "xiù", "ipa": "ɕi̯oʊ˥˩", "syllable_count": 1, "sentences": [{"text": "他在大家面前秀了一段舞。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明想在同学面前秀一下他的新手机。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在朋友面前秀自己的新裙子。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别在我面前秀你的成绩了。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在网上秀过自己做的蛋糕。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在晚会上秀自己的才艺。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王爱在邻居面前秀他的新车。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把画拿到班上秀给同学看。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在客人面前秀了一个新本领。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在老师面前秀一秀自己的中文。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "秀了", "label": "体标"}, {"form": "秀过", "label": "体标"}, {"form": "秀一下", "label": "动量"}], "register": "口语", "sense_fingerprint": "动词：在众人面前表演、展示给大家看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀 xiù：在众人面前表演或展示，让大家看，是正确答案。"}, {"text": "修", "is_correct": false, "explanation": "修 xiū（第一声）与 xiù（第四声）声调不同，意思是修理。"}, {"text": "羞", "is_correct": false, "explanation": "xiū（第一声）与 xiù（第四声）声调不同，意思是害羞。"}, {"text": "旧", "is_correct": false, "explanation": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是旧的。"}], "explanations": {"秀": "秀 xiù：在众人面前表演或展示，让大家看，是正确答案。", "修": "修 xiū（第一声）与 xiù（第四声）声调不同，意思是修理。", "羞": "xiū（第一声）与 xiù（第四声）声调不同，意思是害羞。", "旧": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是旧的。"}, "sentence_index": null, "correct_answer": "秀"}, "level_3": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀：在大家面前表演，让人看，正是这个义项。"}, {"text": "藏", "is_correct": false, "explanation": "语义：藏是隐藏起来，与“在大家面前”的展示相反。"}, {"text": "抢", "is_correct": false, "explanation": "搭配：抢多用于抢夺东西，不能搭配舞蹈。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔是抛出去，舞蹈不能被扔出去，与语境不合。"}], "explanations": {"秀": "秀：在大家面前表演，让人看，正是这个义项。", "藏": "语义：藏是隐藏起来，与“在大家面前”的展示相反。", "抢": "搭配：抢多用于抢夺东西，不能搭配舞蹈。", "扔": "语义：扔是抛出去，舞蹈不能被扔出去，与语境不合。"}, "sentence_index": 0, "correct_answer": "秀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把日记秀在抽屉里。", "explanation": "这里应该用〈隐藏〉。秀是把东西展示出来给人看，与把日记藏起来的意思正相反，不能用于藏东西。"}, {"text": "他把门秀开了，走了出去。", "explanation": "这里应该用〈打开〉。秀是在人前展示或表演，不表示开门，要用打开。"}, {"text": "他在地上秀了一个坑。", "explanation": "这里应该用〈挖〉。秀是在人前展示或表演，不表示挖掘，要用挖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93943, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀 xiù：在众人面前表演或展示，让大家看，是正确答案。"}, {"text": "休", "is_correct": false, "explanation": "xiū（第一声）与 xiù（第四声）声调不同，意思是休息。"}, {"text": "就", "is_correct": false, "explanation": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是就、马上。"}, {"text": "戏", "is_correct": false, "explanation": "xì 比 xiù 少了韵母中的 u，意思是戏剧。"}], "explanations": {"秀": "秀 xiù：在众人面前表演或展示，让大家看，是正确答案。", "休": "xiū（第一声）与 xiù（第四声）声调不同，意思是休息。", "就": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是就、马上。", "戏": "xì 比 xiù 少了韵母中的 u，意思是戏剧。"}, "sentence_index": null, "correct_answer": "秀"}, "level_3": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀：在邻居面前展示自己的新车，正是这个义项。"}, {"text": "砸", "is_correct": false, "explanation": "语义：砸是打坏东西，与“爱在邻居面前展示”的语境相反。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：喝用于饮品，不能搭配汽车。"}, {"text": "撞", "is_correct": false, "explanation": "语义：撞是碰撞出事，与“爱在邻居面前展示”的语境不合。"}], "explanations": {"秀": "秀：在邻居面前展示自己的新车，正是这个义项。", "砸": "语义：砸是打坏东西，与“爱在邻居面前展示”的语境相反。", "喝": "搭配：喝用于饮品，不能搭配汽车。", "撞": "语义：撞是碰撞出事，与“爱在邻居面前展示”的语境不合。"}, "sentence_index": 6, "correct_answer": "秀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "校长在大会上秀了放假的消息。", "explanation": "这里应该用〈宣布〉。秀带有炫示或表演的意思，不能用于正式宣告消息，要用宣布。"}, {"text": "这个仪表秀了当前的温度。", "explanation": "这里应该用〈显示〉。秀指刻意展示给人看，仪表的读数要用显示。"}, {"text": "政府秀了新的法律。", "explanation": "这里应该用〈颁布〉。秀不能用于公布法律，法律的正式公布要用颁布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在朋友面前秀了过他的新表。", "corrected_sentence": "他在朋友面前秀过他的新表。", "error_description": "错误形式：秀了过；正确形式：秀过。经历体“过”前面不能再加“了”，两者不能叠用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把照片秀邻居看。", "corrected_sentence": "妈妈把照片秀给邻居看。", "error_description": "错误形式：秀邻居看；正确形式：秀给邻居看。“秀”后面引出观看的对象要用介词“给”，直接说“秀邻居看”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
