INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表演；演出。", "primary_collocate": null, "pronunciation": "xiù", "ipa": "ɕi̯oʊ˥˩", "syllable_count": 1, "sentences": [{"text": "昨晚我和朋友一起去看了一场秀。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场秀的灯光很漂亮。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的秀几点开始？", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们买了票，明天去看秀。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秀开始前，大家都安静下来。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那场秀太精彩了，观众一直鼓掌。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每个周末都在剧场里办一场秀。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的秀要用很多灯，工人正在准备。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有票，所以不能看今晚的秀。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秀很长，我们看了两个小时。", "target_word": "秀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "时装秀", "label": "复合"}, {"form": "做秀", "label": "复合"}], "register": "口语", "sense_fingerprint": "名词：一场供人观看的表演、演出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀 xiù：供人观看的表演或演出，是正确答案。"}, {"text": "修", "is_correct": false, "explanation": "xiū（第一声）与 xiù（第四声）声调不同，意思是修理。"}, {"text": "旧", "is_correct": false, "explanation": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是旧的。"}, {"text": "戏", "is_correct": false, "explanation": "xì 比 xiù 少了韵母中的 u，意思是戏剧。"}], "explanations": {"秀": "秀 xiù：供人观看的表演或演出，是正确答案。", "修": "xiū（第一声）与 xiù（第四声）声调不同，意思是修理。", "旧": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是旧的。", "戏": "xì 比 xiù 少了韵母中的 u，意思是戏剧。"}, "sentence_index": null, "correct_answer": "秀"}, "level_3": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀：供人观看的表演，看了一场秀，正是这个义项。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭是吃的，不能用来观看，与“看了一场”不合。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：歌多用“听”，不能说看了一场歌。"}, {"text": "书", "is_correct": false, "explanation": "搭配：看书用“一本”，不说“一场”，也不能说看了一场书。"}], "explanations": {"秀": "秀：供人观看的表演，看了一场秀，正是这个义项。", "饭": "语义：饭是吃的，不能用来观看，与“看了一场”不合。", "歌": "搭配：歌多用“听”，不能说看了一场歌。", "书": "搭配：看书用“一本”，不说“一场”，也不能说看了一场书。"}, "sentence_index": 0, "correct_answer": "秀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们在球场上踢了一场秀，观众很多。", "explanation": "这里应该用〈比赛〉。秀指表演性的演出，不指竞技比赛。"}, {"text": "他们在会议室里进行了一场秀，讨论了预算。", "explanation": "这里应该用〈会议〉。秀指供人观看的表演，讨论预算要用会议。"}, {"text": "这次地震的秀很大。", "explanation": "这里应该用〈损失〉。秀是表演演出，不能用于地震造成的损失，要用损失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93944, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀 xiù：供人观看的表演或演出，是正确答案。"}, {"text": "休", "is_correct": false, "explanation": "xiū（第一声）与 xiù（第四声）声调不同，意思是休息。"}, {"text": "就", "is_correct": false, "explanation": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是就、马上。"}, {"text": "羞", "is_correct": false, "explanation": "xiū（第一声）与 xiù（第四声）声调不同，意思是害羞。"}], "explanations": {"秀": "秀 xiù：供人观看的表演或演出，是正确答案。", "休": "xiū（第一声）与 xiù（第四声）声调不同，意思是休息。", "就": "jiù（第四声）与 xiù 声母不同（j 与 x），意思是就、马上。", "羞": "xiū（第一声）与 xiù（第四声）声调不同，意思是害羞。"}, "sentence_index": null, "correct_answer": "秀"}, "level_3": {"options": [{"text": "秀", "is_correct": true, "explanation": "秀：在剧场里办的表演，办一场秀，正是这个义项。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：办多用于活动、会议，不能说办一场雨。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是照明用的，不能被办，与“剧场表演”的语境不合。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜是吃的，不能在剧场里办一场，与语境不合。"}], "explanations": {"秀": "秀：在剧场里办的表演，办一场秀，正是这个义项。", "雨": "搭配：办多用于活动、会议，不能说办一场雨。", "灯": "语义：灯是照明用的，不能被办，与“剧场表演”的语境不合。", "菜": "语义：菜是吃的，不能在剧场里办一场，与语境不合。"}, "sentence_index": 6, "correct_answer": "秀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块秀很硬，切不动。", "explanation": "这里应该用〈肉〉。秀指表演，不能形容可以切的食材，要用肉。"}, {"text": "他按时交了秀。", "explanation": "这里应该用〈作业〉。秀指表演演出，不能像作业那样交给老师。"}, {"text": "这个秀收了三万个词。", "explanation": "这里应该用〈字典〉。秀指表演演出，不能用于收录词语的工具书，要用字典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一共办了三只秀。", "corrected_sentence": "他们一共办了三场秀。", "error_description": "错误形式：三只秀；正确形式：三场秀。“秀”是表演、演出，要用“场”来计量，“只”一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看过一场很好看地秀。", "corrected_sentence": "我看过一场很好看的秀。", "error_description": "错误形式：很好看地秀；正确形式：很好看的秀。修饰名词要用结构助词“的”，“地”用于修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
