INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93945, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "管辖是一个人或一个地方的官管着另一些地方和人。", "primary_collocate": null, "pronunciation": "guǎn xiá", "ipa": "kwan˨˩ ɕja˧˥", "syllable_count": 2, "sentences": [{"text": "古时候，县官管辖一个县。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位大官管辖很多地方。", "target_word": "管辖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "皇帝派他去管辖南方。", "target_word": "管辖", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小城由一位官员管辖。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "以前这些村子都归县官管辖。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他管辖的地方很远，路也很难走。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位将军管辖着五个城。", "target_word": "管辖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管辖这个镇的官员很爱帮助百姓。", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听说他管辖过很多人。", "target_word": "管辖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市由哪位官员管辖？", "target_word": "管辖", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "管辖着", "label": "体标"}, {"form": "管辖过", "label": "体标"}, {"form": "管辖权", "label": "复合"}, {"form": "管轄", "label": "繁体"}], "register": "书面", "sense_fingerprint": "官员管着某些地方和那里的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1707862d-56f8-4d46-b687-e41761f8e4cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管辖", "is_correct": true, "explanation": "正确。古时候县官统辖一个县，就是“管辖”。"}, {"text": "毕业", "is_correct": false, "explanation": "配价：“毕业”的宾语须是学校，不能用于“一个县”。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指给动物或幼儿喂食，不能用于县。"}, {"text": "缝补", "is_correct": false, "explanation": "语义：“缝补”指用针线修补衣物，与县官的职责无关。"}], "explanations": {"管辖": "正确。古时候县官统辖一个县，就是“管辖”。", "毕业": "配价：“毕业”的宾语须是学校，不能用于“一个县”。", "喂养": "语义：“喂养”指给动物或幼儿喂食，不能用于县。", "缝补": "语义：“缝补”指用针线修补衣物，与县官的职责无关。"}, "sentence_index": 0, "correct_answer": "管辖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父亲管辖儿子。", "explanation": "这里应该用〈管教〉。“管辖”针对地区和职权范围，教育子女要用“管教”。"}, {"text": "医生管辖病人。", "explanation": "这里应该用〈诊治〉。“管辖”不用于治疗病人，医生的工作要用“诊治”。"}, {"text": "厨师管辖菜肴。", "explanation": "这里应该用〈烹饪〉。“管辖”指统辖地区或事务，做菜要用“烹饪”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管辖", "is_correct": true, "explanation": "正确。将军统辖着五个城，就是“管辖”。"}, {"text": "生产", "is_correct": false, "explanation": "语义：“生产”指制造产品，城市不能被生产。"}, {"text": "栽培", "is_correct": false, "explanation": "语义：“栽培”指培育植物，不能用于城。"}, {"text": "乘坐", "is_correct": false, "explanation": "配价：“乘坐”的宾语须是交通工具，不能是“五个城”。"}], "explanations": {"管辖": "正确。将军统辖着五个城，就是“管辖”。", "生产": "语义：“生产”指制造产品，城市不能被生产。", "栽培": "语义：“栽培”指培育植物，不能用于城。", "乘坐": "配价：“乘坐”的宾语须是交通工具，不能是“五个城”。"}, "sentence_index": 6, "correct_answer": "管辖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "园丁管辖花草。", "explanation": "这里应该用〈修剪〉。“管辖”指统辖地区或职权范围，修整花草要用“修剪”。"}, {"text": "图书管理员管辖图书。", "explanation": "这里应该用〈整理〉。“管辖”不用于书籍的摆放，整理图书要用“整理”。"}, {"text": "司机管辖汽车。", "explanation": "这里应该用〈驾驶〉。“管辖”不能用于开车，驾驶汽车要用“驾驶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县令管辖着过这个县。", "corrected_sentence": "县令管辖过这个县。", "error_description": "体标错误：“着”与“过”不能叠用在“管辖”之后。应只用经历体“过”，说“管辖过这个县”，错误形式“管辖着过”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一位官员管辖。", "corrected_sentence": "一位官员管辖这座城市。", "error_description": "配价错误：“管辖”是及物动词，必须带出管辖的对象。错误形式“一位官员管辖”缺少宾语，应说“一位官员管辖这座城市”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
