INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "总数是把所有的加在一起得到的数。", "primary_collocate": null, "pronunciation": "zǒng shù", "ipa": "tsʊŋ˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这个班的学生总数是三十人。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你算一下总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先把每天的钱加起来，看看总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的总数比我想的多。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些书的总数是五十本。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三个人的苹果总数是十二个。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把所有分数加在一起，就是总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总数不对，我们再数一遍。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的花费总数很高。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的人，总数有一百个。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把各部分加在一起得到的数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1707862d-56f8-4d46-b687-e41761f8e4cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93949, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。总数指全部加起来的数目。"}, {"text": "总是", "is_correct": false, "explanation": "shì（韵母 i）与 shù（韵母 u）韵母不同，意思是“一直、经常”，不是加起来的数。"}, {"text": "种树", "is_correct": false, "explanation": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“栽种树木”。"}, {"text": "棕树", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“棕榈树”。"}], "explanations": {"总数": "正确。总数指全部加起来的数目。", "总是": "shì（韵母 i）与 shù（韵母 u）韵母不同，意思是“一直、经常”，不是加起来的数。", "种树": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“栽种树木”。", "棕树": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“棕榈树”。"}, "sentence_index": null, "correct_answer": "总数"}, "level_3": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。“总数”指班级人数的合计，可以是三十人。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指每个人的岁数，不是班级人数的合计。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习表现的分数，与班级的人数无关。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”是钱款，不能用“三十人”来计量。"}], "explanations": {"总数": "正确。“总数”指班级人数的合计，可以是三十人。", "年龄": "语义：“年龄”指每个人的岁数，不是班级人数的合计。", "成绩": "语义：“成绩”指学习表现的分数，与班级的人数无关。", "学费": "搭配：“学费”是钱款，不能用“三十人”来计量。"}, "sentence_index": 0, "correct_answer": "总数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的总数是三十度。", "explanation": "这里应该用〈温度〉。“总数”指个数的合计，“三十度”是温度，要用“温度”来说。"}, {"text": "这袋大米的总数有五十公斤。", "explanation": "这里应该用〈总量〉。公斤是重量单位，“总数”只用于可以一个个数的东西，重量要用“总量”。"}, {"text": "他的心情总数很好。", "explanation": "这里误把〈总数〉当成了〈总体〉的意思（整体状态）。“总数”只指加起来的数目，“心情”不能数，应直接说“他的心情很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93949, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。总数指全部加起来的数目。"}, {"text": "综述", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。"}, {"text": "种数", "is_correct": false, "explanation": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“物种的数目”。"}, {"text": "总序", "is_correct": false, "explanation": "xù（声母 x）与 shù（声母 sh）声母不同，意思是“书前的总序言”。"}], "explanations": {"总数": "正确。总数指全部加起来的数目。", "综述": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。", "种数": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“物种的数目”。", "总序": "xù（声母 x）与 shù（声母 sh）声母不同，意思是“书前的总序言”。"}, "sentence_index": null, "correct_answer": "总数"}, "level_3": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。把所有分数加在一起得到的就是总数。"}, {"text": "分数线", "is_correct": false, "explanation": "语义：“分数线”是录取或及格的标准分数，把所有分数加在一起不会得到“分数线”。"}, {"text": "平均数", "is_correct": false, "explanation": "语义：平均数要把总数除以个数，加在一起的结果不是平均数。"}, {"text": "名次", "is_correct": false, "explanation": "语义：“名次”是排列的位置，不是把分数加起来得到的数。"}], "explanations": {"总数": "正确。把所有分数加在一起得到的就是总数。", "分数线": "语义：“分数线”是录取或及格的标准分数，把所有分数加在一起不会得到“分数线”。", "平均数": "语义：平均数要把总数除以个数，加在一起的结果不是平均数。", "名次": "语义：“名次”是排列的位置，不是把分数加起来得到的数。"}, "sentence_index": 6, "correct_answer": "总数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场比赛的总数是九十分钟。", "explanation": "这里应该用〈时长〉。“总数”指个数的合计，时间长短要用“时长”。"}, {"text": "他这次考试的总数是九十分。", "explanation": "这里应该用〈总分〉。分数的合计要说“总分”，“总数”指的是个数。"}, {"text": "这条路的总数是三公里。", "explanation": "这里应该用〈距离〉。路程的长短不能用“总数”，要用“距离”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一个一个地数完，算出了一总数。", "corrected_sentence": "我们一个一个地数完，算出了总数。", "error_description": "数量词错误：“一”后面缺少量词，且“总数”前不能直接加数词“一”。多出的“一”应删去，说“算出了总数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次调查的回答总数是三百本。", "corrected_sentence": "这次调查的回答总数是三百份。", "error_description": "量词错误：“回答”计数应用“份”或“个”，“本”只用于书册。错误形式“三百本”，应改为“三百份”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
