INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "全部加起来的数目。", "primary_collocate": null, "pronunciation": "zǒng shù", "ipa": "tsʊŋ˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这家店今年卖出的书，总数是两千本。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车票的总数已经超过了一万张。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全班同学的作业总数是四十份。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请告诉我客人的总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年游客的总数比今年少。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里鱼的总数一直在减少。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道这片森林里的树的总数吗？", "target_word": "总数", "complexity_tier": "T3", "furigana": "nǐ zhī dào zhè piàn sēn lín lǐ de shù de zǒng shù ma", "sentence_source": "generated"}, {"text": "所有国家的人口总数很大。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写了题目的总数。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些东西的总数不到一百。", "target_word": "总数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全部合计起来的数目", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1707862d-56f8-4d46-b687-e41761f8e4cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。总数指全部合计起来的数目。"}, {"text": "综述", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。"}, {"text": "种数", "is_correct": false, "explanation": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“物种的数目”。"}, {"text": "总序", "is_correct": false, "explanation": "xù（声母 x）与 shù（声母 sh）声母不同，意思是“书前的总序言”。"}], "explanations": {"总数": "正确。总数指全部合计起来的数目。", "综述": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“概括性的论述”。", "种数": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“物种的数目”。", "总序": "xù（声母 x）与 shù（声母 sh）声母不同，意思是“书前的总序言”。"}, "sentence_index": null, "correct_answer": "总数"}, "level_3": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。“总数”指卖出的书加起来的数目，是两千本。"}, {"text": "利润", "is_correct": false, "explanation": "语义：“利润”指卖书后赚得的钱，不是卖出书的数目。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”是钱款，不能用“两千本”来计量。"}, {"text": "页数", "is_correct": false, "explanation": "语义：“页数”指书有多少页，不是卖出的本数。"}], "explanations": {"总数": "正确。“总数”指卖出的书加起来的数目，是两千本。", "利润": "语义：“利润”指卖书后赚得的钱，不是卖出书的数目。", "价格": "搭配：“价格”是钱款，不能用“两千本”来计量。", "页数": "语义：“页数”指书有多少页，不是卖出的本数。"}, "sentence_index": 0, "correct_answer": "总数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个人的总数是一百八十厘米。", "explanation": "这里应该用〈身高〉。“总数”指个数的合计，人的高矮要用“身高”来说。"}, {"text": "这箱苹果的总数有十公斤。", "explanation": "这里应该用〈总量〉。公斤是重量单位，“总数”只用于可以一个个数的东西，重量要用“总量”。"}, {"text": "他的友谊总数很深。", "explanation": "这里误把〈总数〉当成了〈总体〉的意思（整体程度）。“总数”只指加起来的数目，“友谊”不能数，应说“友谊很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。总数指全部合计起来的数目。"}, {"text": "总是", "is_correct": false, "explanation": "shì（韵母 i）与 shù（韵母 u）韵母不同，意思是“一直、经常”。"}, {"text": "种树", "is_correct": false, "explanation": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“栽种树木”。"}, {"text": "棕树", "is_correct": false, "explanation": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“棕榈树”。"}], "explanations": {"总数": "正确。总数指全部合计起来的数目。", "总是": "shì（韵母 i）与 shù（韵母 u）韵母不同，意思是“一直、经常”。", "种树": "zhǒng（声母 zh）与 zǒng（声母 z）声母不同，意思是“栽种树木”。", "棕树": "zōng（第一声）与 zǒng（第三声）声调不同，意思是“棕榈树”。"}, "sentence_index": null, "correct_answer": "总数"}, "level_3": {"options": [{"text": "总数", "is_correct": true, "explanation": "正确。“总数”指树的数目的合计。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是付给人的报酬，树不领工资。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：“成绩”指学习或比赛的结果，不能用于树。"}, {"text": "学费", "is_correct": false, "explanation": "语义：“学费”是交给学校的钱，树不交学费，句子不通。"}], "explanations": {"总数": "正确。“总数”指树的数目的合计。", "工资": "语义：“工资”是付给人的报酬，树不领工资。", "成绩": "语义：“成绩”指学习或比赛的结果，不能用于树。", "学费": "语义：“学费”是交给学校的钱，树不交学费，句子不通。"}, "sentence_index": 6, "correct_answer": "总数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份饭的总数是八百大卡。", "explanation": "这里应该用〈热量〉。“总数”指个数的合计，热量的多少要用“热量”来说。"}, {"text": "这块地的总数是五亩。", "explanation": "这里应该用〈面积〉。“总数”只用于可以数的东西，土地大小要用“面积”。"}, {"text": "汽车的总数是一百公里每小时。", "explanation": "这里应该用〈速度〉。“总数”指个数的合计，车行的快慢要用“速度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们算出了全部客人的一总数。", "corrected_sentence": "我们算出了全部客人的总数。", "error_description": "数量词错误：“总数”前不能直接加数词“一”，多出的“一”应删去，说“算出了全部客人的总数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这所学校的毕业生总数是三百本。", "corrected_sentence": "这所学校的毕业生总数是三百人。", "error_description": "量词错误：“毕业生”是人，计数应用“人”，不能用“本”。错误形式“三百本”，应改为“三百人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
