INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93951, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "舞是跟着音乐做的好看的手脚动作。", "primary_collocate": null, "pronunciation": "wǔ", "ipa": "u˨˩˦", "syllable_count": 1, "sentences": [{"text": "她跳了一支舞。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支舞很好看。", "target_word": "舞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈教我这段舞。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的舞跳得很好。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学这支舞。", "target_word": "舞", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "台上有人跳着一支舞。", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为大家跳了一段舞。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支舞的动作很慢。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哥哥跳的舞，我也想学。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看过这支舞吗？", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "跳舞", "label": "复合"}, {"form": "舞蹈", "label": "复合"}], "register": "中性", "sense_fingerprint": "跟着音乐做的好看的手脚动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6d9584a-0189-4503-ada2-5a16c38af2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93951, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞（wǔ）：跟着音乐做的好看的手脚动作，是正确答案。"}, {"text": "无", "is_correct": false, "explanation": "无（wú，第二声）与舞（wǔ，第三声）声调不同，意思是没有。"}, {"text": "雾", "is_correct": false, "explanation": "雾（wù，第四声）与舞（wǔ，第三声）声调不同，意思是雾气。"}, {"text": "虎", "is_correct": false, "explanation": "虎（hǔ）与舞（wǔ）声母不同，意思是老虎。"}, {"text": "母", "is_correct": false, "explanation": "母（mǔ）与舞（wǔ）声母不同，意思是母亲。"}, {"text": "土", "is_correct": false, "explanation": "土（tǔ）与舞（wǔ）声母不同，意思是泥土。"}], "explanations": {"舞": "舞（wǔ）：跟着音乐做的好看的手脚动作，是正确答案。", "无": "无（wú，第二声）与舞（wǔ，第三声）声调不同，意思是没有。", "雾": "雾（wù，第四声）与舞（wǔ，第三声）声调不同，意思是雾气。", "虎": "虎（hǔ）与舞（wǔ）声母不同，意思是老虎。", "母": "母（mǔ）与舞（wǔ）声母不同，意思是母亲。", "土": "土（tǔ）与舞（wǔ）声母不同，意思是泥土。"}, "sentence_index": null, "correct_answer": "舞"}, "level_3": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞：“跳了一支舞”是固定搭配，“跳”的对象是舞蹈。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：“跳”不接“歌”，唱歌要说“唱”。"}, {"text": "枪", "is_correct": false, "explanation": "语义：枪不能被跳，与“跳”的动作不相容。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能被跳，与“跳”的动作不相容。"}], "explanations": {"舞": "舞：“跳了一支舞”是固定搭配，“跳”的对象是舞蹈。", "歌": "搭配：“跳”不接“歌”，唱歌要说“唱”。", "枪": "语义：枪不能被跳，与“跳”的动作不相容。", "花": "语义：花不能被跳，与“跳”的动作不相容。"}, "sentence_index": 0, "correct_answer": "舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在台上跳了一只舞，大家都在鼓掌。", "explanation": "这里应该用〈支〉或〈段〉。“只”用于动物或单个物件，不用来量舞蹈。"}, {"text": "他很会吃舞，大家都笑了。", "explanation": "这里应该用〈饭〉。“吃”接“饭”，不能接“舞”，舞要说“跳”。"}, {"text": "他很会弹舞，大家都很惊讶。", "explanation": "这里应该用〈钢琴〉。“弹”接乐器，不能接“舞”，舞要说“跳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93951, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞（wǔ）：跟着音乐做的好看的手脚动作，是正确答案。"}, {"text": "府", "is_correct": false, "explanation": "府（fǔ）与舞（wǔ）声母不同，如“政府”的“府”，意思是官府。"}, {"text": "苦", "is_correct": false, "explanation": "苦（kǔ）与舞（wǔ）声母不同，意思是味道或感受不好。"}, {"text": "误", "is_correct": false, "explanation": "误（wù，第四声）与舞（wǔ，第三声）声调不同，意思是错误。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ）与舞（wǔ）韵母不同（ü与u），意思是雨水。"}, {"text": "物", "is_correct": false, "explanation": "物（wù，第四声）与舞（wǔ，第三声）声调不同，意思是东西。"}], "explanations": {"舞": "舞（wǔ）：跟着音乐做的好看的手脚动作，是正确答案。", "府": "府（fǔ）与舞（wǔ）声母不同，如“政府”的“府”，意思是官府。", "苦": "苦（kǔ）与舞（wǔ）声母不同，意思是味道或感受不好。", "误": "误（wù，第四声）与舞（wǔ，第三声）声调不同，意思是错误。", "雨": "雨（yǔ）与舞（wǔ）韵母不同（ü与u），意思是雨水。", "物": "物（wù，第四声）与舞（wǔ，第三声）声调不同，意思是东西。"}, "sentence_index": null, "correct_answer": "舞"}, "level_3": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞：“跳一段舞”是搭配，“跳”的对象是舞蹈。"}, {"text": "戏", "is_correct": false, "explanation": "搭配：“跳”不接“戏”，演戏要说“演”。"}, {"text": "路", "is_correct": false, "explanation": "搭配：“跳”不能接“路”，走路才说“一段路”。"}, {"text": "梦", "is_correct": false, "explanation": "语义：梦不能被跳，与“跳”的动作不相容。"}], "explanations": {"舞": "舞：“跳一段舞”是搭配，“跳”的对象是舞蹈。", "戏": "搭配：“跳”不接“戏”，演戏要说“演”。", "路": "搭配：“跳”不能接“路”，走路才说“一段路”。", "梦": "语义：梦不能被跳，与“跳”的动作不相容。"}, "sentence_index": 6, "correct_answer": "舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在晚会上唱了一支舞，朋友们都笑了。", "explanation": "这里应该用〈歌〉。“唱”接“歌”，不接“舞”，“舞”要说“跳”。"}, {"text": "他站在舞上，大家都在看他。", "explanation": "这里应该用〈舞台〉。“站在……上”要说表示场所的“舞台”，“舞”不能表示场所。"}, {"text": "她跟着音乐踩着舞，一步一步地转圈。", "explanation": "这里应该用〈舞步〉。“踩”接“步”，不能踩“舞”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET conten