INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93951, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她跳了一只好看的舞，大家都鼓掌。", "corrected_sentence": "她跳了一支好看的舞，大家都鼓掌。", "error_description": "量词错误：“舞”应用量词“支”，不能用“只”。错误形式是“一只好看的舞”，正确形式是“一支好看的舞”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93951, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们跳了一首很美的舞，观众都很喜欢。", "corrected_sentence": "他们跳了一段很美的舞，观众都很喜欢。", "error_description": "量词错误：“舞”应用“段”，“首”用于歌曲或诗词，不用来量舞蹈。错误形式是“一首很美的舞”，正确形式是“一段很美的舞”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
