INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "有节奏地舞动身体的艺术形式。", "primary_collocate": null, "pronunciation": "wǔ", "ipa": "u˨˩˦", "syllable_count": 1, "sentences": [{"text": "歌和舞，她都很喜欢。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场表演有歌，也有舞。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想用舞说出自己的心情。", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段舞很有节奏。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的舞里有很多故事。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的舞很有力量。", "target_word": "舞", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "舞需要身体和音乐一起动。", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着台上的舞，一直笑。", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的舞让大家忘了时间。", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得舞是一种好看的艺术。", "target_word": "舞", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "段", "label": "量词"}, {"form": "跳舞", "label": "复合"}, {"form": "舞蹈", "label": "复合"}], "register": "中性", "sense_fingerprint": "有节奏地舞动身体的艺术形式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6d9584a-0189-4503-ada2-5a16c38af2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93952, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞（wǔ）：有节奏地舞动身体的艺术，是正确答案。"}, {"text": "误", "is_correct": false, "explanation": "误（wù，第四声）与舞（wǔ，第三声）声调不同，意思是错误。"}, {"text": "府", "is_correct": false, "explanation": "府（fǔ）与舞（wǔ）声母不同，如“政府”的“府”，意思是官府。"}, {"text": "苦", "is_correct": false, "explanation": "苦（kǔ）与舞（wǔ）声母不同，意思是味道或感受不好。"}, {"text": "土", "is_correct": false, "explanation": "土（tǔ）与舞（wǔ）声母不同，意思是泥土。"}], "explanations": {"舞": "舞（wǔ）：有节奏地舞动身体的艺术，是正确答案。", "误": "误（wù，第四声）与舞（wǔ，第三声）声调不同，意思是错误。", "府": "府（fǔ）与舞（wǔ）声母不同，如“政府”的“府”，意思是官府。", "苦": "苦（kǔ）与舞（wǔ）声母不同，意思是味道或感受不好。", "土": "土（tǔ）与舞（wǔ）声母不同，意思是泥土。"}, "sentence_index": null, "correct_answer": "舞"}, "level_3": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞：“歌和舞”是并列的两种艺术，这里指舞蹈艺术。"}, {"text": "病", "is_correct": false, "explanation": "语义：“病”不是可以并列喜欢的艺术活动，与“歌和……”不协调。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是艺术活动，与“歌”并列不协调。"}, {"text": "作业", "is_correct": false, "explanation": "语义：“作业”不是可以一起喜欢的东西，与“都很喜欢”不协调。"}], "explanations": {"舞": "舞：“歌和舞”是并列的两种艺术，这里指舞蹈艺术。", "病": "语义：“病”不是可以并列喜欢的艺术活动，与“歌和……”不协调。", "桌子": "语义：桌子不是艺术活动，与“歌”并列不协调。", "作业": "语义：“作业”不是可以一起喜欢的东西，与“都很喜欢”不协调。"}, "sentence_index": 0, "correct_answer": "舞"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只舞很有力量，大家都在看。", "explanation": "这里应该用〈段〉或〈支〉。“只”用于动物或单个物件，不用来量舞蹈作品。"}, {"text": "他很会拉舞，大家都很惊讶。", "explanation": "这里应该用〈二胡〉。“拉”接乐器，不能接“舞”，舞要说“跳”。"}, {"text": "她很喜欢听舞，每天都在家里练一遍。", "explanation": "这里应该用〈音乐〉。“听”接“音乐”，不能接“舞”；看舞要说“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93952, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞（wǔ）：有节奏地舞动身体的艺术，是正确答案。"}, {"text": "无", "is_correct": false, "explanation": "无（wú，第二声）与舞（wǔ，第三声）声调不同，意思是没有。"}, {"text": "虎", "is_correct": false, "explanation": "虎（hǔ）与舞（wǔ）声母不同，意思是老虎。"}, {"text": "母", "is_correct": false, "explanation": "母（mǔ）与舞（wǔ）声母不同，意思是母亲。"}, {"text": "物", "is_correct": false, "explanation": "物（wù，第四声）与舞（wǔ，第三声）声调不同，意思是东西。"}], "explanations": {"舞": "舞（wǔ）：有节奏地舞动身体的艺术，是正确答案。", "无": "无（wú，第二声）与舞（wǔ，第三声）声调不同，意思是没有。", "虎": "虎（hǔ）与舞（wǔ）声母不同，意思是老虎。", "母": "母（mǔ）与舞（wǔ）声母不同，意思是母亲。", "物": "物（wù，第四声）与舞（wǔ，第三声）声调不同，意思是东西。"}, "sentence_index": null, "correct_answer": "舞"}, "level_3": {"options": [{"text": "舞", "is_correct": true, "explanation": "舞：“舞需要身体和音乐一起动”，说的正是舞蹈艺术。"}, {"text": "画", "is_correct": false, "explanation": "语义：画不需要身体跟着音乐动，与句意不符。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影不需要观众的身体跟着音乐动，与句意不符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不需要身体和音乐一起动，与句意不符。"}], "explanations": {"舞": "舞：“舞需要身体和音乐一起动”，说的正是舞蹈艺术。", "画": "语义：画不需要身体跟着音乐动，与句意不符。", "电影": "语义：电影不需要观众的身体跟着音乐动，与句意不符。", "房子": "语义：房子不需要身体和音乐一起动，与句意不符。"}, "sentence_index": 6, "correct_answer": "舞"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把舞很好看，大家都在看。", "explanation": "这里应该用〈段〉或〈支〉。“把”用于有柄的东西，不用来量舞蹈。"}, {"text": "她唱了一支舞，大家都很喜欢。", "explanation": "这里应该用〈歌〉。“唱”接“歌”，不接“舞”，“舞”要说“跳”。"}, {"text": "她站在舞上，大家都很高兴。", "explanation": "这里应该用〈舞台〉。“站在……上”要说表示场所的“舞台”，“舞”不能表示场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
