INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过于是比应该的多太多。", "primary_collocate": null, "pronunciation": "guò yú", "ipa": "kuɔ˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "你不要过于紧张。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他对孩子过于严格。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个问题过于复杂，我不会做。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈过于担心他的身体。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件衣服颜色过于鲜艳，我不喜欢。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说话过于直接，朋友有点不高兴。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她过于在意别人的看法。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别过于着急，慢慢来。", "target_word": "过于", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次考试题目过于简单，大家都得了高分。", "target_word": "过于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里过于安静，我有点害怕。", "target_word": "过于", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "過於", "label": "繁体"}], "register": "中性", "sense_fingerprint": "过于·guò yú·比应该的程度多太多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "过于", "is_correct": true, "explanation": "“过于”表示超过适当限度，与“你不要…紧张”的劝阻语气相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已然发生，与“不要”的劝阻语气不相合，“不要已经紧张”不通。"}, {"text": "正在", "is_correct": false, "explanation": "语义：“正在”表示动作进行中，与“不要…紧张”这一状态的劝阻不相合。"}, {"text": "最", "is_correct": false, "explanation": "语义：“最”表示程度最高，与“不要…紧张”的劝阻不相合，说“不要最紧张”不通。"}], "explanations": {"过于": "“过于”表示超过适当限度，与“你不要…紧张”的劝阻语气相合。", "已经": "语义：“已经”表示已然发生，与“不要”的劝阻语气不相合，“不要已经紧张”不通。", "正在": "语义：“正在”表示动作进行中，与“不要…紧张”这一状态的劝阻不相合。", "最": "语义：“最”表示程度最高，与“不要…紧张”的劝阻不相合，说“不要最紧张”不通。"}, "sentence_index": 0, "correct_answer": "过于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的作业过于多，我写到了半夜。", "explanation": "这里应该用〈过多〉。〈过于〉修饰形容词或心理动词，不与“多”组合；说数量超出要用“过多”。"}, {"text": "我们今天过于去超市买东西。", "explanation": "这里应该去掉〈过于〉。〈过于〉修饰形容词或心理动词，不能修饰〈去〉这类动作。"}, {"text": "这个班过于四十人，教室坐不下。", "explanation": "这里应该用〈超过〉。〈过于〉修饰程度，不用来表示人数超出某个界限。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "过于", "is_correct": true, "explanation": "“过于”表示超过适当限度，“过于在意别人的看法”符合句意。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”多与“不”“没”连用表示彻底否定，单独修饰“在意”说不通。"}, {"text": "被", "is_correct": false, "explanation": "语法：“被”引导被动句，需要施事，“她被在意别人的看法”不成立。"}, {"text": "未免", "is_correct": false, "explanation": "语域：“未免”是书面语，含“有些过分”的评价，句中没有这样的语境。"}], "explanations": {"过于": "“过于”表示超过适当限度，“过于在意别人的看法”符合句意。", "根本": "搭配：“根本”多与“不”“没”连用表示彻底否定，单独修饰“在意”说不通。", "被": "语法：“被”引导被动句，需要施事，“她被在意别人的看法”不成立。", "未免": "语域：“未免”是书面语，含“有些过分”的评价，句中没有这样的语境。"}, "sentence_index": 6, "correct_answer": "过于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次郊游我们过于走了很远的路。", "explanation": "这里应该去掉〈过于〉。〈过于〉修饰形容词或心理动词，不能修饰〈走〉这样的动作。"}, {"text": "妈妈过于街去买菜。", "explanation": "这里应该用〈过〉。〈过于〉没有“经过”的意思，“过街”的“过”不带“于”。"}, {"text": "他的成绩过于进步，老师很惊讶。", "explanation": "这里应该用〈很大〉。〈过于〉表示超出限度，不修饰〈进步〉这类表示变化的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的计划很过于复杂，公司不会同意。", "corrected_sentence": "我们的计划过于复杂，公司不会同意。", "error_description": "多余的“很”：“过于”已经表示程度，不能与“很”叠用，应去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93963, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她过于的在意别人的看法，常常睡不好。", "corrected_sentence": "她过于在意别人的看法，常常睡不好。", "error_description": "多余的“的”：“过于”是副词，后面直接接动词或形容词，不能加“的”，应说“过于在意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "靠近", "is_correct": true, "explanation": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。"}, {"text": "进入", "is_correct": false, "explanation": "进入指从外走到内，与距离远近无关，不是反义词。"}, {"text": "停留", "is_correct": false, "explanation": "停留指暂时不走，与距离远近没有对应关系。"}, {"text": "研究", "is_correct": false, "explanation": "研究指深入探讨，与远离没有反义关系。"}], "correct_answer": "靠近", "explanations": {"靠近": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。", "进入": "进入指从外走到内，与距离远近无关，不是反义词。", "停留": "停留指暂时不走，与距离远近没有对应关系。", "研究": "研究指深入探讨，与远离没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "靠近", "is_correct": true, "explanation": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。"}, {"text": "保留", "is_correct": false, "explanation": "保留指留住不失去，与距离远近没有关系。"}, {"text": "修建", "is_correct": false, "explanation": "修建指建造，与远离没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考指用脑子想问题，与远近无关。"}], "correct_answer": "靠近", "explanations": {"靠近": "靠近与远离意思相反，指距离变近，词典中是反义词，与这一义项对立。", "保留": "保留指留住不失去，与距离远近没有关系。", "修建": "修建指建造，与远离没有反义关系。", "思考": "思考指用脑子想问题，与远近无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "远离是离得很远，不靠近。", "primary_collocate": null, "pronunciation": "yuǎn lí", "ipa": "y̯ɛn²¹⁴ li³⁵", "syllable_count": 2, "sentences": [{"text": "我们的学校远离市中心，很安静。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小村子远离大路，很少有车。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请让孩子远离火和电。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家远离城市，住在山里。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂远离河流，不会让水变脏。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院应该远离吵闹的马路。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方远离人群，只有风的声音。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小岛远离陆地，船要开一天。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的房子远离海边，没有海风。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的小学远离县城，路很难走。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远离了", "label": "体标"}, {"form": "远离过", "label": "体标"}, {"form": "遠離", "label": "繁体"}], "register": "中性", "sense_fingerprint": "某处所距离另一处很远，不靠近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8002c7be-6b02-43d9-b4a1-4844c45b5b72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示与市中心距离很远，与“很安静”的描写一致。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：逃离指躲避危险或困境，学校不会逃跑，整句说不通。"}, {"text": "穿过", "is_correct": false, "explanation": "语义：穿过指从中间经过，与“很安静”的描写相反，学校也不会穿过市中心。"}, {"text": "包围", "is_correct": false, "explanation": "配价：包围要求有施事围住对象，学校不能包围市中心。"}], "explanations": {"远离": "正确：远离表示与市中心距离很远，与“很安静”的描写一致。", "逃离": "语义：逃离指躲避危险或困境，学校不会逃跑，整句说不通。", "穿过": "语义：穿过指从中间经过，与“很安静”的描写相反，学校也不会穿过市中心。", "包围": "配价：包围要求有施事围住对象，学校不能包围市中心。"}, "sentence_index": 0, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直远离我，却天天坐在我旁边。", "explanation": "这里应该用〈靠近〉。远离是离得很远，与“天天坐在我旁边”的意思矛盾。"}, {"text": "他在桌子旁边远离了一下，给别人让路。", "explanation": "这里应该用〈让开〉。远离指距离很远，只挪一步让路不能说远离。"}, {"text": "那只猫总是远离主人，一直蹭在他的腿边。", "explanation": "这里应该用〈靠近〉。远离是离得很远，与“一直蹭在他的腿边”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示与人群距离很远，与“只有风的声音”的安静环境一致。"}, {"text": "包围", "is_correct": false, "explanation": "语义：包围是从四周围住，与“只有风的声音”的安静环境矛盾。"}, {"text": "接近", "is_correct": false, "explanation": "语义：接近是靠近，地方接近人群就不会只有风声，前后矛盾。"}, {"text": "闯入", "is_correct": false, "explanation": "配价：闯入需要有人作主语，“这个地方”不能闯入人群。"}], "explanations": {"远离": "正确：远离表示与人群距离很远，与“只有风的声音”的安静环境一致。", "包围": "语义：包围是从四周围住，与“只有风的声音”的安静环境矛盾。", "接近": "语义：接近是靠近，地方接近人群就不会只有风声，前后矛盾。", "闯入": "配价：闯入需要有人作主语，“这个地方”不能闯入人群。"}, "sentence_index": 6, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "父母总是远离孩子，每天都陪着他一起吃饭。", "explanation": "这里应该用〈陪伴〉。远离是离得很远，与“每天都陪着他一起吃饭”的意思矛盾。"}, {"text": "他慢慢远离了那只小狗，想跟它玩。", "explanation": "这里应该用〈接近〉。远离是离得很远，与“想跟它玩”的意思矛盾，要靠近小狗应说接近。"}, {"text": "他一直远离家里，不愿出门。", "explanation": "这里应该用〈留在〉。远离指离得很远，与“一直待在家里，不愿出门”的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个农场从远离铁路，每天都很安静。", "corrected_sentence": "这个农场远离铁路，每天都很安静。", "error_description": "“远离”是动词，前面不能直接加“从”；“从”只用于引出动作的起点，应说“这个农场远离铁路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座寺庙远离在村子，很清静。", "corrected_sentence": "这座寺庙远离村子，很清静。", "error_description": "“远离”后直接带宾语，中间不能插入“在”，应说“远离村子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
