INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离得很远；离开。", "primary_collocate": null, "pronunciation": "yuǎn lí", "ipa": "y̯ɛn²¹⁴ li³⁵", "syllable_count": 2, "sentences": [{"text": "他远离家乡，一个人去了大城市。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业后，她远离了父母，到外地工作。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了身体好，他远离了烟和酒。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想远离吵闹的城市，去山里住。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他远离亲人十年，终于回家了。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到那只大狗，小女孩马上远离了它。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要远离坏朋友，别学他们。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想远离烦人的事，安静地休息几天。", "target_word": "远离", "complexity_tier": "T3", "furigana": "tā xiǎng yuǎnlí fánrén de shì ānjìng de xiūxi jǐ tiān", "sentence_source": "generated"}, {"text": "她远离了朋友们，一个人住在海边。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人远离城市生活，回到了老家。", "target_word": "远离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "远离了", "label": "体标"}, {"form": "远离过", "label": "体标"}, {"form": "遠離", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人主动离开某人、某地或某事物，不再接近", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8002c7be-6b02-43d9-b4a1-4844c45b5b72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示主动离开家乡，与“一个人去了大城市”一致。"}, {"text": "陪伴", "is_correct": false, "explanation": "配价：陪伴要求有生命的对象，家乡不能被陪伴。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是把一种语言转换成另一种，家乡不能被翻译，整句说不通。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：照顾通常用于人或动物，不说照顾家乡。"}], "explanations": {"远离": "正确：远离表示主动离开家乡，与“一个人去了大城市”一致。", "陪伴": "配价：陪伴要求有生命的对象，家乡不能被陪伴。", "翻译": "语义：翻译是把一种语言转换成另一种，家乡不能被翻译，整句说不通。", "照顾": "搭配：照顾通常用于人或动物，不说照顾家乡。"}, "sentence_index": 0, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈慢慢远离了哭闹的孩子，想抱抱他。", "explanation": "这里应该用〈接近〉。远离是离得很远，与“想抱抱他”的意思矛盾，要靠近孩子应说接近。"}, {"text": "他远离家门，整天待在屋里不出去。", "explanation": "这里应该用〈留在〉。远离指离得很远，与“整天待在屋里不出去”的意思矛盾。"}, {"text": "孩子紧紧远离着妈妈，不肯松手。", "explanation": "这里应该用〈贴近〉。远离是离得很远，与“紧紧”“不肯松手”的意思矛盾，要紧挨着妈妈应说贴近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "远离", "is_correct": true, "explanation": "正确：远离表示与坏朋友保持距离，与“别学他们”的劝告一致。"}, {"text": "结交", "is_correct": false, "explanation": "语义：结交是交朋友，与“别学他们”的劝告矛盾。"}, {"text": "包庇", "is_correct": false, "explanation": "语义：包庇是替人隐瞒过错，与“别学他们”的劝告矛盾。"}, {"text": "报答", "is_correct": false, "explanation": "搭配：报答通常接恩情，不说报答坏朋友。"}], "explanations": {"远离": "正确：远离表示与坏朋友保持距离，与“别学他们”的劝告一致。", "结交": "语义：结交是交朋友，与“别学他们”的劝告矛盾。", "包庇": "语义：包庇是替人隐瞒过错，与“别学他们”的劝告矛盾。", "报答": "搭配：报答通常接恩情，不说报答坏朋友。"}, "sentence_index": 6, "correct_answer": "远离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直远离着妻子，却每天都和她一起吃晚饭。", "explanation": "这里应该用〈陪伴〉。远离是离得很远，与“每天都和她一起吃晚饭”的意思矛盾。"}, {"text": "他远离了那场车祸，只受了点轻伤。", "explanation": "这里应该用〈躲过〉。远离指距离远，不能说远离了一场车祸。"}, {"text": "他远离着生病的母亲，寸步不离。", "explanation": "这里应该用〈陪伴〉。远离指离得很远，与“寸步不离”的意思矛盾，照顾生病的母亲应说陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从远离老家，独自去北方打工。", "corrected_sentence": "他远离老家，独自去北方打工。", "error_description": "“远离”是动词，前面不能直接加“从”，应说“他远离老家”，不用“从”引出出发地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我决定远离了坏习惯，每天早起运动。", "corrected_sentence": "我决定远离坏习惯，每天早起运动。", "error_description": "“决定”后面说的是将来的打算，应说“决定远离坏习惯”，不用“远离了”表示已经完成的动作。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "还本是把借来的钱还回去。", "primary_collocate": null, "pronunciation": "huán běn", "ipa": "xwan˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "他答应月底前还本，利息另算。", "target_word": "还本", "complexity_tier": "T3", "furigana": "tā dā yìng yuè dǐ qián huán běn, lì xī lìng suàn.", "sentence_source": "generated"}, {"text": "这笔借款我会分期还本，利息另付。", "target_word": "还本", "complexity_tier": "T3", "furigana": "zhè bǐ jiè kuǎn wǒ huì fēn qī huán běn, lì xī lìng fù.", "sentence_source": "generated"}, {"text": "他不要利息，只要你还本就行。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "借款人应当按期还本，不得拖欠。", "target_word": "还本", "complexity_tier": "T3", "furigana": "jiè kuǎn rén yīng dāng àn qī huán běn, bù dé tuō qiàn.", "sentence_source": "generated"}, {"text": "朋友借给我两千元，约定一年后还本，利息免了。", "target_word": "还本", "complexity_tier": "T3", "furigana": "péng yǒu jiè gěi wǒ liǎng qiān yuán, yuē dìng yì nián hòu huán běn, lì xī miǎn le.", "sentence_source": "generated"}, {"text": "他先还本，再慢慢给我利息。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔借款到期还本，利息每月支付。", "target_word": "还本", "complexity_tier": "T3", "furigana": "zhè bǐ jiè kuǎn dào qī huán běn, lì xī měi yuè zhī fù.", "sentence_source": "generated"}, {"text": "借钱时他说好了，三个月后还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈借我的钱，我已分批还本，利息照付。", "target_word": "还本", "complexity_tier": "T3", "furigana": "mā ma jiè wǒ de qián, wǒ yǐ fēn pī huán běn, lì xī zhào fù.", "sentence_source": "generated"}, {"text": "资金周转不开，他只能先付利息，等有钱再还本。", "target_word": "还本", "complexity_tier": "T3", "furigana": "zī jīn zhōu zhuǎn bù kāi, tā zhǐ néng xiān fù lì xī, děng yǒu qián zài huán běn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "還本", "label": "繁体"}, {"form": "还本付息", "label": "复合"}], "register": "书面语", "sense_fingerprint": "把借来的钱还给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还借来的本金，与「利息另算」搭配，句意通顺。"}, {"text": "退房", "is_correct": false, "explanation": "语义：「退房」是退掉住宿，与借款和利息无关，句子不通。"}, {"text": "还书", "is_correct": false, "explanation": "搭配：「还书」的对象是书，没有利息这一概念，「利息另算」不能与之搭配。"}, {"text": "放假", "is_correct": false, "explanation": "语义：「放假」与借款、利息毫无关系，句子不通。"}], "explanations": {"还本": "「还本」指偿还借来的本金，与「利息另算」搭配，句意通顺。", "退房": "语义：「退房」是退掉住宿，与借款和利息无关，句子不通。", "还书": "搭配：「还书」的对象是书，没有利息这一概念，「利息另算」不能与之搭配。", "放假": "语义：「放假」与借款、利息毫无关系，句子不通。"}, "sentence_index": 0, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借来的图书应当按期还本，不得拖欠。", "explanation": "这里应该用〈归还〉。还本只指偿还所借款项的本金，借来的书要说归还。"}, {"text": "放贷人应当按期还本给借款人，不得拖欠。", "explanation": "这里应该用〈收回〉。还本是借款人偿还本金，放贷人只能说收回本金，不能把本金还给借款人。"}, {"text": "借款人应当按期把利息还本，不得拖欠。", "explanation": "这里应该用〈付息〉。还本的宾语是本金，利息应说付息或还利息，不能说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还本金，与「到期」和「利息每月支付」的还款安排相符。"}, {"text": "退货", "is_correct": false, "explanation": "语义：「退货」是把商品退回，与借款无关，句子不通。"}, {"text": "出租", "is_correct": false, "explanation": "语义：借款不能出租，句子不通。"}, {"text": "登机", "is_correct": false, "explanation": "搭配：「登机」只用于乘坐飞机的场合，与「借款到期」不搭配。"}], "explanations": {"还本": "「还本」指偿还本金，与「到期」和「利息每月支付」的还款安排相符。", "退货": "语义：「退货」是把商品退回，与借款无关，句子不通。", "出租": "语义：借款不能出租，句子不通。", "登机": "搭配：「登机」只用于乘坐飞机的场合，与「借款到期」不搭配。"}, "sentence_index": 6, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欠的房租终于还本了。", "explanation": "这里应该用〈还清〉。还本只指偿还借款的本金，房租这类欠款不说还本。"}, {"text": "他想把老板还本，好让老板高兴。", "explanation": "这里应该用〈还给〉。还本的宾语只能是本金，不能是人。"}, {"text": "他把存在银行的钱还本全部拿走了。", "explanation": "这里应该用〈提取〉。还本指偿还借来的本金，拿回自己存的钱不说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔钱我打算明年把还本。", "corrected_sentence": "这笔钱我打算明年还本。", "error_description": "错误：“明年把还本”。“把”字句需要动词后有宾语或补语，“还本”前不能加“把”，应删去“把”，说“这笔钱我打算明年还本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他分三个还本，利息另付。", "corrected_sentence": "他分三次还本，利息另付。", "error_description": "量词错误：「分三个还本」应改为「分三次还本」。表示还款次数的量词要用「次」，不能用「个」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "偿还本金。", "primary_collocate": null, "pronunciation": "huán běn", "ipa": "xwan˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这笔贷款前三年只付利息，第四年才开始还本。", "target_word": "还本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个月他先付利息，到期再还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司钱不够，银行同意晚一年还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱他分五年还本，每年还一部分。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你要先还本，利息可以以后再给。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸说今年生意好，打算提前还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了还本的日子，他去银行办手续。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司每年付利息，三年后一次还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一边工作一边存钱，想早点还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今年他们只付了利息，明年再还本。", "target_word": "还本", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "還本", "label": "繁体"}, {"form": "还本付息", "label": "复合"}], "register": "书面语", "sense_fingerprint": "偿还贷款或借款的本金，常与付息相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还借款的本金，与「前三年只付利息、第四年才开始」的还款安排相符。"}, {"text": "付息", "is_correct": false, "explanation": "语义：前半句已说「只付利息」，「第四年才开始付息」与前三年只付利息的对照矛盾。"}, {"text": "打折", "is_correct": false, "explanation": "搭配：「打折」用于商品价格，不能用于贷款的还款安排。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：「结婚」与贷款的还款安排无关，句子不通。"}], "explanations": {"还本": "「还本」指偿还借款的本金，与「前三年只付利息、第四年才开始」的还款安排相符。", "付息": "语义：前半句已说「只付利息」，「第四年才开始付息」与前三年只付利息的对照矛盾。", "打折": "搭配：「打折」用于商品价格，不能用于贷款的还款安排。", "结婚": "语义：「结婚」与贷款的还款安排无关，句子不通。"}, "sentence_index": 0, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "借来的字典要按时还本，不能拖到期末。", "explanation": "这里应该用〈归还〉。还本只指偿还借款的本金，字典这类物品要说归还。"}, {"text": "他终于把拖欠的房租还本了。", "explanation": "这里应该用〈还清〉。还本只用于偿还借来的钱的本金，房租这类欠款不说还本。"}, {"text": "银行每月向我们还本，我们只需按时付息。", "explanation": "这里应该用〈放贷〉。还本的主体是借款人，银行向借款人放款，不能说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "还本", "is_correct": true, "explanation": "「还本」指偿还本金，「到了……的日子」去银行办手续，句意通顺。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：游泳的日子不需要去银行办手续，句意不通。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨的日子与去银行办手续无关，句子不合逻辑。"}, {"text": "结婚", "is_correct": false, "explanation": "搭配：「去银行办手续」一般与还款、取款等金融事务搭配，不与「结婚」搭配。"}], "explanations": {"还本": "「还本」指偿还本金，「到了……的日子」去银行办手续，句意通顺。", "游泳": "语义：游泳的日子不需要去银行办手续，句意不通。", "下雨": "语义：下雨的日子与去银行办手续无关，句子不合逻辑。", "结婚": "搭配：「去银行办手续」一般与还款、取款等金融事务搭配，不与「结婚」搭配。"}, "sentence_index": 6, "correct_answer": "还本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他先把欠的利息还本，本金以后再说。", "explanation": "这里应该用〈还息〉。还本只指偿还本金，利息不能说还本。"}, {"text": "他想把老板还本，好让老板放心。", "explanation": "这里应该用〈还给〉。还本的宾语只能是本金，不能是人。"}, {"text": "他去银行把存款还本提走了。", "explanation": "这里应该用〈提取〉。还本指偿还借来的本金，提取自己的存款不说还本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每月按时还本了，利息另付。", "corrected_sentence": "他每月按时还本，利息另付。", "error_description": "体标错误：这里说的是每月按时的习惯性还款，不应在“还本”后加“了”，应说“他每月按时还本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "借款到期后，他还本一下，利息另付。", "corrected_sentence": "借款到期后，他还本一次，利息另付。", "error_description": "动量补语错误：表示一次性还本应说“还本一次”，“一下”用于短暂的动作，不能用于还本。正确说法是“还本一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
