INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "房屋、山等朝着某个方向或某处。", "primary_collocate": null, "pronunciation": "miàn xiàng", "ipa": "mi̯ɛn⁵¹ ɕi̯ɑŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "我家的房子面向南方，冬天很暖和。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室面向操场，很吵。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的房间面向大海，风景很美。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山面向湖水，另一边是树林。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租一间面向公园的小房子。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的新家面向马路，晚上有点吵。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼面向东，早上阳光很好。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大门面向街道，后门面向小河。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面向河边的那家饭馆人很多。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客厅面向花园，孩子们常在那儿玩。", "target_word": "面向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面向着", "label": "体标"}, {"form": "面向了", "label": "体标"}], "register": "中性", "sense_fingerprint": "房子、房间、山等朝着某个方向或某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8002c7be-6b02-43d9-b4a1-4844c45b5b72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93976, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。面向指房屋、山等朝着某个方向或某处。"}, {"text": "现象", "is_correct": false, "explanation": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。"}, {"text": "变相", "is_correct": false, "explanation": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是换个形式。"}, {"text": "面上", "is_correct": false, "explanation": "第二音节声母 sh 与 x 不同（shàng 与 xiàng），意思是表面上、脸上。"}], "explanations": {"面向": "正确答案。面向指房屋、山等朝着某个方向或某处。", "现象": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。", "变相": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是换个形式。", "面上": "第二音节声母 sh 与 x 不同（shàng 与 xiàng），意思是表面上、脸上。"}, "sentence_index": null, "correct_answer": "面向"}, "level_3": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。句子说的是房子朝向南方，只有“面向”能填入。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”指离去，与房子的朝向不符。"}, {"text": "拥有", "is_correct": false, "explanation": "配价：“拥有”要带名词宾语，“拥有南方”不能成立。"}, {"text": "出发", "is_correct": false, "explanation": "配价：“出发”后要接“向”或“到”引出地点，不能直接接方位词。"}], "explanations": {"面向": "正确答案。句子说的是房子朝向南方，只有“面向”能填入。", "离开": "语义：“离开”指离去，与房子的朝向不符。", "拥有": "配价：“拥有”要带名词宾语，“拥有南方”不能成立。", "出发": "配价：“出发”后要接“向”或“到”引出地点，不能直接接方位词。"}, "sentence_index": 0, "correct_answer": "面向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他面向了一份作业。", "explanation": "这里应该用〈交〉。“面向”表示脸或房屋朝着某个方向，交作业要用“交”。"}, {"text": "这条河面向大海，流得很急。", "explanation": "这里应该用〈流向〉。河水是流动的，要说流向大海，不说面向。"}, {"text": "他面向了好成绩。", "explanation": "这里应该用〈取得〉。“面向”表示脸或房屋朝着某个方向，取得成绩要用“取得”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93976, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。面向指房屋、山等朝着某个方向或某处。"}, {"text": "现象", "is_correct": false, "explanation": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。"}, {"text": "变向", "is_correct": false, "explanation": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是改变方向。"}, {"text": "面酱", "is_correct": false, "explanation": "第二音节声母 j 与 x 不同（jiàng 与 xiàng），意思是用面粉等做成的调味酱。"}], "explanations": {"面向": "正确答案。面向指房屋、山等朝着某个方向或某处。", "现象": "第一音节声母 x 与 m 不同（xiàn 与 miàn），意思是事物表现出来的样子。", "变向": "第一音节声母 b 与 m 不同（biàn 与 miàn），意思是改变方向。", "面酱": "第二音节声母 j 与 x 不同（jiàng 与 xiàng），意思是用面粉等做成的调味酱。"}, "sentence_index": null, "correct_answer": "面向"}, "level_3": {"options": [{"text": "面向", "is_correct": true, "explanation": "正确答案。句子说的是这栋楼朝东，只有“面向”能填入。"}, {"text": "通往", "is_correct": false, "explanation": "语义：“通往”表示道路通向某处，楼房不能通向东。"}, {"text": "躲避", "is_correct": false, "explanation": "语义：“躲避”指避开，与楼房的朝向不符。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”是不及物动词，不能带方向词“东”作宾语。"}], "explanations": {"面向": "正确答案。句子说的是这栋楼朝东，只有“面向”能填入。", "通往": "语义：“通往”表示道路通向某处，楼房不能通向东。", "躲避": "语义：“躲避”指避开，与楼房的朝向不符。", "唱歌": "配价：“唱歌”是不及物动词，不能带方向词“东”作宾语。"}, "sentence_index": 6, "correct_answer": "面向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司面向很大的压力。", "explanation": "这里应该用〈面临〉。“面向”表示脸或房屋朝着某个方向，遇到压力要用“面临”。"}, {"text": "他面向了学校的规定。", "explanation": "这里应该用〈遵守〉。“面向”表示脸或房屋朝着某个方向，遵守规定要用“遵守”。"}, {"text": "他面向我吃了一顿饭。", "explanation": "这里应该用〈请〉。“面向”表示脸或房屋朝着某个方向，请人吃饭要用“请”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这间卧室对着面向东边，早上很亮。", "corrected_sentence": "这间卧室面向东边，早上很亮。", "error_description": "赘余介词：“对着”与“面向”意思重复，只用“面向”即可，应说“这间卧室面向东边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这栋大楼对着面向南边，阳光很好。", "corrected_sentence": "这栋大楼面向南边，阳光很好。", "error_description": "赘余介词：“对着”与“面向”意思重复，只用“面向”即可，应说“这栋大楼面向南边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2f663ba0-1400-4a0c-a91b-fc2b4a77a5b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
