INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "专供汽车高速行驶的、设有隔离带和多条车道的公路。", "primary_collocate": null, "pronunciation": "gāo sù gōng lù", "ipa": "kaʊ˥ su˥˩ kʊŋ˥ lu˥˩", "syllable_count": 4, "sentences": [{"text": "高速公路中间有隔离带，车不能随便掉头。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条高速公路有四条车道，车可以开得很快。", "target_word": "高速公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高速公路专供汽车行驶，自行车不能上去。", "target_word": "高速公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在高速公路上，每辆车的速度都不能太慢。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新建的高速公路设有多条车道。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高速公路的隔离带把两个方向的车分开。", "target_word": "高速公路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的高速公路越修越多。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摩托车和行人都不能进入高速公路。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "高速公路上的车道多，车也比较安全。", "target_word": "高速公路", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过这条高速公路，到海边只要一个小时。", "target_word": "高速公路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "专供汽车高速行驶、有隔离带和多车道的公路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高速公路", "is_correct": true, "explanation": "「高速公路」设有隔离带，与「车不能随便掉头」相符。"}, {"text": "操场", "is_correct": false, "explanation": "语义：操场上不会有隔离带限制车辆掉头，句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房里不会有供车辆掉头的隔离带，句子不通。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：「中间有隔离带」不用于教室这类室内场所，句子不搭配。"}], "explanations": {"高速公路": "「高速公路」设有隔离带，与「车不能随便掉头」相符。", "操场": "语义：操场上不会有隔离带限制车辆掉头，句意不通。", "厨房": "语义：厨房里不会有供车辆掉头的隔离带，句子不通。", "教室": "搭配：「中间有隔离带」不用于教室这类室内场所，句子不搭配。"}, "sentence_index": 0, "correct_answer": "高速公路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们在高速公路上跳绳，玩得很开心。", "explanation": "这里应该用〈操场〉。高速公路专供汽车高速行驶，孩子跳绳要去操场。"}, {"text": "火车沿着高速公路开，速度很快。", "explanation": "这里应该用〈铁轨〉。火车在铁轨上行驶，高速公路专供汽车行驶。"}, {"text": "村口的高速公路很窄，只能让行人和自行车走。", "explanation": "这里应该用〈小路〉。高速公路必须宽、专供汽车高速行驶，只能让行人和自行车走的窄路要说小路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高速公路", "is_correct": true, "explanation": "「高速公路」可以越修越多，与「这座城市的……越修越多」相符。"}, {"text": "公交车", "is_correct": false, "explanation": "搭配：「修」用于道路、房屋等，不能用于公交车。"}, {"text": "饭菜", "is_correct": false, "explanation": "语义：饭菜不是修建出来的，句子不通。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不会「越修越多」，句子不合逻辑。"}], "explanations": {"高速公路": "「高速公路」可以越修越多，与「这座城市的……越修越多」相符。", "公交车": "搭配：「修」用于道路、房屋等，不能用于公交车。", "饭菜": "语义：饭菜不是修建出来的，句子不通。", "玩具": "语义：玩具不会「越修越多」，句子不合逻辑。"}, "sentence_index": 6, "correct_answer": "高速公路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天住在高速公路里，上班很方便。", "explanation": "这里应该用〈小区〉。高速公路是道路，不是居住的地方。"}, {"text": "孩子们在高速公路上游泳，玩得很开心。", "explanation": "这里应该用〈河〉。高速公路是供汽车行驶的道路，不能用来游泳。"}, {"text": "孩子生病了，我们去高速公路看病。", "explanation": "这里应该用〈医院〉。高速公路不是看病的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "司机把车开上了高速公路上。", "corrected_sentence": "司机把车开上了高速公路。", "error_description": "重复方位词：「开上」已表示朝向高速公路，「高速公路」后不需再加「上」，应说「开上了高速公路」，不能说「高速公路上」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条高速公路一直通在海边。", "corrected_sentence": "这条高速公路一直通到海边。", "error_description": "介词错误：表示延伸到某处要用「到」，不能用「在」，「通在海边」应改为「通到海边」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
