INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用三颗星表示的等级或评分，如酒店、餐厅的星级。", "primary_collocate": null, "pronunciation": "sān xīng", "ipa": "san˥˥ ɕiŋ˥˥", "syllable_count": 2, "sentences": [{"text": "这家酒店是三星的，住一晚不太贵。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆得了三星，很多客人专门来吃饭。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们住的是三星酒店，房间干净，早饭也不错。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家宾馆只有三星，别对它期望太高。", "target_word": "三星", "complexity_tier": "T3", "furigana": "zhè jiā bīn guǎn zhǐ yǒu sān xīng, bié duì tā qī wàng tài gāo.", "sentence_source": "generated"}, {"text": "这个餐厅评了三星，所以今天要早点订位子。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时我常住三星，又干净又便宜。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给这部电影打了三星，说不好也不坏。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上说那家店是三星，可是我觉得像四星。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行我们订的是三星，不是五星。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "三星的房间不大，但是住着很舒服。", "target_word": "三星", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "三星级", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用三颗星表示的等级，如酒店、餐厅的三星", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "三星", "is_correct": true, "explanation": "“三星”是酒店等级，“这家酒店是三星的，住一晚不太贵”符合句意。"}, {"text": "五星", "is_correct": false, "explanation": "语义：“五星”指高档酒店，与“住一晚不太贵”矛盾。"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”指天上的星体，不表示酒店的等级。"}, {"text": "金牌", "is_correct": false, "explanation": "搭配：酒店的等级用星级表示，不说“金牌的酒店”。"}], "explanations": {"三星": "“三星”是酒店等级，“这家酒店是三星的，住一晚不太贵”符合句意。", "五星": "语义：“五星”指高档酒店，与“住一晚不太贵”矛盾。", "星星": "语义：“星星”指天上的星体，不表示酒店的等级。", "金牌": "搭配：酒店的等级用星级表示，不说“金牌的酒店”。"}, "sentence_index": 0, "correct_answer": "三星"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是三星的，大家都很喜欢他。", "explanation": "这里应该用〈优秀〉或〈好〉。〈三星〉是给酒店、餐厅等评定的等级，不用来评价人。"}, {"text": "这盘菜很三星，我们都吃光了。", "explanation": "这里应该用〈很好吃〉。〈三星〉是名词，不能放在“很”后面作形容词。"}, {"text": "这辆车的座位是三星的，我们坐得很舒服。", "explanation": "这里应该去掉〈三星〉。〈三星〉只用来为酒店、餐厅等评定等级，不用来描述座位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "三星", "is_correct": true, "explanation": "“三星”是评分，“打了三星，说不好也不坏”符合句意。"}, {"text": "五星", "is_correct": false, "explanation": "语义：“五星”表示很好，与“说不好也不坏”矛盾。"}, {"text": "一星", "is_correct": false, "explanation": "语义：“一星”表示很差，与“也不坏”矛盾。"}, {"text": "星级", "is_correct": false, "explanation": "搭配：评分要说“几星”，不说“打了星级”。"}], "explanations": {"三星": "“三星”是评分，“打了三星，说不好也不坏”符合句意。", "五星": "语义：“五星”表示很好，与“说不好也不坏”矛盾。", "一星": "语义：“一星”表示很差，与“也不坏”矛盾。", "星级": "搭配：评分要说“几星”，不说“打了星级”。"}, "sentence_index": 6, "correct_answer": "三星"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个学生考了三星，老师很高兴。", "explanation": "这里应该用〈满分〉或〈一百分〉。〈三星〉是给酒店、餐厅等评定的等级，学生的成绩不用星级表示。"}, {"text": "这张三星的桌子很便宜。", "explanation": "这里应该去掉〈三星〉。〈三星〉是等级，不用来描述桌子之类的家具。"}, {"text": "这次演讲比赛，他拿了三星的好成绩。", "explanation": "这里应该用〈满分〉或〈好〉。〈三星〉是给酒店、餐厅等评定的等级，不用来表示比赛成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家酒店是很三星的，住一晚很便宜。", "corrected_sentence": "这家酒店是三星的，住一晚很便宜。", "error_description": "多余的“很”：“三星”是名词，表示酒店等级，不能受“很”修饰，应说“是三星的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他给这家餐厅打了过三星，服务一般。", "corrected_sentence": "他给这家餐厅打过三星，服务一般。", "error_description": "了、过并用：“过”表示曾经有过的经历，与“了”不能同时用在同一个动词上，应去掉“了”，说“打过三星”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "上下是差不多，多一点或少一点。", "primary_collocate": null, "pronunciation": "shàng xià", "ipa": "ʂɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这件衣服的价格在一百块上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的温度在二十五度上下，很舒服。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体重一直在六十公斤上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来的客人有五十位上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个月的电话费在八十块上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校离我家走路二十分钟上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡觉的时间在七个小时上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的价钱三十块上下，不算贵。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买一台这样的电视，两千块上下就够了。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司有三百人上下，不算大。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "放在数量后，表示差不多、略多或略少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "“上下”表示约数，“一百块上下”说明价格大约在一百块左右。"}, {"text": "以上", "is_correct": false, "explanation": "语义：“以上”表示超过某个数，与“大约在一百块”的约数意思不符。"}, {"text": "以下", "is_correct": false, "explanation": "语义：“以下”表示不足某个数，与“大约在一百块”的约数意思不符。"}, {"text": "有余", "is_correct": false, "explanation": "语域：“有余”是书面语，口语介绍价格时很少这样说。"}], "explanations": {"上下": "“上下”表示约数，“一百块上下”说明价格大约在一百块左右。", "以上": "语义：“以上”表示超过某个数，与“大约在一百块”的约数意思不符。", "以下": "语义：“以下”表示不足某个数，与“大约在一百块”的约数意思不符。", "有余": "语域：“有余”是书面语，口语介绍价格时很少这样说。"}, "sentence_index": 0, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试我得了一百分上下。", "explanation": "这里应该去掉〈上下〉。〈上下〉表示大约，分数要说准确数，如“一百分”。"}, {"text": "这次活动有上下很多人参加。", "explanation": "这里应该去掉〈上下〉。〈上下〉是约数，必须紧跟数量词（如“三百人上下”），句中没有数量，应说“这次活动有很多人参加”。"}, {"text": "这台电脑的价格比那台上下三百块。", "explanation": "这里应该用〈多〉或〈少〉。〈上下〉是约数，不用于比较句中表示差额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "“上下”表示约数，“七个小时上下”说明睡觉时间大约是七小时。"}, {"text": "以内", "is_correct": false, "explanation": "语义：“以内”表示上限，与“大约七个小时”的约数意思不符。"}, {"text": "以外", "is_correct": false, "explanation": "语义：“以外”表示超出某个范围，与“大约七个小时”的约数意思不符。"}, {"text": "有余", "is_correct": false, "explanation": "语域：“有余”是书面语，口语描述睡眠时间时很少这样说。"}], "explanations": {"上下": "“上下”表示约数，“七个小时上下”说明睡觉时间大约是七小时。", "以内": "语义：“以内”表示上限，与“大约七个小时”的约数意思不符。", "以外": "语义：“以外”表示超出某个范围，与“大约七个小时”的约数意思不符。", "有余": "语域：“有余”是书面语，口语描述睡眠时间时很少这样说。"}, "sentence_index": 6, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司正好有三百人上下，一个不多。", "explanation": "这里应该去掉〈上下〉。〈上下〉表示约数，而句子强调人数准确，两者意思相反。"}, {"text": "比赛的奖金上下很高，大家都很开心。", "explanation": "这里应该用〈大约〉或〈左右〉。〈上下〉是放在数量后面的约数，不能直接修饰〈高〉这类形容词。"}, {"text": "今天的温度比昨天上下两度。", "explanation": "这里应该用〈高〉或〈低〉。〈上下〉是放在数量后面的约数，不用于比较句中表示差额。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服的价格在一百条上下，不太便宜。", "corrected_sentence": "这件衣服的价格在一百块上下，不太便宜。", "error_description": "量词错误：价格的量词应为“块”，不能用“条”，应说“一百块上下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天睡觉的时间在七只小时上下，不算少。", "corrected_sentence": "他每天睡觉的时间在七个小时上下，不算少。", "error_description": "量词错误：“小时”的量词应为“个”，不能用“只”，应说“七个小时上下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "表示大约的数量，用在数词后面。", "primary_collocate": null, "pronunciation": "shàng xià", "ipa": "ʂɑŋ˥˩ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "那个男人四十岁上下，穿着一件黑衣服。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的个子一米六上下，不高也不矮。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上九点上下，外面下起雨来了。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的学生有三十人上下。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他明天早上六点上下就会到车站。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一个二十岁上下的女孩。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路长三公里上下，走路很快。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗五公斤上下，不算大。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买这本书花了五十块上下，我记不清了。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家的孩子七岁上下，很爱看书。", "target_word": "上下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "用在年龄、身高、时间等数词后表示大约", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上下", "is_correct": true, "explanation": "正确答案。上下 shàng xià 表示大约的数量，用在数词后面。"}, {"text": "上限", "is_correct": false, "explanation": "xiàn（第四声）比 xià 多了韵尾 n，意思是“上限”，指最高限度。"}, {"text": "上校", "is_correct": false, "explanation": "xiào（第四声）与 xià 的韵母不同，意思是“上校”，一种军衔。"}, {"text": "上架", "is_correct": false, "explanation": "jià（第四声）与 xià 声母不同（j 与 x），意思是“上架”，即放到架子上。"}, {"text": "山下", "is_correct": false, "explanation": "shān（第一声）与 shàng 韵母不同（an 与 ang），声调也不同，意思是“山下”。"}], "explanations": {"上下": "正确答案。上下 shàng xià 表示大约的数量，用在数词后面。", "上限": "xiàn（第四声）比 xià 多了韵尾 n，意思是“上限”，指最高限度。", "上校": "xiào（第四声）与 xià 的韵母不同，意思是“上校”，一种军衔。", "上架": "jià（第四声）与 xià 声母不同（j 与 x），意思是“上架”，即放到架子上。", "山下": "shān（第一声）与 shàng 韵母不同（an 与 ang），声调也不同，意思是“山下”。"}, "sentence_index": null, "correct_answer": "上下"}, "level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "正确答案。“上下”表示大约数量，用在“四十岁”这类数词后面。"}, {"text": "以上", "is_correct": false, "explanation": "语义：「以上」表示超过某个数，“四十岁以上”是四十岁及以上，不表示大约。"}, {"text": "以下", "is_correct": false, "explanation": "语义：「以下」表示不超过某个数，“四十岁以下”是四十岁及以下，不表示大约。"}, {"text": "余", "is_correct": false, "explanation": "语域：「余」是书面语，“四十岁余”与这句口语化的描述风格不符。"}], "explanations": {"上下": "正确答案。“上下”表示大约数量，用在“四十岁”这类数词后面。", "以上": "语义：「以上」表示超过某个数，“四十岁以上”是四十岁及以上，不表示大约。", "以下": "语义：「以下」表示不超过某个数，“四十岁以下”是四十岁及以下，不表示大约。", "余": "语域：「余」是书面语，“四十岁余”与这句口语化的描述风格不符。"}, "sentence_index": 0, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动正好三十人上下。", "explanation": "这里应该用〈整〉。“上下”表示大约，句中要说明确切人数，应说“整三十人”；“上下”不能表示确切数量。"}, {"text": "这两个朋友是上下级关系。", "explanation": "这里应该用〈平级〉。“上下级”指职务上的上级和下级，朋友之间应说“平级”，不能用“上下级”。"}, {"text": "我们班的学生每天上下学校，很辛苦。", "explanation": "这里应该用〈进出〉。“上下”多用于楼梯、车辆等有高低之分的对象，不能与“学校”搭配；进出学校应说“进出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上下", "is_correct": true, "explanation": "正确答案。“上下”表示大约的长度，用在数量词后面。"}, {"text": "开外", "is_correct": false, "explanation": "搭配：「开外」多用于年龄或距离，说“长三公里开外”描述道路长度搭配不当。"}, {"text": "以内", "is_correct": false, "explanation": "语义：「以内」表示不超过三公里，与“这条路长三公里”表示大约长度的意思不符。"}, {"text": "有余", "is_correct": false, "explanation": "语域：「有余」是书面语，不适合这句口语化的描述。"}], "explanations": {"上下": "正确答案。“上下”表示大约的长度，用在数量词后面。", "开外": "搭配：「开外」多用于年龄或距离，说“长三公里开外”描述道路长度搭配不当。", "以内": "语义：「以内」表示不超过三公里，与“这条路长三公里”表示大约长度的意思不符。", "有余": "语域：「有余」是书面语，不适合这句口语化的描述。"}, "sentence_index": 6, "correct_answer": "上下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "李经理上下都很努力工作。", "explanation": "这里应该用〈本人〉。“上下”指一个集体的全体人员，只能用于群体；只指一个人时应说“本人”。"}, {"text": "这次活动有三十多人上下。", "explanation": "这里应该去掉〈上下〉。“三十多”本身已是不确定的大约数，再加“上下”重复，应只说“三十多人”。"}, {"text": "这间平房的上下都是卧室。", "explanation": "这里应该用〈楼上楼下〉。“上下”指上下两层或上面与下面，平房只有一层，应说“屋里都是卧室”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家门口有五只人上下。", "corrected_sentence": "他家门口有五个人上下。", "error_description": "量词错误：“人”的量词应为“个”，不能用“只”，应说“五个人上下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这箱苹果有二十个斤上下。", "corrected_sentence": "这箱苹果有二十斤上下。", "error_description": "量词错误：“斤”本身已是量词，数词后不能再加“个”，应说“二十斤上下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上进是想学得更好，想变得更好。", "primary_collocate": null, "pronunciation": "shàng jìn", "ipa": "ʂaŋ˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "小明很上进，总想把字写得更好。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很上进，所以每天多练习一小时。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥不太上进，只想玩游戏。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "上进的学生会主动问老师问题。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想变得更好，所以特别上进。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹很上进，天天都想学新词。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做人要上进，不能总是懒懒的。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们都很上进，都想考好。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他以前不上进，现在变了。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板喜欢上进的新同事。", "target_word": "上进", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "上進", "label": "繁体"}, {"form": "上进心", "label": "复合"}], "register": "中性", "sense_fingerprint": "想学得更好、想变得更好的态度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上进", "is_correct": true, "explanation": "上进（shàng jìn）：想学得更好，想变得更好，是正确答案。"}, {"text": "上镜", "is_correct": false, "explanation": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。"}, {"text": "上紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。"}, {"text": "上季", "is_correct": false, "explanation": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}], "explanations": {"上进": "上进（shàng jìn）：想学得更好，想变得更好，是正确答案。", "上镜": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。", "上紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。", "上季": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}, "sentence_index": null, "correct_answer": "上进"}, "level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境吵闹，不能用来修饰小明这样的人。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“上进”指想学得更好、想变得更好，与后句“总想把字写得更好”一致。"}, {"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指缺少水分，不能用来形容人的品性。"}, {"text": "辽阔", "is_correct": false, "explanation": "搭配：“辽阔”形容土地、天空等空间，不能修饰人。"}], "explanations": {"嘈杂": "搭配：“嘈杂”形容声音或环境吵闹，不能用来修饰小明这样的人。", "上进": "正确答案：“上进”指想学得更好、想变得更好，与后句“总想把字写得更好”一致。", "干燥": "语义：“干燥”指缺少水分，不能用来形容人的品性。", "辽阔": "搭配：“辽阔”形容土地、天空等空间，不能修饰人。"}, "sentence_index": 0, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的及格率很上进，比上次高了十个百分点。", "explanation": "这里应该用〈提高〉。上进形容人努力向上，及格率的增长要说提高，不能用上进。"}, {"text": "这个小区的环境很上进，周围的绿化一年比一年好。", "explanation": "这里应该用〈优美〉。上进用来形容人的态度，环境的美好要说优美。"}, {"text": "这块地的土质很上进，今年的庄稼长得特别好。", "explanation": "这里应该用〈肥沃〉。上进形容人想学得更好、想变得更好，土地的肥沃要说肥沃，不能用上进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能用于做人的要求。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“做人要上进”指做人要求进步、向上，与“不能总是懒懒的”一致。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水多，不能用来形容做人的态度。"}, {"text": "富丽", "is_correct": false, "explanation": "搭配：“富丽”形容建筑、陈设的华美，不能用于做人的要求。"}], "explanations": {"嘹亮": "搭配：“嘹亮”形容声音，不能用于做人的要求。", "上进": "正确答案：“做人要上进”指做人要求进步、向上，与“不能总是懒懒的”一致。", "潮湿": "语义：“潮湿”指空气或物体含水多，不能用来形容做人的态度。", "富丽": "搭配：“富丽”形容建筑、陈设的华美，不能用于做人的要求。"}, "sentence_index": 6, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把椅子很上进，坐起来特别舒服。", "explanation": "这里应该用〈舒适〉。上进只形容人想学得更好、想变得更好，不能用来形容椅子的舒适程度。"}, {"text": "这家店的生意很上进，周末总是排很长的队。", "explanation": "这里应该用〈兴隆〉。上进形容人努力向上，生意红火要说兴隆，不能用上进。"}, {"text": "这个城市的经济很上进，每年的收入都在增长。", "explanation": "这里应该用〈发达〉。上进形容人想学得更好、想变得更好，城市经济的繁荣要说发达，不能用上进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她很上进心，每天主动找老师问问题。", "corrected_sentence": "她很上进，每天主动找老师问问题。", "error_description": "错误：“很上进心”。“上进心”是名词，不能受程度副词“很”修饰作谓语，应说“很上进”，去掉“心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很上进的准备考试。", "corrected_sentence": "她很上进地准备考试。", "error_description": "错误：“很上进的准备考试”。“准备考试”是动词短语，修饰它的状语要用“地”，应为“很上进地准备考试”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
