INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "努力向上，要求进步。", "primary_collocate": null, "pronunciation": "shàng jìn", "ipa": "ʂaŋ˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他是一个很上进的学生。", "target_word": "上进", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她学习很上进，每天都学新东西。", "target_word": "上进", "complexity_tier": "T3", "furigana": "tā xuéxí hěn shàngjìn, měitiān dōu xué xīn dōngxi。", "sentence_source": "generated"}, {"text": "上进的人不会满足于现在的样子。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟很上进，晚上还在看书。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师喜欢上进又努力的孩子。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他年轻上进，公司的人都很看好他。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想上进的人，总是愿意多学一点。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你这么上进，一定会有好成绩。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就上进，考试总是第一名。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个年轻人又聪明又上进。", "target_word": "上进", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "上進", "label": "繁体"}, {"form": "上进心", "label": "复合"}], "register": "中性", "sense_fingerprint": "人努力向上、要求进步的品质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c50dd8d-0afb-4e4d-8dcd-7c0f9d255ecb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上进", "is_correct": true, "explanation": "上进（shàng jìn）：努力向上，要求进步，是正确答案。"}, {"text": "上镜", "is_correct": false, "explanation": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。"}, {"text": "上紧", "is_correct": false, "explanation": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。"}, {"text": "上季", "is_correct": false, "explanation": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}], "explanations": {"上进": "上进（shàng jìn）：努力向上，要求进步，是正确答案。", "上镜": "jìng（第四声）与 jìn（第四声）韵母不同（-ing / -in），意思是在镜头前显得好看。", "上紧": "jǐn（第三声）与 jìn（第四声）声调不同，意思是拧紧、抓紧。", "上季": "jì（第四声）与 jìn（第四声）韵母不同（-i / -in），意思是上一季。"}, "sentence_index": null, "correct_answer": "上进"}, "level_3": {"options": [{"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”指空气或物体含水分多，不能用来形容学生的品质。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“上进”指努力向上、要求进步，能够描述学生的品质。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：“冷清”形容场所或气氛，不能用来修饰学生这样的人。"}, {"text": "富丽", "is_correct": false, "explanation": "搭配：“富丽”形容建筑、陈设的华美，不能用来修饰学生。"}], "explanations": {"潮湿": "语义：“潮湿”指空气或物体含水分多，不能用来形容学生的品质。", "上进": "正确答案：“上进”指努力向上、要求进步，能够描述学生的品质。", "冷清": "搭配：“冷清”形容场所或气氛，不能用来修饰学生这样的人。", "富丽": "搭配：“富丽”形容建筑、陈设的华美，不能用来修饰学生。"}, "sentence_index": 0, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月公司的销售额很上进，比上个月多了三成。", "explanation": "这里应该用〈上升〉。上进形容人努力向上、要求进步，销售额的增长要说上升，不能用上进。"}, {"text": "这个社区的人数今年很上进，比去年多了两百人。", "explanation": "这里应该用〈增加〉。上进只用于形容人的态度，人数增多要说增加，不能说人数很上进。"}, {"text": "他的成绩很上进，这学期提高了很多。", "explanation": "这里应该用〈进步〉。上进形容人努力向上、要求进步的态度，成绩的变化要说进步，不能用上进。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”与后句“总是愿意多学一点”的态度相反，搭配上不成立。"}, {"text": "嘹亮", "is_correct": false, "explanation": "搭配：“嘹亮”形容声音，不能用来描述“想……的人”的态度。"}, {"text": "上进", "is_correct": true, "explanation": "正确答案：“上进”指想学得更好、想变得更好，与“愿意多学一点”一致。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”指反应慢、不灵活，与“愿意多学一点”的意思矛盾。"}], "explanations": {"懒惰": "语义：“懒惰”与后句“总是愿意多学一点”的态度相反，搭配上不成立。", "嘹亮": "搭配：“嘹亮”形容声音，不能用来描述“想……的人”的态度。", "上进": "正确答案：“上进”指想学得更好、想变得更好，与“愿意多学一点”一致。", "迟钝": "语义：“迟钝”指反应慢、不灵活，与“愿意多学一点”的意思矛盾。"}, "sentence_index": 6, "correct_answer": "上进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家饭馆的生意很上进，每到周末都要排队。", "explanation": "这里应该用〈兴隆〉。上进形容人努力向上，生意红火要说兴隆，不能用上进。"}, {"text": "他的脸色很上进，看起来精神饱满。", "explanation": "这里应该用〈红润〉。上进只用来描述人的态度，形容脸色要说红润。"}, {"text": "妈妈做的菜很上进，大家都吃得很满意。", "explanation": "这里应该用〈可口〉。上进形容人的品质，形容菜的味道要说可口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一位很上进老师。", "corrected_sentence": "他是一位很上进的老师。", "error_description": "错误：“很上进老师”。形容词“上进”修饰名词时，中间要加“的”，应为“很上进的老师”。漏掉“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很上进过，每天都早起学习。", "corrected_sentence": "她很上进，每天都早起学习。", "error_description": "体标误用：形容词“上进”后不能接“过”，“过”只能接在动词后；应删去“过”，即“她很上进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01751798-9545-40b5-b7fd-c1de88568867') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "债权", "is_correct": true, "explanation": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。"}, {"text": "工资", "is_correct": false, "explanation": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。"}, {"text": "存款", "is_correct": false, "explanation": "「存款」指存进银行的钱，与「债务」不构成反义关系。"}, {"text": "收入", "is_correct": false, "explanation": "「收入」与「支出」相对，与「债务」不构成反义关系。"}], "correct_answer": "债权", "explanations": {"债权": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。", "工资": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。", "存款": "「存款」指存进银行的钱，与「债务」不构成反义关系。", "收入": "「收入」与「支出」相对，与「债务」不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "债权", "is_correct": true, "explanation": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。"}, {"text": "工资", "is_correct": false, "explanation": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。"}, {"text": "利润", "is_correct": false, "explanation": "「利润」指经营后的收益，与「债务」不构成反义关系。"}, {"text": "储蓄", "is_correct": false, "explanation": "「储蓄」指存起来的钱，与「债务」不构成反义关系。"}], "correct_answer": "债权", "explanations": {"债权": "「债权」与「债务」相对，指借出钱的一方可以要求对方偿还的权利，是债务的反义词。", "工资": "「工资」指劳动所得的报酬，与「债务」不构成反义关系。", "利润": "「利润」指经营后的收益，与「债务」不构成反义关系。", "储蓄": "「储蓄」指存起来的钱，与「债务」不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "债务是你借了别人的钱，要还给别人。", "primary_collocate": null, "pronunciation": "zhài wù", "ipa": "ʈʂaɪ˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "他借了很多钱，现在背着一大笔债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了还债务，他每天打两份工。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的债务越来越多。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他终于还清了所有债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "父亲去世后，儿子替他还了债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不想借钱，因为不想有债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用工资一点一点还债务。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友帮他解决了债务问题。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她刚工作，已经有五万元债务了。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他有债务，所以不敢买新房子。", "target_word": "债务", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔债务", "label": "量词"}, {"form": "債務", "label": "繁体"}], "register": "中性", "sense_fingerprint": "债务：名词，借别人的钱后要还的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6d9584a-0189-4503-ada2-5a16c38af2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "债务", "is_correct": true, "explanation": "「债务」指欠别人的钱，需要偿还，是本题的正确答案。"}, {"text": "账务", "is_correct": false, "explanation": "「账务」（zhàngwù）与「债务」（zhàiwù）只有韵母不同：ài 与 àng，意思是账目方面的事务。"}, {"text": "财务", "is_correct": false, "explanation": "「财务」（cáiwù）与「债务」（zhàiwù）声母不同：c 与 zh，声调也不同（二声与四声），意思是财产和账目方面的事务。"}, {"text": "站务", "is_correct": false, "explanation": "「站务」（zhànwù）与「债务」（zhàiwù）韵母不同：an 与 ai，意思是车站的事务。"}, {"text": "职务", "is_correct": false, "explanation": "「职务」（zhíwù）与「债务」（zhàiwù）的韵母和声调都不同，意思是工作中的岗位和责任。"}], "explanations": {"债务": "「债务」指欠别人的钱，需要偿还，是本题的正确答案。", "账务": "「账务」（zhàngwù）与「债务」（zhàiwù）只有韵母不同：ài 与 àng，意思是账目方面的事务。", "财务": "「财务」（cáiwù）与「债务」（zhàiwù）声母不同：c 与 zh，声调也不同（二声与四声），意思是财产和账目方面的事务。", "站务": "「站务」（zhànwù）与「债务」（zhàiwù）韵母不同：an 与 ai，意思是车站的事务。", "职务": "「职务」（zhíwù）与「债务」（zhàiwù）的韵母和声调都不同，意思是工作中的岗位和责任。"}, "sentence_index": null, "correct_answer": "债务"}, "level_3": {"options": [{"text": "债务", "is_correct": true, "explanation": "正确：借了很多钱之后欠下的钱正是「债务」，与句意一致。"}, {"text": "存款", "is_correct": false, "explanation": "语义：存款是存进银行的钱，与「借了很多钱」的负债情况正好相反，句子不通。"}, {"text": "奖金", "is_correct": false, "explanation": "语义：奖金是额外得到的钱，与「借钱」无关，放在这里句意矛盾。"}, {"text": "债主", "is_correct": false, "explanation": "搭配：「一大笔」修饰的是钱款，不能修饰人；「债主」指借钱给别人的人。"}], "explanations": {"债务": "正确：借了很多钱之后欠下的钱正是「债务」，与句意一致。", "存款": "语义：存款是存进银行的钱，与「借了很多钱」的负债情况正好相反，句子不通。", "奖金": "语义：奖金是额外得到的钱，与「借钱」无关，放在这里句意矛盾。", "债主": "搭配：「一大笔」修饰的是钱款，不能修饰人；「债主」指借钱给别人的人。"}, "sentence_index": 0, "correct_answer": "债务"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向同事申请了一笔债务，买了新电脑。", "explanation": "这里应该用〈借款〉。申请的是借款；债务指已经欠下、需要偿还的钱，不能去申请。"}, {"text": "这家银行向小企业发放了很多债务。", "explanation": "这里应该用〈贷款〉。银行发放的是贷款；债务是已经欠下的钱，不能由银行发放。"}, {"text": "他拥有一笔债务，对方到期会还他钱。", "explanation": "这里应该用〈债权〉。债权是别人欠自己的钱，对方要还钱给他，应该说债权；债务是自己欠别人的钱，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "债务", "is_correct": true, "explanation": "正确：用工资一点一点偿还的是「债务」，句意通顺。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资是用来还债的手段，不能再作为被还的对象，句子自相矛盾。"}, {"text": "收入", "is_correct": false, "explanation": "搭配：「还」的对象是欠下的钱，不能说「还收入」。"}, {"text": "利润", "is_correct": false, "explanation": "搭配：利润是赚来的钱，不能说「还利润」。"}], "explanations": {"债务": "正确：用工资一点一点偿还的是「债务」，句意通顺。", "工资": "语义：工资是用来还债的手段，不能再作为被还的对象，句子自相矛盾。", "收入": "搭配：「还」的对象是欠下的钱，不能说「还收入」。", "利润": "搭配：利润是赚来的钱，不能说「还利润」。"}, "sentence_index": 6, "correct_answer": "债务"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每个月都向银行存入一笔债务。", "explanation": "这里不能用「存入」。存入银行的是存款；债务是欠别人的钱，要还，不能存进银行。"}, {"text": "这笔债务的颜色很鲜艳。", "explanation": "这里把〈债务〉当成了〈布料〉这类有颜色的实物。债务是欠钱的关系，没有颜色，不能用「鲜艳」形容。"}, {"text": "他每天都在给债务打电话。", "explanation": "「打电话」的对象必须是人或机构，债务不能打电话；这里应该说「还债务」之类的表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一年内终于还清了一只债务。", "corrected_sentence": "他一年内终于还清了一笔债务。", "error_description": "量词错误：「债务」应搭配量词「笔」，不能用「只」。正确说法是「一笔债务」，「只」只用于动物、成对物品中的单个等，不能修饰「债务」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每个月都还在债务，压力很大。", "corrected_sentence": "他每个月都在还债务，压力很大。", "error_description": "错误：进行体「在」位置不对。正确说法是「在还债务」，「在」要放在动词「还」前面，不能说「还在债务」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
