INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人早期的经历或家庭社会背景。", "primary_collocate": null, "pronunciation": "chū shēn", "ipa": "ʈʂʰu˥ ʂən˥", "syllable_count": 2, "sentences": [{"text": "他的出身很普通，但是很有能力。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管出身怎么样，大家都应该有机会。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从不谈自己的出身。", "target_word": "出身", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板不看出身，只看能力。", "target_word": "出身", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的出身并不好，但他没有放弃。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出身不能决定一个人的将来。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师的出身是农民家庭。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们常常用出身来看别人，这样不好。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想改变自己的出身。", "target_word": "出身", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "虽然出身很低，他还是成了校长。", "target_word": "出身", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "家庭出身", "label": "复合"}], "register": "中性", "sense_fingerprint": "出身：名词，一个人早期的经历或家庭社会背景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6d9584a-0189-4503-ada2-5a16c38af2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "出身", "is_correct": true, "explanation": "「出身」指一个人早期的经历或家庭社会背景，是本题的正确答案。"}, {"text": "出生", "is_correct": false, "explanation": "「出生」（chūshēng）与「出身」（chūshēn）只有韵母不同：eng 与 en，意思是婴儿来到世上。"}, {"text": "出神", "is_correct": false, "explanation": "「出神」（chūshén）与「出身」声调不同（二声与一声），意思是注意力集中到发呆的状态。"}, {"text": "出山", "is_correct": false, "explanation": "「出山」（chūshān）与「出身」韵母不同：an 与 en，意思是离开隐居重新做事。"}, {"text": "初审", "is_correct": false, "explanation": "「初审」（chūshěn）与「出身」声调不同（三声与一声），意思是第一次审理。"}], "explanations": {"出身": "「出身」指一个人早期的经历或家庭社会背景，是本题的正确答案。", "出生": "「出生」（chūshēng）与「出身」（chūshēn）只有韵母不同：eng 与 en，意思是婴儿来到世上。", "出神": "「出神」（chūshén）与「出身」声调不同（二声与一声），意思是注意力集中到发呆的状态。", "出山": "「出山」（chūshān）与「出身」韵母不同：an 与 en，意思是离开隐居重新做事。", "初审": "「初审」（chūshěn）与「出身」声调不同（三声与一声），意思是第一次审理。"}, "sentence_index": null, "correct_answer": "出身"}, "level_3": {"options": [{"text": "出身", "is_correct": true, "explanation": "正确：「出身很普通」说的是家庭背景，与「但是很有能力」形成对比，句意通顺。"}, {"text": "能力", "is_correct": false, "explanation": "语义：「能力很普通，但是很有能力」自相矛盾，句子说的是背景，不是能力。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「普通」一般不用来修饰年龄，不能说「年龄很普通」。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：「寿命」不用「普通」来形容，这样说不自然。"}], "explanations": {"出身": "正确：「出身很普通」说的是家庭背景，与「但是很有能力」形成对比，句意通顺。", "能力": "语义：「能力很普通，但是很有能力」自相矛盾，句子说的是背景，不是能力。", "年龄": "搭配：「普通」一般不用来修饰年龄，不能说「年龄很普通」。", "寿命": "搭配：「寿命」不用「普通」来形容，这样说不自然。"}, "sentence_index": 0, "correct_answer": "出身"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的出身很丰富，去过很多国家。", "explanation": "这里应该用〈经历〉。出身指家庭背景，不能说「丰富」；丰富的是经历。"}, {"text": "他把出身放进了箱子里。", "explanation": "出身是抽象的背景，不能装进箱子；放进箱子的必须是实物。"}, {"text": "这家餐厅的出身特别好吃。", "explanation": "出身不是食物，不能用「好吃」形容；评价菜的好坏应说〈味道〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出身", "is_correct": true, "explanation": "正确：「这位老师的出身是农民家庭」说的是家庭背景，句意通顺。"}, {"text": "家乡", "is_correct": false, "explanation": "语义：家乡是地方，不是家庭，不能说「家乡是农民家庭」。"}, {"text": "职业", "is_correct": false, "explanation": "语义：职业指工作，不能说「职业是农民家庭」。"}, {"text": "学历", "is_correct": false, "explanation": "搭配：学历指受教育的程度，不能用「是农民家庭」来说明。"}], "explanations": {"出身": "正确：「这位老师的出身是农民家庭」说的是家庭背景，句意通顺。", "家乡": "语义：家乡是地方，不是家庭，不能说「家乡是农民家庭」。", "职业": "语义：职业指工作，不能说「职业是农民家庭」。", "学历": "搭配：学历指受教育的程度，不能用「是农民家庭」来说明。"}, "sentence_index": 6, "correct_answer": "出身"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把出身打包寄走了。", "explanation": "这里把〈出身〉当成了〈包裹〉这类实物。出身是抽象的家庭背景和经历，不能打包寄走。"}, {"text": "他的出身考完了三门课。", "explanation": "「考」的对象是科目，出身不能被考。"}, {"text": "他的出身今天很便宜。", "explanation": "这里把〈出身〉当成了〈商品〉。出身是家庭背景和经历，没有价格，不能说「便宜」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她出身为农民家庭，但很努力。", "corrected_sentence": "她出身于农民家庭，但很努力。", "error_description": "错误：介词用错。「出身为」不对，正确说法是「出身于」，介词「于」引出出身的家庭或地方。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是护士出身了，经验很丰富。", "corrected_sentence": "她是护士出身，经验很丰富。", "error_description": "错误：「出身」后面不能加「了」。「是……出身」表示出身的状态，句末不用「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
