INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用尖物在物体表面划过，也指用桨拨水前进。", "primary_collocate": null, "pronunciation": "huá", "ipa": "xwa˧˥", "syllable_count": 1, "sentences": [{"text": "他划破了手指。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们去湖里划船。", "target_word": "划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他划了一根火柴。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心，这把刀会划手。", "target_word": "划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我们在公园划小船。", "target_word": "划", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "树枝划过他的脸，有点疼。", "target_word": "划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用力划桨，船走得很快。", "target_word": "划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们坐在船上，慢慢地划着。", "target_word": "划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树枝把他的手划了一道口子。", "target_word": "划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用小刀划开信封。", "target_word": "划", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "划了", "label": "完成体"}, {"form": "划着", "label": "持续体"}, {"form": "劃", "label": "繁体"}], "register": "中性", "sense_fingerprint": "划·huá·尖物划过表面；用桨拨水前进", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93996, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "划", "is_correct": true, "explanation": "正确答案。huá 指尖物划过表面，或用桨拨水前进。"}, {"text": "话", "is_correct": false, "explanation": "声调不同：huà（第四声）与 huá（第二声）不同，意思是话语。"}, {"text": "花", "is_correct": false, "explanation": "声调不同：huā（第一声）与 huá（第二声）不同，意思是花朵。"}, {"text": "环", "is_correct": false, "explanation": "韵母不同：huán 比 huá 多一个 -n，意思是圆环。"}, {"text": "黄", "is_correct": false, "explanation": "韵母不同：huáng 比 huá 多一个 -ng，意思是黄色。"}], "explanations": {"划": "正确答案。huá 指尖物划过表面，或用桨拨水前进。", "话": "声调不同：huà（第四声）与 huá（第二声）不同，意思是话语。", "花": "声调不同：huā（第一声）与 huá（第二声）不同，意思是花朵。", "环": "韵母不同：huán 比 huá 多一个 -n，意思是圆环。", "黄": "韵母不同：huáng 比 huá 多一个 -ng，意思是黄色。"}, "sentence_index": null, "correct_answer": "划"}, "level_3": {"options": [{"text": "划", "is_correct": true, "explanation": "正确。划破表示尖物刮伤表面，与“手指”相合。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：撕用于纸、布等，不说撕破手指。"}, {"text": "缝", "is_correct": false, "explanation": "语义：缝是用针线连缀，不会把手指弄破。"}, {"text": "写", "is_correct": false, "explanation": "语义：写字与划破手指无关，语义不通。"}], "explanations": {"划": "正确。划破表示尖物刮伤表面，与“手指”相合。", "撕": "搭配：撕用于纸、布等，不说撕破手指。", "缝": "语义：缝是用针线连缀，不会把手指弄破。", "写": "语义：写字与划破手指无关，语义不通。"}, "sentence_index": 0, "correct_answer": "划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "厨师用刀划了一块肉。", "explanation": "这里应该用〈割〉。割指切开，说割肉；划指轻刮、划破表面，不表示切下一块。"}, {"text": "我们在湖上划了一条汽艇。", "explanation": "这里应该用〈开〉。划指用桨拨水前进，汽艇靠机器行驶，要说开汽艇，不能说划。"}, {"text": "他用力划了一下窗帘。", "explanation": "这里应该用〈拉〉。划指用尖物刮过表面或用桨拨水，拉窗帘要用〈拉〉，不能说划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93996, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "划", "is_correct": true, "explanation": "正确答案。huá 指尖物划过表面，或用桨拨水前进。"}, {"text": "画", "is_correct": false, "explanation": "声调不同：huà（第四声）与 huá（第二声）不同，意思是绘画。"}, {"text": "化", "is_correct": false, "explanation": "声调不同：huà（第四声）与 huá（第二声）不同，意思是变化。"}, {"text": "怀", "is_correct": false, "explanation": "韵母不同：huái 比 huá 多一个 -i，意思是怀抱。"}, {"text": "还", "is_correct": false, "explanation": "韵母不同：huán 比 huá 多一个 -n，意思是归还。"}], "explanations": {"划": "正确答案。huá 指尖物划过表面，或用桨拨水前进。", "画": "声调不同：huà（第四声）与 huá（第二声）不同，意思是绘画。", "化": "声调不同：huà（第四声）与 huá（第二声）不同，意思是变化。", "怀": "韵母不同：huái 比 huá 多一个 -i，意思是怀抱。", "还": "韵母不同：huán 比 huá 多一个 -n，意思是归还。"}, "sentence_index": null, "correct_answer": "划"}, "level_3": {"options": [{"text": "划", "is_correct": true, "explanation": "正确。划桨即用桨拨水前进，与“船走得很快”相合。"}, {"text": "扛", "is_correct": false, "explanation": "语义：扛是用肩承担重物，与船走得快无关。"}, {"text": "砍", "is_correct": false, "explanation": "语义：砍是劈断，不能使船前进。"}, {"text": "捆", "is_correct": false, "explanation": "搭配：捆用于绳索、货物，不说捆桨。"}], "explanations": {"划": "正确。划桨即用桨拨水前进，与“船走得很快”相合。", "扛": "语义：扛是用肩承担重物，与船走得快无关。", "砍": "语义：砍是劈断，不能使船前进。", "捆": "搭配：捆用于绳索、货物，不说捆桨。"}, "sentence_index": 6, "correct_answer": "划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力划了一下鼓。", "explanation": "这里应该用〈打〉。打鼓是敲击，划只用于刮擦表面或划船。"}, {"text": "她用扫帚划了一下地。", "explanation": "这里应该用〈扫〉。扫地用扫帚扫，划表示刮过表面，不表示清扫。"}, {"text": "他用力划了一下门铃。", "explanation": "这里应该用〈按〉。划指刮过表面或用桨拨水，按门铃是用手指压下去，要用〈按〉，不能说划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不小心划破的袖子。", "corrected_sentence": "她不小心划破了袖子。", "error_description": "“了”误用为“的”：“划破的袖子”是名词短语，不能单独成句作陈述。应说“她不小心划破了袖子。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (93996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在湖上划了一个船。", "corrected_sentence": "我们在湖上划了一条船。", "error_description": "量词错误：“船”的量词应为“条”，不能用“个”，应说“划了一条船”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
