INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94006, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上下牙齿用力夹住或夹碎东西。", "primary_collocate": null, "pronunciation": "yǎo", "ipa": "jɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个苹果太硬了，我咬不动。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用牙把坚果咬碎，放进嘴里。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心点，别把舌头咬到了。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠把桌子上的纸咬了一个洞。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她紧张得咬着嘴唇，一句话也不说。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "狗把我的新鞋咬坏了。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块肉太老了，怎么咬也咬不烂。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口咬下去，糖果就碎了。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子爱咬铅笔，笔上都是牙印。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线很结实，用牙咬不断。", "target_word": "咬", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "咬了", "label": "完成体"}, {"form": "咬着", "label": "持续体"}, {"form": "咬过", "label": "经历体"}, {"form": "咬碎", "label": "复合词"}, {"form": "咬断", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用力用牙咬、咬碎、咬断、咬出痕迹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。咬 yǎo 表示用牙齿夹住或夹碎东西。"}, {"text": "要", "is_correct": false, "explanation": "yào（第四声）与 yǎo（第三声）声调不同，意思是“要”。"}, {"text": "好", "is_correct": false, "explanation": "h 与 y 声母不同，声调相同，意思是“好”。"}, {"text": "老", "is_correct": false, "explanation": "l 与 y 声母不同，声调相同，意思是“老”。"}, {"text": "考", "is_correct": false, "explanation": "k 与 y 声母不同，声调相同，意思是“考试”。"}, {"text": "腰", "is_correct": false, "explanation": "yāo（第一声）与 yǎo（第三声）声调不同，意思是“腰”。"}], "explanations": {"咬": "正确答案。咬 yǎo 表示用牙齿夹住或夹碎东西。", "要": "yào（第四声）与 yǎo（第三声）声调不同，意思是“要”。", "好": "h 与 y 声母不同，声调相同，意思是“好”。", "老": "l 与 y 声母不同，声调相同，意思是“老”。", "考": "k 与 y 声母不同，声调相同，意思是“考试”。", "腰": "yāo（第一声）与 yǎo（第三声）声调不同，意思是“腰”。"}, "sentence_index": null, "correct_answer": "咬"}, "level_3": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。“咬不动”表示用牙夹不动，与“苹果太硬”的语境一致。"}, {"text": "推", "is_correct": false, "explanation": "语义：“推不动”指推动物体，与硬苹果咬不动的意思不符。"}, {"text": "拉", "is_correct": false, "explanation": "语义：“拉不动”指拉动物体，与苹果太硬、无法用牙夹断的意思不符。"}, {"text": "举", "is_correct": false, "explanation": "搭配：“举不动”多用于形容重物，苹果并不重，与“太硬”的语境搭配不当。"}], "explanations": {"咬": "正确答案。“咬不动”表示用牙夹不动，与“苹果太硬”的语境一致。", "推": "语义：“推不动”指推动物体，与硬苹果咬不动的意思不符。", "拉": "语义：“拉不动”指拉动物体，与苹果太硬、无法用牙夹断的意思不符。", "举": "搭配：“举不动”多用于形容重物，苹果并不重，与“太硬”的语境搭配不当。"}, "sentence_index": 0, "correct_answer": "咬"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他咬了一口汤，觉得太咸了。", "explanation": "这里应该用〈尝〉。咬要用牙夹住固体食物，汤是液体，不能用“咬”。"}, {"text": "他用手把纸咬碎了。", "explanation": "这里应该用〈撕〉。“咬”要用牙齿夹碎东西，用手弄碎纸应说“撕碎”。"}, {"text": "他用剪刀咬断了那根线。", "explanation": "“咬”只能用牙齿，不能借助剪刀；这里应该说“剪断”，不能用“咬”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94006, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。咬 yǎo 表示用牙齿夹住或夹碎东西。"}, {"text": "药", "is_correct": false, "explanation": "yào（第四声）与 yǎo（第三声）声调不同，意思是“药”。"}, {"text": "脑", "is_correct": false, "explanation": "n 与 y 声母不同，声调相同，意思是“大脑”。"}, {"text": "草", "is_correct": false, "explanation": "c 与 y 声母不同，声调相同，意思是“草”。"}, {"text": "跑", "is_correct": false, "explanation": "p 与 y 声母不同，声调相同，意思是“跑步”。"}, {"text": "饱", "is_correct": false, "explanation": "b 与 y 声母不同，声调相同，意思是“吃饱”。"}], "explanations": {"咬": "正确答案。咬 yǎo 表示用牙齿夹住或夹碎东西。", "药": "yào（第四声）与 yǎo（第三声）声调不同，意思是“药”。", "脑": "n 与 y 声母不同，声调相同，意思是“大脑”。", "草": "c 与 y 声母不同，声调相同，意思是“草”。", "跑": "p 与 y 声母不同，声调相同，意思是“跑步”。", "饱": "b 与 y 声母不同，声调相同，意思是“吃饱”。"}, "sentence_index": null, "correct_answer": "咬"}, "level_3": {"options": [{"text": "咬", "is_correct": true, "explanation": "正确答案。“怎么咬也咬不烂”前后动作一致，符合“太老”的语境。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“怎么切也咬不烂”前后动作不一致，“切”与后面的“咬不烂”不呼应。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”与后面的“咬不烂”不呼应，前后语义断裂。"}, {"text": "喝", "is_correct": false, "explanation": "语义：喝是饮用，不能施于肉块，“怎么喝也咬不烂”不成立。"}], "explanations": {"咬": "正确答案。“怎么咬也咬不烂”前后动作一致，符合“太老”的语境。", "切": "搭配：“怎么切也咬不烂”前后动作不一致，“切”与后面的“咬不烂”不呼应。", "撕": "搭配：“撕”与后面的“咬不烂”不呼应，前后语义断裂。", "喝": "语义：喝是饮用，不能施于肉块，“怎么喝也咬不烂”不成立。"}, "sentence_index": 6, "correct_answer": "咬"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他咬了一下门铃，然后走了进去。", "explanation": "这里应该用〈按〉。“咬”表示用牙齿夹住或夹碎东西，按门铃应说“按”，不能说“咬”。"}, {"text": "他咬了一口烟，然后吐了出来。", "explanation": "这里应该用〈抽〉。“咬”表示用牙齿夹住东西，吸烟应说“抽”，不能说“咬了一口”。"}, {"text": "他咬了一口空气，然后走出了房间。", "explanation": "这里应该用〈吸〉。“咬”要用牙夹住东西，空气不能被牙咬，应说“吸了一口空气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他咬了一口苹果着，又放下了。", "corrected_sentence": "他咬了一口苹果，又放下了。", "error_description": "“着”放在宾语“苹果”之后，位置错误。“咬一口”是一次性动作，应说“咬了一口苹果”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把硬糖碎咬了。", "corrected_sentence": "他把硬糖咬碎了。", "error_description": "错误形式“碎咬了”，正确形式“咬碎了”。结果补语“碎”必须紧跟动词“咬”之后，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "解放：使受压迫的人摆脱控制而获得自由，与“压迫”构成反义。"}, {"text": "保护", "is_correct": false, "explanation": "保护：照顾并防止受到伤害，不是“压迫”的反义词。"}, {"text": "培养", "is_correct": false, "explanation": "培养：有计划地教育、扶持使其成长，与“压迫”不构成反义。"}, {"text": "同意", "is_correct": false, "explanation": "同意：表示赞成或认可，与“压迫”不是反义关系。"}], "correct_answer": "解放", "explanations": {"解放": "解放：使受压迫的人摆脱控制而获得自由，与“压迫”构成反义。", "保护": "保护：照顾并防止受到伤害，不是“压迫”的反义词。", "培养": "培养：有计划地教育、扶持使其成长，与“压迫”不构成反义。", "同意": "同意：表示赞成或认可，与“压迫”不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "解放：使受压迫的人摆脱控制而获得自由，与“压迫”构成反义。"}, {"text": "支持", "is_correct": false, "explanation": "支持：赞成并帮助，与“压迫”不构成反义。"}, {"text": "尊重", "is_correct": false, "explanation": "尊重：重视并以礼相待，与“压迫”不是反义关系。"}, {"text": "忘记", "is_correct": false, "explanation": "忘记：记不住或不再记得，与“压迫”无关。"}], "correct_answer": "解放", "explanations": {"解放": "解放：使受压迫的人摆脱控制而获得自由，与“压迫”构成反义。", "支持": "支持：赞成并帮助，与“压迫”不构成反义。", "尊重": "尊重：重视并以礼相待，与“压迫”不是反义关系。", "忘记": "忘记：记不住或不再记得，与“压迫”无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "压迫是用权势或很大的力量欺负别人，使别人不能反抗。", "primary_collocate": null, "pronunciation": "yā pò", "ipa": "jä˥ pʰwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "古时候，有钱人常常压迫穷人。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板压迫工人，让他们每天工作十几个小时。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国王压迫老百姓，大家都很生气。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大人不应该压迫小孩，要听听他们的想法。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个恶霸经常压迫弱小的同学。", "target_word": "压迫", "complexity_tier": "T3", "furigana": "nà gè è bà jīng cháng yā pò ruò xiǎo de tóng xué", "sentence_source": "generated"}, {"text": "地主压迫农民很多年，农民终于站起来了。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强国不能压迫弱国，每个国家都应平等。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得公司在压迫她，每天都不让她休息。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们反抗那些压迫人民的坏官。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要是有人压迫你，你要告诉老师。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压迫了", "label": "体标（了）"}, {"form": "压迫着", "label": "体标（着）"}, {"form": "压迫过", "label": "体标（过）"}, {"form": "壓迫", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "压迫：用权势或力量欺负他人，使人不能反抗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d7132db-349d-4d06-b68d-82e6dd273dcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压迫", "is_correct": true, "explanation": "压迫：用权势或力量欺负他人，使人不能反抗，正合“有钱人欺压穷人”的情境。"}, {"text": "拥有", "is_correct": false, "explanation": "搭配：“拥有”表示占有，不含欺压之意，与句中“常常欺压穷人”的语义不合。"}, {"text": "建造", "is_correct": false, "explanation": "语义：“建造”指修建房屋、建筑等，与人无关。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指栽种植物，不能用于人。"}], "explanations": {"压迫": "压迫：用权势或力量欺负他人，使人不能反抗，正合“有钱人欺压穷人”的情境。", "拥有": "搭配：“拥有”表示占有，不含欺压之意，与句中“常常欺压穷人”的语义不合。", "建造": "语义：“建造”指修建房屋、建筑等，与人无关。", "种植": "语义：“种植”指栽种植物，不能用于人。"}, "sentence_index": 0, "correct_answer": "压迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他压迫嗓门，小声地跟我说话。", "explanation": "这里应该用〈压低〉。压低指降低声音；压迫指以权势欺压或施加压力，不能用于嗓门。"}, {"text": "妈妈压迫我快点起床。", "explanation": "这里应该用〈催促〉。压迫指以权势或强力欺压，语义过重，不能用于一般的催促。"}, {"text": "他用道理压迫了大家，大家都不再争了。", "explanation": "这里应该用〈压服〉。压服指用道理或力量使人服从；压迫指以权势欺压或施加压力，不用于说理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压迫", "is_correct": true, "explanation": "压迫：以强力或权势欺压他人，正合“强国欺压弱国”的语境。"}, {"text": "喂养", "is_correct": false, "explanation": "语义：“喂养”指给动物或幼儿提供食物，不能用于国家。"}, {"text": "洗涤", "is_correct": false, "explanation": "语义：“洗涤”指用水清洗物品，与国家无关。"}, {"text": "比较", "is_correct": false, "explanation": "语义：“比较”指对照、衡量，不含欺压之意，与“强国不能……弱国”的语境不合。"}], "explanations": {"压迫": "压迫：以强力或权势欺压他人，正合“强国欺压弱国”的语境。", "喂养": "语义：“喂养”指给动物或幼儿提供食物，不能用于国家。", "洗涤": "语义：“洗涤”指用水清洗物品，与国家无关。", "比较": "语义：“比较”指对照、衡量，不含欺压之意，与“强国不能……弱国”的语境不合。"}, "sentence_index": 6, "correct_answer": "压迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士压迫病人，病人很快就好了。", "explanation": "这里应该用〈照顾〉。压迫指以权势欺压他人，用于护理病人是错误的。"}, {"text": "大家压迫这个方案，所以它顺利实施了。", "explanation": "这里应该用〈支持〉。压迫的对象是人，且含欺压之意，不能用于方案。"}, {"text": "她压迫着心里的悲伤，没有哭出来。", "explanation": "这里应该用〈压抑〉。压抑指克制感情使其不外露；压迫是外力欺压，不用于心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "富人把穷人压迫。", "corrected_sentence": "富人把穷人压迫得喘不过气来。", "error_description": "“把”字句中动词“压迫”后需要补语，应说“富人把穷人压迫得喘不过气来”；只说“把穷人压迫”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板在压迫了工人很久，工人们终于忍不住了。", "corrected_sentence": "老板压迫了工人很久，工人们终于忍不住了。", "error_description": "“在”表示动作正在进行，与动词后的“了”（表示完成）不能同时使用，应去掉“在”，说“老板压迫了工人很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
