INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对物体或身体部位施加压力，使其受挤压。", "primary_collocate": null, "pronunciation": "yā pò", "ipa": "jä˥ pʰwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "石头压迫着他的腿，他站不起来。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肿块压迫神经，所以他的手很疼。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雪压迫着屋顶，房子快要坏了。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个姿势会压迫胸部，睡觉时不舒服。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说骨头压迫了神经，要做手术。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手压迫伤口，血很快就止住了。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太紧的鞋会压迫脚，走路很疼。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "千斤顶用力压迫汽车底部，把车抬了起来。", "target_word": "压迫", "complexity_tier": "T3", "furigana": "qiān jīn dǐng yòng lì yā pò qì chē dǐ bù bǎ chē tái le qǐ lái", "sentence_source": "generated"}, {"text": "太重的书包压迫着孩子的肩膀。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车门用力压迫了他的手指，他疼得大叫起来。", "target_word": "压迫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "压迫了", "label": "体标（了）"}, {"form": "压迫着", "label": "体标（着）"}, {"form": "压迫过", "label": "体标（过）"}, {"form": "壓迫", "label": "繁体"}], "register": "书面语", "sense_fingerprint": "压迫：对物体或身体部位施加压力，使其受挤压", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d7132db-349d-4d06-b68d-82e6dd273dcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "压迫", "is_correct": true, "explanation": "压迫：对物体施加压力，正合“石头压着腿”的语境。"}, {"text": "欺负", "is_correct": false, "explanation": "语义：“欺负”指人对人的恶意侵害，石头不能欺负人。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：“拥抱”指双臂环抱人，不能用于石头压在腿上。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的宾语是衣物、鞋袜，不能说“穿着他的腿”。"}], "explanations": {"压迫": "压迫：对物体施加压力，正合“石头压着腿”的语境。", "欺负": "语义：“欺负”指人对人的恶意侵害，石头不能欺负人。", "拥抱": "语义：“拥抱”指双臂环抱人，不能用于石头压在腿上。", "穿": "搭配：“穿”的宾语是衣物、鞋袜，不能说“穿着他的腿”。"}, "sentence_index": 0, "correct_answer": "压迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直压迫价钱，店主只好便宜卖了。", "explanation": "这里应该用〈压价〉。压价指压低价格；压迫指以权势欺压或施加压力，不能用于价格。"}, {"text": "他压迫着心中的悲伤，没有哭出来。", "explanation": "这里应该用〈压抑〉。压抑指克制感情使其不外露；压迫指对身体或物体施加压力，不用于感情。"}, {"text": "这个软件可以压迫图片，让文件变小。", "explanation": "这里应该用〈压缩〉。压缩指减小体积；压迫指施加力量使人屈服或身体受压，不能用于图片或文件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "压迫", "is_correct": true, "explanation": "压迫：对身体施加压力，正合“鞋太紧压着脚”的语境。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：“安慰”指使人舒心，鞋不能安慰脚，且与“走路很疼”矛盾。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“保护”指防护，与“走路很疼”的结果矛盾。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”的宾语是帽子、眼镜等，不能用于脚（鞋袜应说“穿”）。"}], "explanations": {"压迫": "压迫：对身体施加压力，正合“鞋太紧压着脚”的语境。", "安慰": "语义：“安慰”指使人舒心，鞋不能安慰脚，且与“走路很疼”矛盾。", "保护": "语义：“保护”指防护，与“走路很疼”的结果矛盾。", "戴": "搭配：“戴”的宾语是帽子、眼镜等，不能用于脚（鞋袜应说“穿”）。"}, "sentence_index": 6, "correct_answer": "压迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生压迫病人，病人很快就好了。", "explanation": "这里应该用〈照顾〉。压迫指以权势欺压他人，用于护理病人是错误的。"}, {"text": "大家压迫这个方案，所以它顺利实施了。", "explanation": "这里应该用〈支持〉。压迫的对象是人，且含欺压之意，不能用于方案。"}, {"text": "我们压迫了工期，结果做得很粗糙。", "explanation": "这里应该用〈压缩〉。压缩指缩短时间或减小体积；压迫指施加力量使人屈服或身体受压，不用于工期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那块大石头把他的腿压迫。", "corrected_sentence": "那块大石头把他的腿压迫得动弹不得。", "error_description": "“把”字句中动词“压迫”后需要补语，应说“把他的腿压迫得动弹不得”；只说“把他的腿压迫”，句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙倒下来在压迫了他的后背很久，救护车才赶到。", "corrected_sentence": "墙倒下来压迫了他的后背很久，救护车才赶到。", "error_description": "“在”表示动作正在进行，与动词后的“了”（表示完成）不能同时使用，应去掉“在”，说“墙倒下来压迫了他的后背很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
