INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94010, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "有多个政党的。", "primary_collocate": null, "pronunciation": "duō dǎng", "ipa": "tuɔ˥ tɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "那是一个多党国家，有七个政党。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多党选举让人民有更多选择。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在多党国家，不同的政党会争取选票。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在一个多党的国家长大。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家过去是一党，现在实行多党制。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多党议会里，没有一个党能独自决定一切。", "target_word": "多党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，多党社会里常常有不同的声音。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在书上读到过一个多党国家的故事。", "target_word": "多党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在多党政治中，小党也可以有自己的位置。", "target_word": "多党", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个多党联盟由三个政党组成。", "target_word": "多党", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "多党制", "label": "复合"}, {"form": "多黨", "label": "繁体"}], "register": "书面", "sense_fingerprint": "多党·duō dǎng·有多个政党的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96e26a56-c268-4fa2-ac9c-592556122806') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多党", "is_correct": true, "explanation": "正确。多党国家指有多个政党，与“有七个政党”相合。"}, {"text": "一党", "is_correct": false, "explanation": "语义：一党指只有一个政党，与“有七个政党”矛盾。"}, {"text": "无党", "is_correct": false, "explanation": "搭配：无党指没有政党归属，不能直接修饰“国家”。"}, {"text": "单党", "is_correct": false, "explanation": "语义：单党指只有一个政党，与“有七个政党”矛盾。"}], "explanations": {"多党": "正确。多党国家指有多个政党，与“有七个政党”相合。", "一党": "语义：一党指只有一个政党，与“有七个政党”矛盾。", "无党": "搭配：无党指没有政党归属，不能直接修饰“国家”。", "单党": "语义：单党指只有一个政党，与“有七个政党”矛盾。"}, "sentence_index": 0, "correct_answer": "多党"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的文化是多党的。", "explanation": "这里应该用〈多元〉。多党指政党数量多，形容文化、思想要用〈多元〉，不能说多党。"}, {"text": "这片森林的生物是多党的。", "explanation": "这里应该用〈多样〉。多党只说政党数量，形容生物的种类要用〈多样〉，不能说多党。"}, {"text": "两国签了多党协议。", "explanation": "这里应该用〈多边〉。多党指政党多，两国之间的协议要用〈多边〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多党", "is_correct": true, "explanation": "正确。多党社会指有多个政党的社会，与“不同的声音”相合。"}, {"text": "同质", "is_correct": false, "explanation": "语义：同质指成分一致，与“常常有不同的声音”矛盾。"}, {"text": "单一", "is_correct": false, "explanation": "语义：单一指只有一种，与“不同的声音”相悖。"}, {"text": "统一", "is_correct": false, "explanation": "搭配：统一多用于整体一致，不说统一社会。"}], "explanations": {"多党": "正确。多党社会指有多个政党的社会，与“不同的声音”相合。", "同质": "语义：同质指成分一致，与“常常有不同的声音”矛盾。", "单一": "语义：单一指只有一种，与“不同的声音”相悖。", "统一": "搭配：统一多用于整体一致，不说统一社会。"}, "sentence_index": 6, "correct_answer": "多党"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座塔是多党的。", "explanation": "这里应该用〈多层〉。多党只说政党数量，形容塔的层数要用〈多层〉，不能说多党。"}, {"text": "我们完成了多党任务。", "explanation": "这里应该用〈多项〉。多党指政党多，任务的数量要用〈多项〉。"}, {"text": "这份工作有多党困难。", "explanation": "这里应该用〈多重〉。多党只用于政党，困难的层次要用〈多重〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家的议会是多党。", "corrected_sentence": "这个国家的议会是多党的。", "error_description": "“多党”是非谓形容词，不能单独作谓语，作谓语时须带“的”，应说“是多党的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个地区是多党地。", "corrected_sentence": "那个地区是多党的。", "error_description": "“多党”作谓语时须用“的”，误用“地”不成立，“是……地”不能成句。应说“那个地区是多党的。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9fff2ef6-382c-4da9-8b0d-fcbf4e8d241c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
