INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94014, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自己或他人的妻子。", "primary_collocate": null, "pronunciation": "tài tai", "ipa": "tʰaɪ˥˩ tʰaɪ", "syllable_count": 2, "sentences": [{"text": "我太太是老师。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他太太今天不在家。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张带着太太去旅行了。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给太太买了一束花。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你太太做的菜真好吃。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天开车送太太上班。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我想陪太太去看电影。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生的太太是医生。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和太太结婚二十年了。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我先问问太太，再告诉你。", "target_word": "太太", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "太太们", "label": "复数"}, {"form": "位", "label": "量词"}, {"form": "老太太", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：自己或他人的妻子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '116981cc-4263-43d0-82cf-0f02bbe0094d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太太", "is_correct": true, "explanation": "“我太太”指自己的妻子，“太太”与自称“我”搭配，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是物件，不能作为“我”的配偶，也不能是老师。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不能作为“我”的配偶，也不能当老师。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不是人，不能作为“我”的配偶。"}], "explanations": {"太太": "“我太太”指自己的妻子，“太太”与自称“我”搭配，符合句意。", "黑板": "语义：黑板是物件，不能作为“我”的配偶，也不能是老师。", "椅子": "语义：椅子是家具，不能作为“我”的配偶，也不能当老师。", "课本": "语义：课本是书，不是人，不能作为“我”的配偶。"}, "sentence_index": 0, "correct_answer": "太太"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他女儿是我的太太。", "explanation": "“太太”指妻子，只能指配偶；女儿与“我”是父女关系，不能作配偶，这里不能说“我的太太”。"}, {"text": "我有一只太太，她很能干。", "explanation": "这里应该用〈位〉。太太指人，量词要用〈位〉，“只”用于动物或物品。"}, {"text": "那位太太刚大学毕业，还没结婚。", "explanation": "这里应该用〈小姐〉。太太只称已婚女子，刚毕业、未婚的女子应称〈小姐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "太太", "is_correct": true, "explanation": "“陪太太去看电影”指陪自己的妻子，“太太”是人，可以被陪同。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能被“陪”去看电影。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是物件，不能被“陪”去看电影。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是物件，不能被“陪”一起去看电影。"}], "explanations": {"太太": "“陪太太去看电影”指陪自己的妻子，“太太”是人，可以被陪同。", "桌子": "语义：桌子是家具，不能被“陪”去看电影。", "雨伞": "语义：雨伞是物件，不能被“陪”去看电影。", "窗户": "语义：窗户是物件，不能被“陪”一起去看电影。"}, "sentence_index": 6, "correct_answer": "太太"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我太太今年五岁，她很聪明。", "explanation": "这里应该用〈女儿〉。太太指妻子，不能指五岁的孩子。"}, {"text": "邻居们都亲切地喊她小丽太太。", "explanation": "这里应该用〈李太太〉这类“姓氏＋太太”的称呼。“太太”前只能加姓氏，不能加名字。"}, {"text": "我哥哥是我的太太。", "explanation": "“太太”指妻子，只能指配偶；哥哥是“我”的亲属，不能作配偶，这里不能说“我的太太”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "张先生的一只太太很早就回家了。", "corrected_sentence": "张先生的一位太太很早就回家了。", "error_description": "量词错误：“太太”指人，应用量词“位”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把太太下班了。", "corrected_sentence": "我太太下班了。", "error_description": "配价错误：“下班”是不及物动词，不能带“把”字宾语，应说“我太太下班了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '470fa1ce-3878-4b8a-a758-1e6bd7970682') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
