INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对年长女性的亲切称呼。", "primary_collocate": null, "pronunciation": "nǎi nai", "ipa": "nai̯˨˩˦ nai̯", "syllable_count": 2, "sentences": [{"text": "奶奶，您慢点走，我来帮您。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车上，小男孩对老人说：“奶奶，请坐。”", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶，请问去医院怎么走？", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边的奶奶很和气，常跟孩子们打招呼。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "隔壁的奶奶常给我们水果。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶，您的东西掉了。", "target_word": "奶奶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位奶奶坐在门口晒太阳。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们叫她奶奶，她很高兴。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶，这条路我带您过去吧。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里有位奶奶找不到她的包。", "target_word": "奶奶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老奶奶", "label": "复合"}], "register": "口语", "sense_fingerprint": "称呼年长女性的亲切用语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6d9584a-0189-4503-ada2-5a16c38af2b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奶奶", "is_correct": true, "explanation": "正确。奶奶是对年长女性的亲切称呼，符合这句话的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能走路，也不能被这样称呼。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能走路，也不能被称呼为长辈。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不能自己走路，句中“慢点走”和“我来帮您”都不适用于婴儿。"}], "explanations": {"奶奶": "正确。奶奶是对年长女性的亲切称呼，符合这句话的语境。", "汽车": "语义：汽车不能走路，也不能被这样称呼。", "桌子": "语义：桌子不能走路，也不能被称呼为长辈。", "婴儿": "语义：婴儿不能自己走路，句中“慢点走”和“我来帮您”都不适用于婴儿。"}, "sentence_index": 0, "correct_answer": "奶奶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶，你的书掉了。", "explanation": "这里应该用〈姐姐〉。奶奶只用于称呼年长女性，不能用来称呼年轻女性。"}, {"text": "我对那位老先生说：“奶奶，您今天身体怎么样？”", "explanation": "这里应该用〈爷爷〉。奶奶只用于称呼年长的女性，称呼老先生应用“爷爷”。"}, {"text": "那位四十岁的女士，我们都叫她奶奶。", "explanation": "这里应该用〈阿姨〉。奶奶只用于称呼年长的女性，四十岁的女士应称“阿姨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奶奶", "is_correct": true, "explanation": "正确。奶奶是对年长女性的称呼，符合“坐在门口晒太阳”的语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会坐，也不会晒太阳。"}, {"text": "花", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“那位花”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会坐，也不会晒太阳。"}], "explanations": {"奶奶": "正确。奶奶是对年长女性的称呼，符合“坐在门口晒太阳”的语境。", "石头": "语义：石头不会坐，也不会晒太阳。", "花": "搭配：量词“位”只用于人，不能说“那位花”。", "桌子": "语义：桌子是家具，不会坐，也不会晒太阳。"}, "sentence_index": 6, "correct_answer": "奶奶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶是我爸爸的哥哥。", "explanation": "这里应该用〈伯伯〉。奶奶只用于称呼年长女性，爸爸的哥哥是男性。"}, {"text": "奶奶是我的同学。", "explanation": "这里应该用〈同学〉。奶奶只用于称呼年长女性，同学是同龄人。"}, {"text": "奶奶是我的小妹妹。", "explanation": "这里应该用〈妹妹〉。奶奶只用于称呼年长女性，小妹妹年纪还小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那位奶奶们在公园里跳舞。", "corrected_sentence": "那些奶奶们在公园里跳舞。", "error_description": "量词错误：“那位”是单数，与表示复数的“们”矛盾，应改为“那些”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们都把她奶奶。", "corrected_sentence": "孩子们都叫她奶奶。", "error_description": "动词错误：称谓结构应为“叫＋人＋称谓”，即“叫她奶奶”。“把”字句需要后接动词和宾语，“把她奶奶”不成立，应把“把”改为“叫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c28db41-0640-44f8-9853-a7135bfdc57c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
