INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "打扰；妨碍正常进行。", "primary_collocate": null, "pronunciation": "gān rǎo", "ipa": "kan˥˩ ʐaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大雾干扰了飞机的正常起飞。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "强风干扰了比赛的进行。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外界的消息不应干扰我们的计划。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气干扰了我们的出行计划。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些问题干扰了会议的正常进行。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "无关的人员不要干扰医生工作。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不让感情干扰判断。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上的施工干扰了交通。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众的喊声干扰了演员表演。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要让小事干扰你的正常生活。", "target_word": "干扰", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干扰了", "label": "完成体"}, {"form": "干扰着", "label": "持续体"}, {"form": "干扰过", "label": "经历体"}, {"form": "干擾", "label": "繁体"}], "register": "中性", "sense_fingerprint": "干扰：外来因素妨碍事情或活动正常进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e60ece-b0ef-49ed-9e2f-beaff451da86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保障", "is_correct": false, "explanation": "语义：“保障”指保证，与“大雾”造成的阻碍相反，句意不通。"}, {"text": "干扰", "is_correct": true, "explanation": "“干扰”指外来因素妨碍事情正常进行，符合句意。"}, {"text": "促进", "is_correct": false, "explanation": "语义：“促进”指推动事情发展，与“大雾”造成的阻碍相反。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”接机器、物品等，不接“起飞”这类过程。"}], "explanations": {"保障": "语义：“保障”指保证，与“大雾”造成的阻碍相反，句意不通。", "干扰": "“干扰”指外来因素妨碍事情正常进行，符合句意。", "促进": "语义：“促进”指推动事情发展，与“大雾”造成的阻碍相反。", "修理": "搭配：“修理”接机器、物品等，不接“起飞”这类过程。"}, "sentence_index": 0, "correct_answer": "干扰"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场台风干扰了农田。", "explanation": "这里应该用〈破坏〉。干扰指妨碍事情或活动的正常进行，不指对农田这类实物造成损坏。"}, {"text": "他干扰了百米纪录。", "explanation": "这里应该用〈打破〉。干扰表示妨碍正在进行的事，不表示突破已有纪录。"}, {"text": "吸烟干扰了健康。", "explanation": "这里应该用〈损害〉。干扰指妨碍事情进行，不指伤害身体或健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "治疗", "is_correct": false, "explanation": "搭配：“治疗”接疾病或病人，不接“判断”。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”接距离、温度等可量化的事物，不接“判断”。"}, {"text": "干扰", "is_correct": true, "explanation": "“干扰”指外来因素妨碍判断，符合句意。"}, {"text": "提醒", "is_correct": false, "explanation": "语义：“提醒”需要有人作主语，感情不能提醒判断，句意不通。"}], "explanations": {"治疗": "搭配：“治疗”接疾病或病人，不接“判断”。", "测量": "搭配：“测量”接距离、温度等可量化的事物，不接“判断”。", "干扰": "“干扰”指外来因素妨碍判断，符合句意。", "提醒": "语义：“提醒”需要有人作主语，感情不能提醒判断，句意不通。"}, "sentence_index": 6, "correct_answer": "干扰"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一本好词典，干扰了他的学习。", "explanation": "这里应该用〈帮助〉。买到好词典是好事，〈干扰〉指妨碍正常进行，用于此句与语义相反。"}, {"text": "这件事干扰了他的心，让他一夜没睡。", "explanation": "这里应该用〈牵动〉。〈牵动〉指引起情绪变化，〈干扰〉只指打搅正在进行的事，不用于说心被触动。"}, {"text": "他一直在旁边鼓励我，干扰了我的学习。", "explanation": "这里应该用〈帮助〉。热心鼓励是好意，〈干扰〉含打搅、妨碍之意，用于此句与语义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "暴雨干扰了过火车的运行。", "corrected_sentence": "暴雨干扰了火车的运行。", "error_description": "错误：「了」与「过」同时用在动词「干扰」之后，一个动词后只能用一个体标。正确形式：「暴雨干扰了火车的运行」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大雪干扰了了交通。", "corrected_sentence": "大雪干扰了交通。", "error_description": "错误：「了」重复出现，写成「干扰了了交通」。「了」表示完成，一个动词后只用一个。正确形式：「大雪干扰了交通」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "放任：听任、不加过问，与“干涉”意思相反。"}, {"text": "鼓励", "is_correct": false, "explanation": "鼓励：表示支持、激励，与“干涉”不构成反义关系。"}, {"text": "支持", "is_correct": false, "explanation": "支持：表示赞同、援助，与“干涉”不构成反义关系。"}, {"text": "理解", "is_correct": false, "explanation": "理解：了解并体谅，与“干涉”不构成反义关系。"}], "correct_answer": "放任", "explanations": {"放任": "放任：听任、不加过问，与“干涉”意思相反。", "鼓励": "鼓励：表示支持、激励，与“干涉”不构成反义关系。", "支持": "支持：表示赞同、援助，与“干涉”不构成反义关系。", "理解": "理解：了解并体谅，与“干涉”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "放任：听任、不加过问，与“干涉”意思相反。"}, {"text": "建议", "is_correct": false, "explanation": "建议：提出看法供对方参考，与“干涉”不构成反义关系。"}, {"text": "提醒", "is_correct": false, "explanation": "提醒：提示对方注意，与“干涉”不构成反义关系。"}, {"text": "赞同", "is_correct": false, "explanation": "赞同：表示同意，与“干涉”不构成反义关系。"}], "correct_answer": "放任", "explanations": {"放任": "放任：听任、不加过问，与“干涉”意思相反。", "建议": "建议：提出看法供对方参考，与“干涉”不构成反义关系。", "提醒": "提醒：提示对方注意，与“干涉”不构成反义关系。", "赞同": "赞同：表示同意，与“干涉”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "硬要过问或插手别人不想让你管的私事。", "primary_collocate": null, "pronunciation": "gān shè", "ipa": "kan˥˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "我的事，请你不要干涉。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不应该干涉孩子交朋友。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他总是干涉我的生活，我很烦。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我自己的事，你别干涉我。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈从来不干涉我选专业。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板干涉了我们的工作方式。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同事们都不喜欢他干涉别人的事。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她太爱干涉朋友的决定了。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想让别人干涉我的爱情。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总要干涉我穿什么衣服？", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涉了", "label": "体标"}, {"form": "干涉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "硬要管别人不想让你管的私事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5159ab8-5210-402a-9e8c-41ff5dea1a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：过问或插手别人的私事，与“我的事”和“请你不要”的语境相符。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”的对象是活动、会议等，不能说“参加我的事”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”表示赞赏，与“请你不要”的劝阻语气相悖。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是物体表面，不能说“擦我的事”。"}], "explanations": {"干涉": "干涉：过问或插手别人的私事，与“我的事”和“请你不要”的语境相符。", "参加": "搭配：“参加”的对象是活动、会议等，不能说“参加我的事”。", "欣赏": "语义：“欣赏”表示赞赏，与“请你不要”的劝阻语气相悖。", "擦": "搭配：“擦”的对象是物体表面，不能说“擦我的事”。"}, "sentence_index": 0, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直干涉他的勇气。", "explanation": "这里应该用〈欣赏〉。干涉的对象是别人的事务或决定，不能是品质；称赞他人的勇气要用〈欣赏〉。"}, {"text": "我的队友都来干涉我的工作，我们一起完成了任务。", "explanation": "这里应该用〈分担〉。干涉是不受欢迎地插手别人的事务，带有管束之意；队友主动分担工作要用〈分担〉。"}, {"text": "我每天干涉房间。", "explanation": "这里应该用〈打扫〉。干涉的对象是人的事务，不能用于房间这类物体；“打扫房间”才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：插手别人的事，句中“同事们不喜欢他”的语境与之相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说“参观别人的事”。"}, {"text": "失败", "is_correct": false, "explanation": "配价：“失败”是不及物动词，不能带“别人的事”作宾语。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是生活、乐趣等，不能说“享受别人的事”。"}], "explanations": {"干涉": "干涉：插手别人的事，句中“同事们不喜欢他”的语境与之相符。", "参观": "搭配：“参观”的对象是场所或展览，不能说“参观别人的事”。", "失败": "配价：“失败”是不及物动词，不能带“别人的事”作宾语。", "享受": "搭配：“享受”的对象是生活、乐趣等，不能说“享受别人的事”。"}, "sentence_index": 6, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他干涉了那盆花。", "explanation": "这里应该用〈浇〉。干涉的对象是人或人的事务，不能用于植物；应说“浇花”。"}, {"text": "他很快就干涉完了那份作业。", "explanation": "这里应该用〈做〉。干涉是插手别人的事务或决定，不能表示完成作业；做作业要用〈做〉。"}, {"text": "我们干涉了快乐。", "explanation": "这里应该用〈分享〉。干涉的对象是他人的事务或选择，快乐不能被插手；应说“分享快乐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "父母不要干涉在我的恋爱。", "corrected_sentence": "父母不要干涉我的恋爱。", "error_description": "错误在于“干涉”后应直接带宾语，不能在宾语前加“在”。正确形式是“父母不要干涉我的恋爱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94029, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他总是干涉了我跟谁交往。", "corrected_sentence": "他总是干涉我跟谁交往。", "error_description": "“总是”表示习惯性的动作，不能与表示完成的“了”同用。应去掉“了”，说“他总是干涉我跟谁交往”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "放任：听任、不加管束，与“干涉”意思相反。"}, {"text": "赞美", "is_correct": false, "explanation": "赞美：表示称赞，与“干涉”不构成反义关系。"}, {"text": "帮助", "is_correct": false, "explanation": "帮助：给予援助，与“干涉”不构成反义关系。"}, {"text": "记录", "is_correct": false, "explanation": "记录：把事情写下来，与“干涉”不构成反义关系。"}], "correct_answer": "放任", "explanations": {"放任": "放任：听任、不加管束，与“干涉”意思相反。", "赞美": "赞美：表示称赞，与“干涉”不构成反义关系。", "帮助": "帮助：给予援助，与“干涉”不构成反义关系。", "记录": "记录：把事情写下来，与“干涉”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放任", "is_correct": true, "explanation": "放任：听任、不加管束，与“干涉”意思相反。"}, {"text": "批准", "is_correct": false, "explanation": "批准：同意并予以认可，与“干涉”不构成反义关系。"}, {"text": "答应", "is_correct": false, "explanation": "答应：表示同意，与“干涉”不构成反义关系。"}, {"text": "祝贺", "is_correct": false, "explanation": "祝贺：表示庆贺、道喜，与“干涉”不构成反义关系。"}], "correct_answer": "放任", "explanations": {"放任": "放任：听任、不加管束，与“干涉”意思相反。", "批准": "批准：同意并予以认可，与“干涉”不构成反义关系。", "答应": "答应：表示同意，与“干涉”不构成反义关系。", "祝贺": "祝贺：表示庆贺、道喜，与“干涉”不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "过问或插手别人的事情。", "primary_collocate": null, "pronunciation": "gān shè", "ipa": "kan˥˥ ʂɤ˥˩", "syllable_count": 2, "sentences": [{"text": "公司领导很少干涉我们的具体工作。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官独立判案，不受别人干涉。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个国家不能干涉另一个国家的内政。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师没有干涉学生的社团活动。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想干涉哥哥和朋友的事。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷退休后，不再干涉家里的大事。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府不应该过多干涉市场。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长很少干涉老师怎么上课。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不干涉你的选择，你自己决定。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事别人无权干涉。", "target_word": "干涉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干涉了", "label": "体标"}, {"form": "干涉过", "label": "体标"}], "register": "中性", "sense_fingerprint": "过问或插手他人事务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5159ab8-5210-402a-9e8c-41ff5dea1a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：过问或插手，句中“很少”与“具体工作”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃具体工作”。"}, {"text": "哭", "is_correct": false, "explanation": "配价：“哭”是不及物动词，不能带“具体工作”作宾语。"}, {"text": "失眠", "is_correct": false, "explanation": "配价：“失眠”是不及物动词，不能带“具体工作”作宾语。"}], "explanations": {"干涉": "干涉：过问或插手，句中“很少”与“具体工作”的语境相符。", "吃": "搭配：“吃”的对象是食物，不能说“吃具体工作”。", "哭": "配价：“哭”是不及物动词，不能带“具体工作”作宾语。", "失眠": "配价：“失眠”是不及物动词，不能带“具体工作”作宾语。"}, "sentence_index": 0, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一直在干涉电脑。", "explanation": "这里应该用〈修理〉。干涉的对象是人或人的事务，不能用于机器；“修理电脑”才是正确搭配。"}, {"text": "妈妈每天都干涉我的早饭，做得又香又好吃。", "explanation": "这里应该用〈准备〉。干涉是不受欢迎地插手别人的事务，不能表示做饭；“准备早饭”才是正确说法。"}, {"text": "妈妈干涉了窗户。", "explanation": "这里应该用〈擦〉。干涉的对象是人的事务，不能用于窗户等物体；“擦窗户”才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干涉", "is_correct": true, "explanation": "干涉：过问或插手，句中“过多”与“市场”的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象是衣物、身体等，不能说“洗市场”。"}, {"text": "躺", "is_correct": false, "explanation": "配价：“躺”是不及物动词，不能带“市场”作宾语。"}, {"text": "睡", "is_correct": false, "explanation": "配价：“睡”是不及物动词，不能带“市场”作宾语。"}], "explanations": {"干涉": "干涉：过问或插手，句中“过多”与“市场”的语境相符。", "洗": "搭配：“洗”的对象是衣物、身体等，不能说“洗市场”。", "躺": "配价：“躺”是不及物动词，不能带“市场”作宾语。", "睡": "配价：“睡”是不及物动词，不能带“市场”作宾语。"}, "sentence_index": 6, "correct_answer": "干涉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他干涉了一杯茶。", "explanation": "这里应该用〈喝〉。干涉的对象是他人的事务，不能用于饮品；“喝一杯茶”才是正确搭配。"}, {"text": "他干涉了蜡烛。", "explanation": "这里应该用〈点燃〉。干涉的对象是人或人的事务，不能用于蜡烛；应说“点燃蜡烛”。"}, {"text": "他干涉了一棵树。", "explanation": "这里应该用〈种〉。干涉的对象是人的事务，不能用于植物；应说“种了一棵树”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们不要干涉了他人的隐私。", "corrected_sentence": "我们不要干涉他人的隐私。", "error_description": "错误在于“不要”表示禁止，不能与表示完成的“了”同用。应去掉“了”，说“我们不要干涉他人的隐私”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "校长不该随便干涉得学生的选择。", "corrected_sentence": "校长不该随便干涉学生的选择。", "error_description": "“干涉”后的“得”只能接补语，不能直接带宾语。应去掉“得”，说“校长不该随便干涉学生的选择”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
