INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "快钱是很快就能赚到的钱。", "primary_collocate": null, "pronunciation": "kuài qián", "ipa": "kʰwaɪ˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他想找一份能赚快钱的工作。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快钱哪有那么容易赚，别想得太美了。", "target_word": "快钱", "complexity_tier": "T3", "furigana": "kuài qián nǎ yǒu nà me róng yì zhuàn，bié xiǎng de tài měi le。", "sentence_source": "generated"}, {"text": "爸爸说，赚快钱要先看清楚风险。", "target_word": "快钱", "complexity_tier": "T3", "furigana": "bà ba shuō，zhuàn kuài qián yào xiān kàn qīng chu fēng xiǎn。", "sentence_source": "generated"}, {"text": "这笔快钱让他很高兴。", "target_word": "快钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "为了赚快钱，他每天只睡三小时。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的朋友只对快钱有兴趣。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快钱虽然诱人，但是常常有陷阱。", "target_word": "快钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他抢着去赚快钱，却忘了学习。", "target_word": "快钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李赚过几次快钱，后来都亏了。", "target_word": "快钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人不要总想着赚快钱。", "target_word": "快钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔快钱", "label": "量词"}, {"form": "快錢", "label": "繁体"}], "register": "口语", "sense_fingerprint": "很快就能到手的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1707862d-56f8-4d46-b687-e41761f8e4cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "快钱", "is_correct": true, "explanation": "正确：“赚快钱的工作”指能短时间赚到钱的工作，与“赚”搭配。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能靠“赚”得到，“能赚石头的工作”不成立。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是可以赚来的收益，句意不通。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“赚”搭配钱或利益，不接心情。"}], "explanations": {"快钱": "正确：“赚快钱的工作”指能短时间赚到钱的工作，与“赚”搭配。", "石头": "语义：石头不能靠“赚”得到，“能赚石头的工作”不成立。", "房子": "语义：房子不是可以赚来的收益，句意不通。", "心情": "搭配：“赚”搭配钱或利益，不接心情。"}, "sentence_index": 0, "correct_answer": "快钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我父亲每个月的快钱都很稳定。", "explanation": "这里应该用〈退休金〉。快钱指短时间内容易赚到的钱，不用于每个月固定、稳定的收入。"}, {"text": "这只快钱让他很高兴。", "explanation": "这里量词应该用〈笔〉。快钱按笔计，“只”用于动物或成对物品中的一个，不用于钱。"}, {"text": "这家公司每年的快钱都很稳定。", "explanation": "这里应该用〈利润〉。快钱是短时间内容易赚到的钱，不能用来形容每年稳定的收益。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "快钱", "is_correct": true, "explanation": "正确：“快钱虽然诱人，但常有陷阱”指短时间赚到的钱，语义相合。"}, {"text": "白开水", "is_correct": false, "explanation": "搭配：「诱人」多修饰利益、风景、美食，不说“白开水诱人”。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不会让人觉得“诱人”，也谈不上“常有陷阱”。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水不是让人动心的东西，句子的意思说不通。"}], "explanations": {"快钱": "正确：“快钱虽然诱人，但常有陷阱”指短时间赚到的钱，语义相合。", "白开水": "搭配：「诱人」多修饰利益、风景、美食，不说“白开水诱人”。", "空气": "语义：空气不会让人觉得“诱人”，也谈不上“常有陷阱”。", "墨水": "语义：墨水不是让人动心的东西，句子的意思说不通。"}, "sentence_index": 6, "correct_answer": "快钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子每个月的快钱都很稳定。", "explanation": "这里应该用〈房租〉。快钱指短时间内容易赚到的钱，不能用来形容每月固定的收入。"}, {"text": "他的快钱要等到退休才能领取。", "explanation": "这里应该用〈养老金〉。快钱是短时间内容易赚到的钱，不是等到退休才能领取的钱。"}, {"text": "他在工厂里每天按时领取快钱。", "explanation": "这里应该用〈工资〉。快钱指短时间内不费力赚到的钱，按日领取的薪水不是快钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她说，赚一只快钱的人往往不会长久。", "corrected_sentence": "她说，赚一笔快钱的人往往不会长久。", "error_description": "错误：量词用了“只”；正确：“一笔快钱”。快钱按笔计，量词应为“笔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他为了一辆快钱，把积蓄都投进了股市。", "corrected_sentence": "他为了一笔快钱，把积蓄都投进了股市。", "error_description": "错误：量词用了“辆”；正确：“一笔快钱”。快钱按笔计，量词应为“笔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "应付是想办法把事做完，或者随便做一做。", "primary_collocate": null, "pronunciation": "yìng fu", "ipa": "iŋ˥˩ fu", "syllable_count": 2, "sentences": [{"text": "他只想应付作业，没有认真写。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告太马虎了，明显是应付差事。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做工作要认真，不能随便应付。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天上班只是应付一下，不想多做。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱不多，先应付这个月的生活吧。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天没时间做饭，随便应付一顿。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板要的东西，我先应付着做一份。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样应付检查，迟早会出问题。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把作业应付完就去玩了。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习不能只是应付考试。", "target_word": "应付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "应付了", "label": "完成体"}, {"form": "应付着", "label": "持续体"}, {"form": "应付过", "label": "经历体"}, {"form": "應付", "label": "繁体"}, {"form": "应付差事", "label": "复合词"}], "register": "中性", "sense_fingerprint": "应付：不认真，只求把事情做完或勉强凑合过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e60ece-b0ef-49ed-9e2f-beaff451da86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "语义：作业不是值得欣赏的对象，与“没有认真写”的语境不合。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：装饰指美化物体，不能用于作业。"}, {"text": "应付", "is_correct": true, "explanation": "正确：应付作业指勉强完成、敷衍了事，符合“没有认真写”的句意。"}, {"text": "批改", "is_correct": false, "explanation": "语义：批改是检查并修改作业，学生做的事不是批改。"}], "explanations": {"欣赏": "语义：作业不是值得欣赏的对象，与“没有认真写”的语境不合。", "装饰": "搭配：装饰指美化物体，不能用于作业。", "应付": "正确：应付作业指勉强完成、敷衍了事，符合“没有认真写”的句意。", "批改": "语义：批改是检查并修改作业，学生做的事不是批改。"}, "sentence_index": 0, "correct_answer": "应付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对朋友很应付，每次聚会都认真陪伴大家。", "explanation": "这里应该用〈真诚〉。“应付”带有敷衍意味，与“认真陪伴”矛盾。"}, {"text": "这种方法可以应付在教学中。", "explanation": "这里应该用〈应用〉。“应用”指用于某种场合；“应付”指对付情况，不能说“应付在教学中”。"}, {"text": "他应付工作很认真，每件事都仔细检查。", "explanation": "这里应该用〈对待〉。“应付”带有敷衍意味，与“很认真、仔细检查”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "推辞", "is_correct": false, "explanation": "语义：推辞指婉言谢绝，“做一份”的东西不是推辞的对象。"}, {"text": "应付", "is_correct": true, "explanation": "正确：应付指勉强对付，符合“先应付着做一份”的句意。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：赔偿针对损失或损害，不能用于做东西。"}, {"text": "打听", "is_correct": false, "explanation": "语义：打听指探问消息，与“做一份”无关。"}], "explanations": {"推辞": "语义：推辞指婉言谢绝，“做一份”的东西不是推辞的对象。", "应付": "正确：应付指勉强对付，符合“先应付着做一份”的句意。", "赔偿": "搭配：赔偿针对损失或损害，不能用于做东西。", "打听": "语义：打听指探问消息，与“做一份”无关。"}, "sentence_index": 6, "correct_answer": "应付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的应付款项已经全部收齐了。", "explanation": "这里应该用〈应收〉。“应收”指应当收回的款项，“应付”指应当支付的款项，“收齐”的应是应收款。"}, {"text": "这次考试是用来应付学习效果的。", "explanation": "这里应该用〈检验〉。“检验”指查看效果；“应付”表示对付，不能说“应付学习效果”。"}, {"text": "学生应该应付老师的爱，并努力回报。", "explanation": "这里应该用〈接受〉。“接受”指愿意接纳感情，“应付”只表示处理事情或敷衍，不能用于感情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些问题我很快就应付了完。", "corrected_sentence": "这些问题我很快就应付完了。", "error_description": "错误：“应付了完”，结果补语“完”应直接跟在动词后，“了”要放在句末。正确：“应付完了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94033, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他只是随便应付一下地。", "corrected_sentence": "他只是随便应付一下。", "error_description": "错误：“应付一下地”，“地”是状语标记，只能加在形容词或副词后面，动量补语“一下”之后不能加“地”。正确：“应付一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
