INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94038, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拥有足够多的股份，从而控制某公司。", "primary_collocate": null, "pronunciation": "kòng gǔ", "ipa": "kʰʊŋ˥˩ ku˨˩˦", "syllable_count": 2, "sentences": [{"text": "那家基金公司控股了三家银行。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板拥有六成股份，控股了整个集团。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想控股这家公司，所以每天买股票。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店由外国公司控股。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家控股后，公司换了新经理。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要控股一家公司，得拥有过半的股份。", "target_word": "控股", "complexity_tier": "T3", "furigana": "kòng gǔ", "sentence_source": "generated"}, {"text": "我们公司现在由两家大企业共同控股。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家控股着这家老字号。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李的叔叔控股一家汽车公司。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家公司没有控股过任何银行。", "target_word": "控股", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "控股了", "label": "体标"}, {"form": "控股过", "label": "体标"}], "register": "正式", "sense_fingerprint": "靠足够多的股份控制公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "控股", "is_correct": true, "explanation": "正确：“控股了三家银行”指那家基金公司拥有足够多的股份而控制这三家银行。"}, {"text": "上市", "is_correct": false, "explanation": "配价：“上市”是不及物动词，不能带“三家银行”作宾语，句子不成立。"}, {"text": "颁发", "is_correct": false, "explanation": "语义：“颁发”的对象是证书、执照、奖项，不能说颁发三家银行。"}, {"text": "捐献", "is_correct": false, "explanation": "搭配：“捐献”的对象是钱物，不能说捐献三家银行。"}], "explanations": {"控股": "正确：“控股了三家银行”指那家基金公司拥有足够多的股份而控制这三家银行。", "上市": "配价：“上市”是不及物动词，不能带“三家银行”作宾语，句子不成立。", "颁发": "语义：“颁发”的对象是证书、执照、奖项，不能说颁发三家银行。", "捐献": "搭配：“捐献”的对象是钱物，不能说捐献三家银行。"}, "sentence_index": 0, "correct_answer": "控股"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外国公司控股了这家酒店，只买了三成的股份。", "explanation": "这里应该用〈参股〉。控股要求拥有足够多的股份，只占三成不足以控股，这里应说参股。"}, {"text": "这家酒店由外国公司每天控股。", "explanation": "这里应该用〈经营〉。控股指持续拥有股份的状态，不是每天重复的动作，不能用“每天”修饰。"}, {"text": "外国公司控股了这家酒店的经理。", "explanation": "这里应该用〈聘请〉。控股的对象是公司、企业，人不能被控股，应说聘请这家酒店的经理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "控股", "is_correct": true, "explanation": "正确：“共同控股”指两家企业一起拥有这家公司的多数股份。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”只能用于人或动物，公司不能游泳。"}, {"text": "出生", "is_correct": false, "explanation": "配价：“出生”没有受事，不能组成“由……共同”带受事的句子。"}, {"text": "怀念", "is_correct": false, "explanation": "语义：“怀念”的对象是人或往事，不能用于企业。"}], "explanations": {"控股": "正确：“共同控股”指两家企业一起拥有这家公司的多数股份。", "游泳": "语义：“游泳”只能用于人或动物，公司不能游泳。", "出生": "配价：“出生”没有受事，不能组成“由……共同”带受事的句子。", "怀念": "语义：“怀念”的对象是人或往事，不能用于企业。"}, "sentence_index": 6, "correct_answer": "控股"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那家公司控股了它的全部员工。", "explanation": "这里应该用〈掌控〉。控股的对象是公司、企业，员工不能被控股，应说掌控。"}, {"text": "那家公司控股了这项工程。", "explanation": "这里应该用〈承包〉。控股的对象是公司，工程不是公司，应说承包这项工程。"}, {"text": "那家公司控股了这次会议。", "explanation": "这里应该用〈主持〉。会议不是公司，不能被控股，应说主持这次会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那家银行正在控股了两家小公司。", "corrected_sentence": "那家银行正在控股两家小公司。", "error_description": "错误：“正在”表示动作进行中，句中不能再用“了”。正确：“正在控股两家小公司”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们家没控股了那家餐厅。", "corrected_sentence": "他们家没控股过那家餐厅。", "error_description": "错误：否定“没”后面的体标应用“过”，不能用“了”。正确：“没控股过那家餐厅”表示从未有过这种情况。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
