INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "此次；这一次。", "primary_collocate": null, "pronunciation": "shì cì", "ipa": "ʂɻ̩˥˩ tsʰɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "是次考试的题目比上次容易。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次选举，很多年轻人去投票了。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次大雨来得很快，街上都是水。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次旅游让我认识了新朋友。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次出差，经理带了三个同事。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次比赛有二十个国家参加。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次服务让我很满意。", "target_word": "是次", "complexity_tier": "T3", "furigana": "shì cì fú wù ràng wǒ hěn mǎn yì", "sentence_source": "generated"}, {"text": "是次聚会在周六晚上，别忘了。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次失败，让他明白了努力的重要。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "是次讲座有一百多人来听。", "target_word": "是次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面语", "sense_fingerprint": "是次：此次，用于书面或正式场合指这一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d7132db-349d-4d06-b68d-82e6dd273dcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "是次", "is_correct": true, "explanation": "是次：此次，指这一次，正合“这次考试的题目”的语境。"}, {"text": "上次", "is_correct": false, "explanation": "语义：句中已有“比上次”，再说“上次考试”会与之重复，指代冲突。"}, {"text": "很", "is_correct": false, "explanation": "语法：副词“很”不能直接修饰名词“考试”，此处不成立。"}, {"text": "上一场", "is_correct": false, "explanation": "语义：“上一场”指前一场，与“比上次”所指的时间重复、冲突。"}], "explanations": {"是次": "是次：此次，指这一次，正合“这次考试的题目”的语境。", "上次": "语义：句中已有“比上次”，再说“上次考试”会与之重复，指代冲突。", "很": "语法：副词“很”不能直接修饰名词“考试”，此处不成立。", "上一场": "语义：“上一场”指前一场，与“比上次”所指的时间重复、冲突。"}, "sentence_index": 0, "correct_answer": "是次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "是次手机很好用，我每天都带着。", "explanation": "这里应该用〈这部〉。是次只指时间，不能修饰手机等物品。"}, {"text": "是次我三年前就去过那里。", "explanation": "这里不该用〈是次〉。是次指说话时正在谈论的这一次，与“三年前”矛盾。"}, {"text": "是次我们每个月都见面。", "explanation": "这里应该用〈经常〉。是次只指这一次，不能表示反复发生的“每个月都”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
