INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94042, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有完结；没有了结。", "primary_collocate": null, "pronunciation": "wèi liǎo", "ipa": "weɪ˥˩ liɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他还有一件未了的债务。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个案子未了，警察还在查。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家的矛盾至今未了。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里有一桩未了的事。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的旧账还未了。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱的事未了，你不能走。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父亲去世前，还有未了的心事。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "官司三年未了，他很累。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事至今未了，大家都很着急。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在出国前把未了的事做完。", "target_word": "未了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "遗留问题、债务、纠纷等没有了结", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5159ab8-5210-402a-9e8c-41ff5dea1a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未了", "is_correct": true, "explanation": "未了：债务尚未了结，修饰“债务”，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的动作不能修饰“债务”，句意不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”的动作不能修饰“债务”，句意不通。"}, {"text": "洗澡", "is_correct": false, "explanation": "搭配：“债务”常与“欠、还”搭配，不与“洗澡”搭配。"}], "explanations": {"未了": "未了：债务尚未了结，修饰“债务”，符合句意。", "唱": "语义：“唱”的动作不能修饰“债务”，句意不通。", "跳舞": "语义：“跳舞”的动作不能修饰“债务”，句意不通。", "洗澡": "搭配：“债务”常与“欠、还”搭配，不与“洗澡”搭配。"}, "sentence_index": 0, "correct_answer": "未了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汤还未了。", "explanation": "这里应该用〈未煮熟〉。未了用于债务、纠纷等尚未了结的事，汤不能“了结”，应说“汤还没煮熟”。"}, {"text": "这台电脑还未了。", "explanation": "这里应该用〈未修好〉。未了不用于机器的状态，应说“电脑还没修好”。"}, {"text": "窗户还未了。", "explanation": "这里应该用〈未擦净〉。未了不用于窗户，应说“窗户还没擦干净”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未了", "is_correct": true, "explanation": "未了：尚未了结，作定语修饰“心事”，符合句意。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”的动作不能修饰“心事”，句意不通。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的动作不能修饰“心事”，句意不通。"}, {"text": "打", "is_correct": false, "explanation": "搭配：“打”不与“心事”搭配，句意不通。"}], "explanations": {"未了": "未了：尚未了结，作定语修饰“心事”，符合句意。", "煮": "语义：“煮”的动作不能修饰“心事”，句意不通。", "喝": "语义：“喝”的动作不能修饰“心事”，句意不通。", "打": "搭配：“打”不与“心事”搭配，句意不通。"}, "sentence_index": 6, "correct_answer": "未了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "草还未了。", "explanation": "这里应该用〈未长高〉。未了用于事情、纠纷等尚未了结的事，草不能“了结”，应说“草还没长高”。"}, {"text": "鞋还未了。", "explanation": "这里应该用〈未穿上〉。未了不用于鞋的状态，应说“鞋还没穿上”。"}, {"text": "蛋糕还未了。", "explanation": "这里应该用〈未切开〉。未了用于事情尚未了结，蛋糕不能“了结”，应说“蛋糕还没切开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这笔欠款已未了，他每天都在想办法。", "corrected_sentence": "这笔欠款还未了，他每天都在想办法。", "error_description": "“未了”本身已含“尚未”之义，不能与“已”同用。应用“还”，说“这笔欠款还未了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔借款至今还未了着，他睡不着。", "corrected_sentence": "这笔借款至今还未了，他睡不着。", "error_description": "“未了”表示尚未了结的状态，后面不能加“着”。应去掉“着”，说“这笔借款至今还未了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
