INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94060, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "由低处走到高处；攀登。", "primary_collocate": null, "pronunciation": "dēng", "ipa": "təŋ˥", "syllable_count": 1, "sentences": [{"text": "他一步一步登上山顶。", "target_word": "登", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们登上了最高的楼。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年纪大，登不上这座山。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她登到三楼，累得不想动。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们登了两个小时才到山顶。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友登上台阶，走进门。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想看日出，就要早点登上山顶。", "target_word": "登", "complexity_tier": "T3", "furigana": "xiǎng kàn rì chū，jiù yào zǎo diǎn dēng shàng shān dǐng。", "sentence_source": "generated"}, {"text": "他登上高塔，看到整个城市。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座山太陡，很难登上去。", "target_word": "登", "complexity_tier": "T3", "furigana": "zhè zuò shān tài dǒu，hěn nán dēng shàng qù。", "sentence_source": "generated"}, {"text": "登上长城，我觉得很自豪。", "target_word": "登", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "登了", "label": "体标"}, {"form": "登过", "label": "体标"}, {"form": "登上", "label": "复合"}, {"form": "登山", "label": "复合"}, {"form": "登高", "label": "复合"}], "register": "中性", "sense_fingerprint": "从低处走到高处，攀登山、楼、塔等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1707862d-56f8-4d46-b687-e41761f8e4cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94060, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "登", "is_correct": true, "explanation": "正确：登（dēng）指一步一步往高处走上去。"}, {"text": "等", "is_correct": false, "explanation": "děng（第三声）与 dēng（第一声）声调不同，意思是等待。"}, {"text": "凳", "is_correct": false, "explanation": "dèng（第四声）与 dēng 声调不同，意思是板凳。"}, {"text": "东", "is_correct": false, "explanation": "dōng 与 dēng 韵母不同（-ong 与 -eng），意思是东边。"}, {"text": "冬", "is_correct": false, "explanation": "dōng 与 dēng 韵母不同（-ong 与 -eng），意思是冬天。"}], "explanations": {"登": "正确：登（dēng）指一步一步往高处走上去。", "等": "děng（第三声）与 dēng（第一声）声调不同，意思是等待。", "凳": "dèng（第四声）与 dēng 声调不同，意思是板凳。", "东": "dōng 与 dēng 韵母不同（-ong 与 -eng），意思是东边。", "冬": "dōng 与 dēng 韵母不同（-ong 与 -eng），意思是冬天。"}, "sentence_index": null, "correct_answer": "登"}, "level_3": {"options": [{"text": "登", "is_correct": true, "explanation": "正确：“一步一步登上山顶”指一步步往高处走，与“一步一步”相合。"}, {"text": "飞", "is_correct": false, "explanation": "语义：飞是在空中移动，与“一步一步”的走法相矛盾。"}, {"text": "游", "is_correct": false, "explanation": "搭配：游多指在水中或游览，不说“游上山顶”的攀登。"}, {"text": "跳", "is_correct": false, "explanation": "语义：跳是一跃而起，不是一步一步往上走。"}], "explanations": {"登": "正确：“一步一步登上山顶”指一步步往高处走，与“一步一步”相合。", "飞": "语义：飞是在空中移动，与“一步一步”的走法相矛盾。", "游": "搭配：游多指在水中或游览，不说“游上山顶”的攀登。", "跳": "语义：跳是一跃而起，不是一步一步往上走。"}, "sentence_index": 0, "correct_answer": "登"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "蜗牛慢慢登上了墙。", "explanation": "这里应该用〈爬〉。登指人一步一步有目的地向高处走上去，蜗牛爬墙要用“爬”。"}, {"text": "他登进了房间，关上了门。", "explanation": "这里应该用〈走进〉。登只表示由低处向高处走上去，进房间是水平移动，不能用“登”。"}, {"text": "热气球慢慢登到了空中。", "explanation": "这里应该用〈升〉。热气球靠气流上升，不是一步步走上去，不能用“登”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94060, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "登", "is_correct": true, "explanation": "正确：登（dēng）指一步一步往高处走上去。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dēng 韵母不同（-ang 与 -eng），意思是应当、当时。"}, {"text": "瞪", "is_correct": false, "explanation": "dèng（第四声）与 dēng（第一声）声调不同，意思是瞪眼。"}, {"text": "钉", "is_correct": false, "explanation": "dīng 与 dēng 韵母不同（-ing 与 -eng），意思是钉子。"}], "explanations": {"登": "正确：登（dēng）指一步一步往高处走上去。", "当": "dāng 与 dēng 韵母不同（-ang 与 -eng），意思是应当、当时。", "瞪": "dèng（第四声）与 dēng（第一声）声调不同，意思是瞪眼。", "钉": "dīng 与 dēng 韵母不同（-ing 与 -eng），意思是钉子。"}, "sentence_index": null, "correct_answer": "登"}, "level_3": {"options": [{"text": "登", "is_correct": true, "explanation": "正确：“早点登上山顶”指一步步往高处走，与“看日出”的目的相合。"}, {"text": "煮", "is_correct": false, "explanation": "语义：煮是加热食物，与看日出、登山无关。"}, {"text": "住", "is_correct": false, "explanation": "搭配：“住”接“在＋地点”，不说“住上山顶”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌与登山无关，句子语义不通。"}], "explanations": {"登": "正确：“早点登上山顶”指一步步往高处走，与“看日出”的目的相合。", "煮": "语义：煮是加热食物，与看日出、登山无关。", "住": "搭配：“住”接“在＋地点”，不说“住上山顶”。", "唱": "语义：唱歌与登山无关，句子语义不通。"}, "sentence_index": 6, "correct_answer": "登"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "秋天的叶子慢慢登到了地上。", "explanation": "这里应该用〈落〉。登只表示向高处走上去，叶子从高处往下落不能用“登”。"}, {"text": "他把杯子登到了桌子上。", "explanation": "这里应该用〈放〉。登的主语须是人或动物自己一步步向上走，杯子不能“登”，应用“放”。"}, {"text": "我们从山顶登到了山脚。", "explanation": "这里应该用〈下〉。登只能表示向高处走，不能表示从高处往低处走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94060, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一步一步登下山顶，看到了日出。", "corrected_sentence": "他一步一步登上山顶，看到了日出。", "error_description": "错误：趋向补语“下”与“登”（向高处走）矛盾。正确：“登上山顶”，应用“上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94060, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们终于登了上长城，很激动。", "corrected_sentence": "我们终于登上了长城，很激动。", "error_description": "错误：“了”插在“登”和补语“上”之间。正确：“登上了长城”，补语“上”紧接“登”，“了”放在补语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '207dac0a-91e8-459a-bcbc-020b201f57cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
