INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94061, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "发布会是大家聚在一起听人宣布新消息的会。", "primary_collocate": null, "pronunciation": "fā bù huì", "ipa": "fa˥˥ pu˥˩ xweɪ˥˩", "syllable_count": 3, "sentences": [{"text": "今天下午三点有一个发布会。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发布会的时候，大家都很安静。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和同学一起去听发布会。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发布会的房间里坐满了人。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在发布会上宣布了好消息。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发布会上，老板说公司要搬家了。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次发布会上，大家听到了最新的消息。", "target_word": "发布会", "complexity_tier": "T3", "furigana": "zhè cì fā bù huì shàng, dà jiā tīng dào le zuì xīn de xiāo xi", "sentence_source": "generated"}, {"text": "大家都在等发布会开始。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天的发布会，你为什么没去？", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她站在发布会的台上，很紧张。", "target_word": "发布会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场发布会", "label": "量词"}, {"form": "一次发布会", "label": "量词"}, {"form": "新闻发布会", "label": "复合"}, {"form": "产品发布会", "label": "复合"}], "register": "中性", "sense_fingerprint": "大家聚在一起听人宣布新消息的会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5159ab8-5210-402a-9e8c-41ff5dea1a11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94061, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发布会", "is_correct": true, "explanation": "正确：“一个发布会”指大家听人宣布消息的会，下午三点举行很自然。"}, {"text": "日出", "is_correct": false, "explanation": "语义：日出在清晨，下午三点不会有日出，与“下午三点”矛盾。"}, {"text": "夜市", "is_correct": false, "explanation": "语义：夜市是晚上营业的集市，与“下午三点”矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”只描述人的高矮，不能作为下午三点发生的事情。"}], "explanations": {"发布会": "正确：“一个发布会”指大家听人宣布消息的会，下午三点举行很自然。", "日出": "语义：日出在清晨，下午三点不会有日出，与“下午三点”矛盾。", "夜市": "语义：夜市是晚上营业的集市，与“下午三点”矛盾。", "身高": "体貌：“身高”只描述人的高矮，不能作为下午三点发生的事情。"}, "sentence_index": 0, "correct_answer": "发布会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "同学们在发布会上背诵课文。", "explanation": "这里应该用〈课堂〉。发布会是宣布新消息的场合，背诵课文要在课堂上进行。"}, {"text": "评委在发布会上给选手打分。", "explanation": "这里应该用〈选拔会〉。发布会只用来宣布消息，给选手打分要在选拔会上进行。"}, {"text": "亲友们在发布会上哭泣。", "explanation": "这里应该用〈葬礼〉。发布会是宣布新消息的场合，哀悼逝者要在葬礼上进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94061, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发布会", "is_correct": true, "explanation": "正确：“这次发布会上”指宣布消息的会，与“听到了最新的消息”相合。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是哀悼逝者的场合，不会有人在那里宣布最新消息。"}, {"text": "面容", "is_correct": false, "explanation": "体貌：“面容”指人的脸部外貌，不能用来指一次活动。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验学习成绩的活动，不是宣布最新消息的场合。"}], "explanations": {"发布会": "正确：“这次发布会上”指宣布消息的会，与“听到了最新的消息”相合。", "葬礼": "语义：葬礼是哀悼逝者的场合，不会有人在那里宣布最新消息。", "面容": "体貌：“面容”指人的脸部外貌，不能用来指一次活动。", "考试": "语义：考试是测验学习成绩的活动，不是宣布最新消息的场合。"}, "sentence_index": 6, "correct_answer": "发布会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在发布会上参加了期末考试。", "explanation": "这里应该用〈考试〉。发布会只用来宣布新消息，参加期末考试不是它的用途。"}, {"text": "他在发布会上吹灭了蜡烛。", "explanation": "这里应该用〈生日派对〉。发布会只用来宣布新消息，吹蜡烛过生日要在生日派对上进行。"}, {"text": "孩子们在发布会上堆沙堡。", "explanation": "这里应该用〈海边〉。发布会是宣布新消息的会，堆沙堡要在海边进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94061, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家在发布会下听到了好消息。", "corrected_sentence": "大家在发布会上听到了好消息。", "error_description": "方位词错误：“发布会”后应用方位词“上”，说“发布会上”。“下”表示位置在下方，不能用于会议。正确形式是“大家在发布会上听到了好消息”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94061, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天的一条发布会，记者们等了很久。", "corrected_sentence": "今天的一场发布会，记者们等了很久。", "error_description": "量词错误：“发布会”应用量词“场”或“次”，“条”用于细长的东西，不能修饰会议。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bed8848-8f5c-48c4-abd1-ef1f51ae9967') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
