INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94065, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "码头是船靠岸，人和货上下船的地方。", "primary_collocate": null, "pronunciation": "mǎ tou", "ipa": "ma˨˩˦ tʰou", "syllable_count": 2, "sentences": [{"text": "码头上的风很大，大家都戴着帽子。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去码头接从海南来的朋友。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船靠岸后，大家从码头走上岸。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个码头很老，只能停小船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上都去码头买新鲜的鱼。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "码头离火车站不远，走路十分钟。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车一直开到码头，我们才下车。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个码头晚上没有船，也没有人。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他小时候常在码头看大船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把行李搬到码头那边去。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "客运码头", "label": "复合"}, {"form": "碼頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "船靠岸、人和货上下船的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94065, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "码头", "is_correct": true, "explanation": "正确：“码头上”指船靠岸、人和货上下船的地方，室外、靠水，风大符合语境。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是室内放书的家具，不会有很大的风。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内空间，“上的风很大”与“大家都戴着帽子”不相符。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“上的风”一般用于室外地点，厨房是室内，搭配不当。"}], "explanations": {"码头": "正确：“码头上”指船靠岸、人和货上下船的地方，室外、靠水，风大符合语境。", "书架": "语义：书架是室内放书的家具，不会有很大的风。", "教室": "语义：教室是室内空间，“上的风很大”与“大家都戴着帽子”不相符。", "厨房": "搭配：“上的风”一般用于室外地点，厨房是室内，搭配不当。"}, "sentence_index": 0, "correct_answer": "码头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在岸边新建了一只码头。", "explanation": "这里应该用〈座〉。码头是固定的建筑，量词用“座”，“只”一般用于船、动物等。"}, {"text": "这个码头很老，只能看小病。", "explanation": "这里应该用〈医院〉。看小病要去医院，码头是船靠岸、人和货上下船的地方。"}, {"text": "这个码头很老，只能剪短发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，码头是船靠岸、人和货上下船的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94065, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "码头", "is_correct": true, "explanation": "正确：“车一直开到码头，我们才下车”指车开到码头，人才下车，符合语境。"}, {"text": "卧室", "is_correct": false, "explanation": "语义：车不能开进卧室，“开到卧室”不符合常理。"}, {"text": "游泳池", "is_correct": false, "explanation": "搭配：“开到”一般搭配可通车的地点，游泳池一般不能把车开过去。"}, {"text": "舞台", "is_correct": false, "explanation": "语义：车不能开上舞台，与“我们才下车”的语境不符。"}], "explanations": {"码头": "正确：“车一直开到码头，我们才下车”指车开到码头，人才下车，符合语境。", "卧室": "语义：车不能开进卧室，“开到卧室”不符合常理。", "游泳池": "搭配：“开到”一般搭配可通车的地点，游泳池一般不能把车开过去。", "舞台": "语义：车不能开上舞台，与“我们才下车”的语境不符。"}, "sentence_index": 6, "correct_answer": "码头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个码头每天审理很多案子。", "explanation": "这里应该用〈法院〉。审理案件的是法院，码头是船靠岸、人和货上下船的地方。"}, {"text": "这个码头每年招收三百名新生。", "explanation": "这里应该用〈学校〉。招收新生的是学校，码头是船靠岸、人和货上下船的地方。"}, {"text": "这个码头每年生产十万吨钢铁。", "explanation": "这里应该用〈钢厂〉。生产钢铁的是钢厂，码头是船靠岸、人和货上下船的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94065, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只码头每天都很热闹。", "corrected_sentence": "这个码头每天都很热闹。", "error_description": "错误：码头是固定建筑，量词应用“个”或“座”，“只”一般用于船、动物等。正确：“这个码头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94065, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "货船靠到这艘码头了。", "corrected_sentence": "货船靠到这个码头了。", "error_description": "错误：码头是固定建筑，量词应用“个”或“座”，“艘”一般用于船只。正确：“这个码头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
