INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "江河湖海边供船停靠和装卸货物、乘客上下的地方。", "primary_collocate": null, "pronunciation": "mǎ tou", "ipa": "ma˨˩˦ tʰou", "syllable_count": 2, "sentences": [{"text": "船慢慢开到码头边。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在码头等去岛上的船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "码头上有很多工人在搬货。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个码头每天有三班船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在江边的码头上钓鱼。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "货船到了码头，工人开始卸货。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人从码头走上了大船。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边新建了一座码头。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船都停在小码头旁边。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐船到了对岸的码头，再坐车去城里。", "target_word": "码头", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "货运码头", "label": "复合"}, {"form": "碼頭", "label": "繁体"}], "register": "中性", "sense_fingerprint": "水边供船停靠、装卸货物和上下客的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "码头", "is_correct": true, "explanation": "正确：“码头边”指江河湖海边供船停靠的地方，船开到这里合理。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不临水，船不能开到教室边。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不靠水，船无法开到图书馆边。"}, {"text": "停车场", "is_correct": false, "explanation": "搭配：“停车场”是车辆停放的地方，船不会停在那里。"}], "explanations": {"码头": "正确：“码头边”指江河湖海边供船停靠的地方，船开到这里合理。", "教室": "语义：教室不临水，船不能开到教室边。", "图书馆": "语义：图书馆不靠水，船无法开到图书馆边。", "停车场": "搭配：“停车场”是车辆停放的地方，船不会停在那里。"}, "sentence_index": 0, "correct_answer": "码头"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在河边新建了一只码头。", "explanation": "这里应该用〈座〉。码头是固定的建筑，量词用“座”，“只”一般用于船、动物等。"}, {"text": "他每周去码头剪头发。", "explanation": "这里应该用〈理发店〉。剪头发要去理发店，码头是船靠岸、装卸货物的地方。"}, {"text": "这个码头每天有三百位病人就诊。", "explanation": "这里应该用〈医院〉。就诊看病要去医院，码头是船靠岸、装卸货物的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "码头", "is_correct": true, "explanation": "正确：“从码头走上大船”指客人从码头登上大船，符合语境。"}, {"text": "跑道", "is_correct": false, "explanation": "语义：跑道供飞机起降，客人不能从跑道走上大船。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是登船的地方，不能从厨房走上大船。"}, {"text": "卧室", "is_correct": false, "explanation": "搭配：“卧室”不是登船处，与“走上大船”搭配不当。"}], "explanations": {"码头": "正确：“从码头走上大船”指客人从码头登上大船，符合语境。", "跑道": "语义：跑道供飞机起降，客人不能从跑道走上大船。", "厨房": "语义：厨房不是登船的地方，不能从厨房走上大船。", "卧室": "搭配：“卧室”不是登船处，与“走上大船”搭配不当。"}, "sentence_index": 6, "correct_answer": "码头"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个码头每天生产三千台机器。", "explanation": "这里应该用〈工厂〉。生产机器的是工厂，码头是船靠岸、装卸货物的地方。"}, {"text": "这个码头养了三百只猴子。", "explanation": "这里应该用〈动物园〉。饲养动物的是动物园，码头是船靠岸、装卸货物的地方。"}, {"text": "这个码头每晚都住满了客人。", "explanation": "这里应该用〈宾馆〉。住宿留客的是宾馆，码头是船靠岸、装卸货物的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里新修了一只码头。", "corrected_sentence": "村里新修了一座码头。", "error_description": "错误：量词“只”一般用于船、动物等，码头是固定建筑，应用“座”。正确：“一座码头”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94066, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "渔船靠到这台码头了。", "corrected_sentence": "渔船靠到这个码头了。", "error_description": "错误：码头是固定建筑，量词应用“个”或“座”，“台”一般用于机器、车辆等。正确：“这个码头”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有希望", "is_correct": true, "explanation": "“有希望”与“绝望”相对，指心里还存有盼头。"}, {"text": "平静", "is_correct": false, "explanation": "“平静”指心情安稳，不是“绝望”的反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”指明白、不模糊，与“绝望”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“绝望”没有反义关系。"}], "correct_answer": "有希望", "explanations": {"有希望": "“有希望”与“绝望”相对，指心里还存有盼头。", "平静": "“平静”指心情安稳，不是“绝望”的反义词。", "清楚": "“清楚”指明白、不模糊，与“绝望”没有反义关系。", "整齐": "“整齐”指排列有序，与“绝望”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "有希望", "is_correct": true, "explanation": "“有希望”与“绝望”相对，指心里还存有盼头。"}, {"text": "轻松", "is_correct": false, "explanation": "“轻松”指不紧张、不费力，与“绝望”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "“严肃”指态度认真或庄重，与“绝望”没有反义关系。"}, {"text": "整洁", "is_correct": false, "explanation": "“整洁”指干净利落，与“绝望”没有反义关系。"}], "correct_answer": "有希望", "explanations": {"有希望": "“有希望”与“绝望”相对，指心里还存有盼头。", "轻松": "“轻松”指不紧张、不费力，与“绝望”没有反义关系。", "严肃": "“严肃”指态度认真或庄重，与“绝望”没有反义关系。", "整洁": "“整洁”指干净利落，与“绝望”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "绝望是心里觉得再也没有办法了，一点盼头也没有。", "primary_collocate": null, "pronunciation": "jué wàng", "ipa": "tɕɥe˧˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "考试没过，他心里很绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她绝望地坐在地上哭了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了一个月工作，越找越绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着空空的钱包，觉得很绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "迷路的人在大雨里感到绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绝望的眼神让人心疼。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有人帮忙，她一个人绝望极了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到那个坏消息，大家都很绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一次次失败，一天比一天绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别太绝望，也许明天会有办法。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝望地", "label": "状语形式"}, {"form": "绝望了", "label": "体标"}, {"form": "絕望", "label": "繁体"}], "register": "中性", "sense_fingerprint": "心里觉得没有办法、没有盼头的感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”指心里觉得没有办法、没有盼头，与“考试没过”的情境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：考试没过，心里不会高兴，与句中的情况相反。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能用来形容心情。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描写人的身材，不能用来说心里的感受。"}], "explanations": {"绝望": "“绝望”指心里觉得没有办法、没有盼头，与“考试没过”的情境相符。", "高兴": "语义：考试没过，心里不会高兴，与句中的情况相反。", "清脆": "搭配：“清脆”形容声音，不能用来形容心情。", "高大": "体貌：“高大”描写人的身材，不能用来说心里的感受。"}, "sentence_index": 0, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他收到录取通知，绝望地跳了起来。", "explanation": "这里应该用〈高兴〉。收到录取通知是喜事，“绝望”表示彻底没有希望，不能用来修饰高兴地跳起来的动作。"}, {"text": "他刚买的新车特别好，他很绝望。", "explanation": "这里应该用〈满意〉。买到称心的新车是好事，“绝望”表示彻底没有希望，与此矛盾。"}, {"text": "听到好消息，她终于绝望了。", "explanation": "这里应该用〈放心〉。听到好消息应该说“放心”，“绝望”表示彻底没有希望，与好消息正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”指彻底没有希望，与“没有人帮忙、一个人”的处境相符。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”指人多、有声响，与“没有人帮忙”“一个人”矛盾。"}, {"text": "齐全", "is_correct": false, "explanation": "搭配：“齐全”指东西完备，不能用来形容人的心情。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或眼神，不用来说心里的感受。"}], "explanations": {"绝望": "“绝望”指彻底没有希望，与“没有人帮忙、一个人”的处境相符。", "热闹": "语义：“热闹”指人多、有声响，与“没有人帮忙”“一个人”矛盾。", "齐全": "搭配：“齐全”指东西完备，不能用来形容人的心情。", "明亮": "体貌：“明亮”形容光线或眼神，不用来说心里的感受。"}, "sentence_index": 6, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他考了全班第一，很绝望。", "explanation": "这里应该用〈得意〉。考了全班第一是值得骄傲的事，“绝望”表示彻底没有希望，两者正好相反。"}, {"text": "手术很顺利，家人都很绝望。", "explanation": "这里应该用〈安心〉。手术顺利时家人应该安心，“绝望”表示彻底没有希望，与结果相反。"}, {"text": "天气很好，我特别绝望。", "explanation": "这里应该用〈愉快〉。天气好时心情应该说“愉快”，“绝望”表示彻底没有希望，两者正好相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他绝望的看着窗外的雨。", "corrected_sentence": "他绝望地看着窗外的雨。", "error_description": "“绝望”修饰动词“看”时要用“地”，不能用“的”。应说“绝望地看着”，写成“绝望的看着”是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94069, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找不到出路，成了绝望地人。", "corrected_sentence": "我找不到出路，成了绝望的人。", "error_description": "“绝望”修饰名词“人”时要用“的”，不能用“地”。“地”用来修饰动词或形容词，此处“绝望地人”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "希望", "is_correct": true, "explanation": "“希望”与“绝望”相对，指对事情仍抱有盼望。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”指动脑子想问题，与“绝望”没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "“讨论”指大家交换意见，与“绝望”没有反义关系。"}, {"text": "解释", "is_correct": false, "explanation": "“解释”指说明道理，与“绝望”没有反义关系。"}], "correct_answer": "希望", "explanations": {"希望": "“希望”与“绝望”相对，指对事情仍抱有盼望。", "思考": "“思考”指动脑子想问题，与“绝望”没有反义关系。", "讨论": "“讨论”指大家交换意见，与“绝望”没有反义关系。", "解释": "“解释”指说明道理，与“绝望”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "希望", "is_correct": true, "explanation": "“希望”与“绝望”相对，指对事情仍抱有盼望。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”指把杂乱的东西归置好，与“绝望”没有反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "“研究”指深入探讨问题，与“绝望”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“绝望”没有反义关系。"}], "correct_answer": "希望", "explanations": {"希望": "“希望”与“绝望”相对，指对事情仍抱有盼望。", "整理": "“整理”指把杂乱的东西归置好，与“绝望”没有反义关系。", "研究": "“研究”指深入探讨问题，与“绝望”没有反义关系。", "旅行": "“旅行”指到外地游览，与“绝望”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "完全失去希望，认为不可能再有转机。", "primary_collocate": null, "pronunciation": "jué wàng", "ipa": "tɕɥe˧˥ wɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他对生活绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说还有办法，你别绝望。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对这个人已经绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人的家人从没有绝望过。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的未来完全绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援还在继续，我们不能对他绝望。", "target_word": "绝望", "complexity_tier": "T3", "furigana": "jiù yuán hái zài jì xù, wǒ men bù néng duì tā jué wàng.", "sentence_source": "generated"}, {"text": "弟弟对学习绝望，不想再读书了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人对儿子绝望，决定一个人生活。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛只剩一分钟，球迷对结果绝望了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她曾经对爱情绝望，现在又相信了。", "target_word": "绝望", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绝望了", "label": "体标"}, {"form": "绝望过", "label": "体标"}, {"form": "絕望", "label": "繁体"}], "register": "中性", "sense_fingerprint": "对人或事完全失去希望，认为没有转机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”作动词，表示对生活完全失去希望，与句子相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能说“对生活参观”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不能用于“生活”。"}, {"text": "瞻仰", "is_correct": false, "explanation": "语域：“瞻仰”是书面语，只用于人物或遗迹，不能说“对生活瞻仰”。"}], "explanations": {"绝望": "“绝望”作动词，表示对生活完全失去希望，与句子相符。", "参观": "搭配：“参观”的对象是场所或展览，不能说“对生活参观”。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不能用于“生活”。", "瞻仰": "语域：“瞻仰”是书面语，只用于人物或遗迹，不能说“对生活瞻仰”。"}, "sentence_index": 0, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务好极了，我对它很绝望。", "explanation": "这里应该用〈满意〉。服务好极了应该说“满意”，“绝望”表示对事情彻底不抱希望，与这样的评价矛盾。"}, {"text": "学校为他安排了好老师，他对此很绝望。", "explanation": "这里应该用〈欣慰〉。学校安排了好老师是让人欣慰的事，“绝望”表示彻底不抱希望，与此相反。"}, {"text": "孩子的身体已经完全康复了，她对此很绝望。", "explanation": "这里应该用〈放心〉。身体康复后应该说“放心”，“绝望”表示对事情不再抱任何希望，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绝望", "is_correct": true, "explanation": "“绝望”作动词，表示对学习失去希望，与后句“不想再读书了”相符。"}, {"text": "热衷", "is_correct": false, "explanation": "语义：“热衷”表示积极投入，与后句“不想再读书了”矛盾。"}, {"text": "请教", "is_correct": false, "explanation": "配价：“请教”要求说明对象是人，不能带“对学习”这样的宾语。"}, {"text": "珍惜", "is_correct": false, "explanation": "语义：“珍惜”表示爱惜，与后句“不想再读书了”矛盾。"}], "explanations": {"绝望": "“绝望”作动词，表示对学习失去希望，与后句“不想再读书了”相符。", "热衷": "语义：“热衷”表示积极投入，与后句“不想再读书了”矛盾。", "请教": "配价：“请教”要求说明对象是人，不能带“对学习”这样的宾语。", "珍惜": "语义：“珍惜”表示爱惜，与后句“不想再读书了”矛盾。"}, "sentence_index": 6, "correct_answer": "绝望"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们大获全胜，大家都很绝望。", "explanation": "这里应该用〈兴奋〉。大获全胜是令人振奋的事，“绝望”表示对事情彻底不抱希望，与此矛盾。"}, {"text": "他拿到了满分，妈妈为此很绝望。", "explanation": "这里应该用〈骄傲〉。拿到满分值得骄傲，“绝望”表示彻底失去希望，两者正好相反。"}, {"text": "终于找到了失散多年的亲人，她很绝望。", "explanation": "这里应该用〈激动〉。找到失散多年的亲人是让人激动的事，“绝望”表示不再抱任何希望，不能用于这种情形。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这份工作绝望了。", "corrected_sentence": "他对这份工作绝望了。", "error_description": "“绝望”作动词时，它的对象要由介词“对”引出，漏掉“对”就不通。应说“他对这份工作绝望了”，不能说“他这份工作绝望了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94070, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跟这场比赛绝望过，后来又振作起来了。", "corrected_sentence": "他对这场比赛绝望过，后来又振作起来了。", "error_description": "“绝望”的对象要由介词“对”引出，不能用“跟”。应说“对这场比赛绝望过”，不能说“跟这场比赛绝望过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
