INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94076, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修补破损的东西，或把缺少的部分添上。", "primary_collocate": null, "pronunciation": "bǔ", "ipa": "pu˨˩˦", "syllable_count": 1, "sentences": [{"text": "奶奶会用小布条补旧衣服。", "target_word": "补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "牙坏了一个洞，医生帮他补好了。", "target_word": "补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "窗户的玻璃碎了，明天请人来补。", "target_word": "补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "渔网破了，爷爷坐在门口补着。", "target_word": "补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路有个坑，工人用土把它补平了。", "target_word": "补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶漏雨了，我们得马上补。", "target_word": "补", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书里少了一页，店员说可以帮我补上。", "target_word": "补", "complexity_tier": "T3", "furigana": "shū lǐ shǎo le yí yè, diànyuán shuō kěyǐ bāng wǒ bǔ shang。", "sentence_source": "generated"}, {"text": "他把破帐篷补过很多次。", "target_word": "补", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份表格少了一行，我等会儿补上。", "target_word": "补", "complexity_tier": "T3", "furigana": "zhè fèn biǎo gé shǎo le yì háng, wǒ děng huìr bǔ shang。", "sentence_source": "generated"}, {"text": "我的鞋子开线了，要拿去店里补。", "target_word": "补", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "补了", "label": "体标"}, {"form": "补过", "label": "体标"}, {"form": "补补", "label": "重叠"}, {"form": "補", "label": "繁体"}], "register": "中性", "sense_fingerprint": "修补破损的东西或添上缺少的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d7132db-349d-4d06-b68d-82e6dd273dcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94076, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "补", "is_correct": true, "explanation": "正确：补指修补破损的东西。"}, {"text": "步", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，意思是脚步。"}, {"text": "普", "is_correct": false, "explanation": "pǔ 与 bǔ 声母不同（p 与 b），意思是普通、普遍。"}, {"text": "赌", "is_correct": false, "explanation": "dǔ 与 bǔ 声母不同（d 与 b），意思是赌博。"}, {"text": "土", "is_correct": false, "explanation": "tǔ 与 bǔ 声母不同（t 与 b），意思是泥土。"}], "explanations": {"补": "正确：补指修补破损的东西。", "步": "bù（第四声）与 bǔ（第三声）声调不同，意思是脚步。", "普": "pǔ 与 bǔ 声母不同（p 与 b），意思是普通、普遍。", "赌": "dǔ 与 bǔ 声母不同（d 与 b），意思是赌博。", "土": "tǔ 与 bǔ 声母不同（t 与 b），意思是泥土。"}, "sentence_index": null, "correct_answer": "补"}, "level_3": {"options": [{"text": "补", "is_correct": true, "explanation": "正确：补指修补破旧的衣服，与“小布条”搭配。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧是焚毁，不能用来修补衣服。"}, {"text": "穿", "is_correct": false, "explanation": "语义：穿是穿戴，与用小布条修补的意思不符。"}, {"text": "挂", "is_correct": false, "explanation": "搭配：挂是晾挂，不能用小布条去挂旧衣服。"}], "explanations": {"补": "正确：补指修补破旧的衣服，与“小布条”搭配。", "烧": "语义：烧是焚毁，不能用来修补衣服。", "穿": "语义：穿是穿戴，与用小布条修补的意思不符。", "挂": "搭配：挂是晾挂，不能用小布条去挂旧衣服。"}, "sentence_index": 0, "correct_answer": "补"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用尺子补了桌子的长度。", "explanation": "这里应该用〈量〉。补表示修补或补上缺少的部分，测量长度要用量。"}, {"text": "他把垃圾补掉了。", "explanation": "这里应该用〈扔〉。补不表示丢弃，把垃圾丢掉要用扔。"}, {"text": "他把长头发补短了。", "explanation": "这里应该用〈剪〉。补不表示剪短，修剪头发要用剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94076, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "补", "is_correct": true, "explanation": "正确：补指修补破损的东西，或补上缺少的部分。"}, {"text": "布", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，意思是布料。"}, {"text": "谱", "is_correct": false, "explanation": "pǔ 与 bǔ 声母不同（p 与 b），意思是乐谱、图谱。"}, {"text": "堵", "is_correct": false, "explanation": "dǔ 与 bǔ 声母不同（d 与 b），意思是堵塞。"}, {"text": "不", "is_correct": false, "explanation": "bù（第四声）与 bǔ（第三声）声调不同，表示否定。"}], "explanations": {"补": "正确：补指修补破损的东西，或补上缺少的部分。", "布": "bù（第四声）与 bǔ（第三声）声调不同，意思是布料。", "谱": "pǔ 与 bǔ 声母不同（p 与 b），意思是乐谱、图谱。", "堵": "dǔ 与 bǔ 声母不同（d 与 b），意思是堵塞。", "不": "bù（第四声）与 bǔ（第三声）声调不同，表示否定。"}, "sentence_index": null, "correct_answer": "补"}, "level_3": {"options": [{"text": "补", "is_correct": true, "explanation": "正确：补指补上缺少的部分，与“少了一页”搭配。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：戴上搭配帽子、眼镜，不能用于书页。"}, {"text": "摔", "is_correct": false, "explanation": "语义：摔是猛然碰撞或掷下，与补上书页的意思不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：穿上搭配衣服、鞋袜，不能用于书页。"}], "explanations": {"补": "正确：补指补上缺少的部分，与“少了一页”搭配。", "戴": "搭配：戴上搭配帽子、眼镜，不能用于书页。", "摔": "语义：摔是猛然碰撞或掷下，与补上书页的意思不符。", "穿": "搭配：穿上搭配衣服、鞋袜，不能用于书页。"}, "sentence_index": 6, "correct_answer": "补"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去花园补了一朵花。", "explanation": "这里应该用〈摘〉。补表示修补或补上缺少的部分，采摘花朵要用摘。"}, {"text": "我把脏衣服补干净了。", "explanation": "这里应该用〈洗〉。补不表示去除污渍，洗干净要用洗。"}, {"text": "他把书桌补到了窗边。", "explanation": "这里应该用〈搬〉。补表示修补或补上缺少的部分，移动位置要用搬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94076, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷坐在门口补了着渔网。", "corrected_sentence": "爷爷坐在门口补着渔网。", "error_description": "错误形式：「补了着」。正确形式：「补着」。「了」与「着」不能同时加在同一动词后，表示持续状态只用「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94076, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的皮鞋开线了，打算拿去店里补了。", "corrected_sentence": "我的皮鞋开线了，打算拿去店里补。", "error_description": "错误形式：「补了」。正确形式：「补」。「打算」表示未来的意图，句中不能再用完成标记「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
