INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94079, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "躲是藏起来或走开，不让别人看见或碰到。", "primary_collocate": null, "pronunciation": "duǒ", "ipa": "tuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "捉迷藏时，他躲在大树后面。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗怕打雷，躲到了床下。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见老板走来，赶快躲到一边。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟躲在窗帘后面，没有出声。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个人一直在躲我，不想见面。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，路上的人都躲进了店里。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想让朋友看见，就躲起来了。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老鼠看到猫，一下子躲进洞里。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没做完作业，所以躲着老师。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别躲了，我已经看见你了。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "躲了", "label": "体标"}, {"form": "躲着", "label": "体标"}, {"form": "躲起来", "label": "复合"}, {"form": "躲藏", "label": "复合"}, {"form": "躲避", "label": "复合"}], "register": "通用", "sense_fingerprint": "藏起来或走开，不让别人看见或碰到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94079, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：听到的是「躲」duǒ（第三声），意思是藏起来或走开。"}, {"text": "多", "is_correct": false, "explanation": "「多」duō（第一声）与「躲」duǒ声调不同，意思是数量大。"}, {"text": "夺", "is_correct": false, "explanation": "「夺」duó（第二声）与「躲」duǒ声调不同，意思是抢夺。"}, {"text": "剁", "is_correct": false, "explanation": "「剁」duò（第四声）与「躲」duǒ声调不同，意思是用刀切。"}, {"text": "妥", "is_correct": false, "explanation": "「妥」tuǒ与「躲」duǒ声母不同（t与d），意思是妥当。"}], "explanations": {"躲": "正确：听到的是「躲」duǒ（第三声），意思是藏起来或走开。", "多": "「多」duō（第一声）与「躲」duǒ声调不同，意思是数量大。", "夺": "「夺」duó（第二声）与「躲」duǒ声调不同，意思是抢夺。", "剁": "「剁」duò（第四声）与「躲」duǒ声调不同，意思是用刀切。", "妥": "「妥」tuǒ与「躲」duǒ声母不同（t与d），意思是妥当。"}, "sentence_index": null, "correct_answer": "躲"}, "level_3": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：「躲在大树后面」表示藏身，符合捉迷藏的情境。"}, {"text": "露", "is_correct": false, "explanation": "语义：「露」表示显露出来，与「捉迷藏」要隐蔽的情境矛盾。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：「吃」不能用来表示在大树后面藏身，搭配不通。"}, {"text": "写", "is_correct": false, "explanation": "配价：「写」需要书写的对象，不能用「在大树后面」表示位置。"}], "explanations": {"躲": "正确：「躲在大树后面」表示藏身，符合捉迷藏的情境。", "露": "语义：「露」表示显露出来，与「捉迷藏」要隐蔽的情境矛盾。", "吃": "搭配：「吃」不能用来表示在大树后面藏身，搭配不通。", "写": "配价：「写」需要书写的对象，不能用「在大树后面」表示位置。"}, "sentence_index": 0, "correct_answer": "躲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他躲了自己的病情。", "explanation": "这里应该用〈隐瞒〉。「躲」表示避开或藏身，不能带「病情」作宾语，隐瞒信息要说「隐瞒」。"}, {"text": "他把信躲在花盆下面。", "explanation": "这里应该用〈藏〉。「躲」的动作由人自己完成，不能带「信」作宾语，把东西隐藏起来要说「藏」。"}, {"text": "一堵墙躲住了风。", "explanation": "这里应该用〈挡〉。「躲」的主语要能自己走开或藏身，墙不能躲，挡风要说「挡」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94079, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：听到的是「躲」duǒ（第三声），意思是藏起来或走开。"}, {"text": "抖", "is_correct": false, "explanation": "「抖」dǒu（第三声）与「躲」duǒ韵母不同（ou与uo），意思是振动。"}, {"text": "堵", "is_correct": false, "explanation": "「堵」dǔ（第三声）与「躲」duǒ韵母不同（u与uo），意思是堵塞。"}, {"text": "舵", "is_correct": false, "explanation": "「舵」duò（第四声）与「躲」duǒ声调不同，意思是船舵。"}, {"text": "跺", "is_correct": false, "explanation": "「跺」duò（第四声）与「躲」duǒ声调不同，意思是用脚踩地。"}], "explanations": {"躲": "正确：听到的是「躲」duǒ（第三声），意思是藏起来或走开。", "抖": "「抖」dǒu（第三声）与「躲」duǒ韵母不同（ou与uo），意思是振动。", "堵": "「堵」dǔ（第三声）与「躲」duǒ韵母不同（u与uo），意思是堵塞。", "舵": "「舵」duò（第四声）与「躲」duǒ声调不同，意思是船舵。", "跺": "「跺」duò（第四声）与「躲」duǒ声调不同，意思是用脚踩地。"}, "sentence_index": null, "correct_answer": "躲"}, "level_3": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：「躲起来」表示藏起来，不让朋友看见，符合语境。"}, {"text": "站", "is_correct": false, "explanation": "语义：「站起来」会被朋友看见，与「不想让朋友看见」矛盾。"}, {"text": "拿", "is_correct": false, "explanation": "语义：「拿起来」是拿取东西，与「不想让朋友看见」要躲藏的意思不符。"}, {"text": "唱", "is_correct": false, "explanation": "语义：「唱起来」会引人注意，与「不想让朋友看见」矛盾。"}], "explanations": {"躲": "正确：「躲起来」表示藏起来，不让朋友看见，符合语境。", "站": "语义：「站起来」会被朋友看见，与「不想让朋友看见」矛盾。", "拿": "语义：「拿起来」是拿取东西，与「不想让朋友看见」要躲藏的意思不符。", "唱": "语义：「唱起来」会引人注意，与「不想让朋友看见」矛盾。"}, "sentence_index": 6, "correct_answer": "躲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了这话，眼泪躲了出来。", "explanation": "这里应该用〈流〉。「躲」的主语须是能自己避开或藏身的人或动物，眼泪不能躲，流出来要说「流」。"}, {"text": "他用毛巾躲干了手。", "explanation": "这里应该用〈擦干〉。「躲」没有除去水渍的意思，把手擦干要说「擦干」。"}, {"text": "他把窗户躲开了。", "explanation": "这里应该用〈推开〉。「躲开」是人或物自己避开，不能带「窗户」作宾语表示打开，要说「推开」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content,