INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94079, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一听见妈妈的声音，小猫就躲了床底下。", "corrected_sentence": "一听见妈妈的声音，小猫就躲到了床底下。", "error_description": "错误：「躲了床底下」，缺少处所成分「到」。正确：「躲到了床底下」。「躲」后面要带「到、进、在」等表示处所的成分才能成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94079, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他怕挨骂，一直躲班主任。", "corrected_sentence": "他怕挨骂，一直躲着班主任。", "error_description": "错误：「一直躲班主任」，缺少动态助词「着」。正确：「一直躲着班主任」。表示持续地避开某人时，动词「躲」后要带「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
