INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94080, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "设法避开或隐藏起来，使人或物不能发现、触及。", "primary_collocate": null, "pronunciation": "duǒ", "ipa": "tuɔ˨˩˦", "syllable_count": 1, "sentences": [{"text": "下雨了，我们快躲到树下吧。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一看见老师就躲了起来。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球飞过来了，他没有躲。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫怕狗，躲在桌子下面。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么一直躲着我？", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子做错了事，躲在房间里不出来。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳太大，我们躲进商店里休息。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有困难就要面对，不要躲。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他躲在门后面，想吓妈妈一跳。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面风很大，大家都躲进了屋里。", "target_word": "躲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "躲了", "label": "体标"}, {"form": "躲着", "label": "体标"}, {"form": "躲起来", "label": "复合"}, {"form": "躲藏", "label": "复合"}, {"form": "躲避", "label": "复合"}], "register": "通用", "sense_fingerprint": "设法避开或隐藏，不让人或物碰到、发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed0c4cfe-367f-4222-8eac-27cac2d37f6c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94080, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：听到的是「躲」duǒ（第三声），意思是设法避开或藏起来。"}, {"text": "多", "is_correct": false, "explanation": "「多」duō（第一声）与「躲」duǒ声调不同，意思是数量大。"}, {"text": "夺", "is_correct": false, "explanation": "「夺」duó（第二声）与「躲」duǒ声调不同，意思是抢夺。"}, {"text": "剁", "is_correct": false, "explanation": "「剁」duò（第四声）与「躲」duǒ声调不同，意思是用刀切。"}, {"text": "妥", "is_correct": false, "explanation": "「妥」tuǒ与「躲」duǒ声母不同（t与d），意思是妥当。"}], "explanations": {"躲": "正确：听到的是「躲」duǒ（第三声），意思是设法避开或藏起来。", "多": "「多」duō（第一声）与「躲」duǒ声调不同，意思是数量大。", "夺": "「夺」duó（第二声）与「躲」duǒ声调不同，意思是抢夺。", "剁": "「剁」duò（第四声）与「躲」duǒ声调不同，意思是用刀切。", "妥": "「妥」tuǒ与「躲」duǒ声母不同（t与d），意思是妥当。"}, "sentence_index": null, "correct_answer": "躲"}, "level_3": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：「躲到树下」表示为了避雨而到树下藏身，符合语境。"}, {"text": "晒", "is_correct": false, "explanation": "语义：「晒」指被阳光照射，与「下雨了」的情境矛盾。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：「洗」不能与「到树下」组合表示避雨，语境不通。"}, {"text": "写", "is_correct": false, "explanation": "配价：「写」需要书写的对象作宾语，不能带处所补语「到树下」。"}], "explanations": {"躲": "正确：「躲到树下」表示为了避雨而到树下藏身，符合语境。", "晒": "语义：「晒」指被阳光照射，与「下雨了」的情境矛盾。", "洗": "搭配：「洗」不能与「到树下」组合表示避雨，语境不通。", "写": "配价：「写」需要书写的对象作宾语，不能带处所补语「到树下」。"}, "sentence_index": 0, "correct_answer": "躲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把书躲在书包里。", "explanation": "这里应该用〈藏〉。「躲」表示人自己避开或藏身，不能带「书」这样的物体作宾语，把东西放起来要说「藏」。"}, {"text": "会议躲到下周了。", "explanation": "这里应该用〈推迟〉。「躲」的主语应是能自己避开的人或动物，会议被延后要说「推迟」。"}, {"text": "她用手躲住了脸。", "explanation": "这里应该用〈捂〉。「躲」不表示遮盖，用手遮住脸要说「捂住」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94080, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：听到的是「躲」duǒ（第三声），意思是设法避开或藏起来。"}, {"text": "抖", "is_correct": false, "explanation": "「抖」dǒu（第三声）与「躲」duǒ韵母不同（ou与uo），意思是振动。"}, {"text": "堵", "is_correct": false, "explanation": "「堵」dǔ（第三声）与「躲」duǒ韵母不同（u与uo），意思是堵塞。"}, {"text": "舵", "is_correct": false, "explanation": "「舵」duò（第四声）与「躲」duǒ声调不同，意思是船舵。"}, {"text": "跺", "is_correct": false, "explanation": "「跺」duò（第四声）与「躲」duǒ声调不同，意思是用脚踩地。"}], "explanations": {"躲": "正确：听到的是「躲」duǒ（第三声），意思是设法避开或藏起来。", "抖": "「抖」dǒu（第三声）与「躲」duǒ韵母不同（ou与uo），意思是振动。", "堵": "「堵」dǔ（第三声）与「躲」duǒ韵母不同（u与uo），意思是堵塞。", "舵": "「舵」duò（第四声）与「躲」duǒ声调不同，意思是船舵。", "跺": "「跺」duò（第四声）与「躲」duǒ声调不同，意思是用脚踩地。"}, "sentence_index": null, "correct_answer": "躲"}, "level_3": {"options": [{"text": "躲", "is_correct": true, "explanation": "正确：「躲进商店」表示为避开烈日而进店，符合语境。"}, {"text": "淋", "is_correct": false, "explanation": "语义：「淋」指被雨水浇，与「太阳太大」的情境矛盾。"}, {"text": "晒", "is_correct": false, "explanation": "搭配：「晒」是被阳光照射，不能带「进商店里」的处所补语，「晒进商店里」不成句。"}, {"text": "扔", "is_correct": false, "explanation": "配价：「扔」需要被扔的东西作宾语，「我们扔进商店里」不成立。"}], "explanations": {"躲": "正确：「躲进商店」表示为避开烈日而进店，符合语境。", "淋": "语义：「淋」指被雨水浇，与「太阳太大」的情境矛盾。", "晒": "搭配：「晒」是被阳光照射，不能带「进商店里」的处所补语，「晒进商店里」不成句。", "扔": "配价：「扔」需要被扔的东西作宾语，「我们扔进商店里」不成立。"}, "sentence_index": 6, "correct_answer": "躲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一紧张，手心躲出了汗。", "explanation": "这里应该用〈冒〉。「躲」的主语须是能自己避开或藏身的人或动物，汗不能躲，「手心冒汗」才自然。"}, {"text": "他用袖子躲了躲汗。", "explanation": "这里应该用〈擦〉。「躲」没有除去脏东西的意思，擦汗要说「擦」。"}, {"text": "我们把门躲上了。", "explanation": "这里应该用〈关〉。「躲」不能带「门」作宾语表示关闭，把门关上要说「关」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94080, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他听见门响，赶紧躲了桌子底下。", "corrected_sentence": "他听见门响，赶紧躲到了桌子底下。", "error_description": "错误：「躲了桌子底下」，缺少处所成分「到」。正确：「躲到了桌子底下」。「躲」表示避开或藏身，后面要带「到、进、在」等表示处所的成分才能成句。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94080, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他怕被妈妈骂，就整天躲她着。", "corrected_sentence": "他怕被妈妈骂，就整天躲着她。", "error_description": "错误：「躲她着」，动态助词「着」放错了位置。正确：「躲着她」。「着」应紧跟在动词后面，表示动作持续。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c0c618-cc8c-461c-b87a-986decb259ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
