INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94084, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94084, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "两地之间可供人、车辆或物体通行的路径。", "primary_collocate": null, "pronunciation": "tōng dào", "ipa": "tʰʊŋ˥ taʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这条通道连着两座大楼。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里有一条通道，可以到对面的村子。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从这条通道流到河里。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们打开了通道，车终于过去了。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两座城市之间有一条新通道。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条通道很窄，大车开不过去。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪太大，山上的通道关了。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物们从一条小通道走到了河边。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边有一条通道，船可以通过。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们找到了去对面的通道。", "target_word": "通道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "两地之间可通行的路径", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f1d60f8e-cf7f-4e4e-b486-7bb9d64b7105') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通道", "is_correct": true, "explanation": "正确。“这条通道连着两座大楼”中，通道指连接两地的路径，与语境相符。"}, {"text": "水井", "is_correct": false, "explanation": "语义：水井不能连接大楼，“这条水井连着两座大楼”说不通。"}, {"text": "驿道", "is_correct": false, "explanation": "语域：“驿道”是古代驿站间的道路，属历史书面用语，不用于描述现代大楼之间的连接。"}, {"text": "墓道", "is_correct": false, "explanation": "语义：墓道是墓穴中的通道，与两座大楼无关，“连着两座大楼”不成立。"}], "explanations": {"通道": "正确。“这条通道连着两座大楼”中，通道指连接两地的路径，与语境相符。", "水井": "语义：水井不能连接大楼，“这条水井连着两座大楼”说不通。", "驿道": "语域：“驿道”是古代驿站间的道路，属历史书面用语，不用于描述现代大楼之间的连接。", "墓道": "语义：墓道是墓穴中的通道，与两座大楼无关，“连着两座大楼”不成立。"}, "sentence_index": 0, "correct_answer": "通道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们打开了通道，取出了钥匙。", "explanation": "这里应该用〈抽屉〉。通道是供人、车通行的路径，不能从里面取东西；打开、取东西的是抽屉。"}, {"text": "老师在通道上写了三个字。", "explanation": "这里应该用〈黑板〉。通道是供人、车通行的路径，不能用来写字；写字要在黑板上。"}, {"text": "工人们打开了一把通道，车终于过去了。", "explanation": "这里应该用〈条〉。通道用量词“条”，“把”用于有柄的东西，不说“一把通道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通道", "is_correct": true, "explanation": "正确。“雪太大，山上的通道关了”中，通道指山上可通行的路，“关”用于路的封闭，与语境相符。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不能“关闭”，“山上的河流关了”与常识不符。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不能被“关”，“山上的星星关了”说不通。"}, {"text": "雪季", "is_correct": false, "explanation": "搭配：“关”多用于门、路等可通行的地方，不说“雪季关了”。"}], "explanations": {"通道": "正确。“雪太大，山上的通道关了”中，通道指山上可通行的路，“关”用于路的封闭，与语境相符。", "河流": "语义：河流不能“关闭”，“山上的河流关了”与常识不符。", "星星": "语义：星星不能被“关”，“山上的星星关了”说不通。", "雪季": "搭配：“关”多用于门、路等可通行的地方，不说“雪季关了”。"}, "sentence_index": 6, "correct_answer": "通道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条通道每天能制造很多冰。", "explanation": "这里应该用〈制冰机〉。通道是供人、车通行的路径，不能用来制冰；制冰要用机器。"}, {"text": "他们沿通道上到了五楼。", "explanation": "这里应该用〈楼梯〉。通道是平行通行的路，不能用来上下楼；上楼要用楼梯或电梯。"}, {"text": "他们找到了去对面的一张通道。", "explanation": "这里应该用〈条〉。通道用量词“条”，“张”用于平面的东西，不说“一张通道”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张通道一直通到河边。", "corrected_sentence": "这条通道一直通到河边。", "error_description": "“通道”应用量词“条”，不用“张”（“张”多用于平面的东西）。错误形式：这张通道；正确形式：这条通道。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山上找到了一只新通道。", "corrected_sentence": "他们在山上找到了一条新通道。", "error_description": "“通道”应用量词“条”，不用“只”（“只”多用于动物等）。错误形式：一只新通道；正确形式：一条新通道。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '78f36863-349e-4c5e-8a86-6cf49f30a7c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
