INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "真正的、纯正的，具有地方特色的。", "primary_collocate": null, "pronunciation": "dào dì", "ipa": "taʊ˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他说一口道地的北京话。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的英语说得很道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一家道地的老北京饭馆。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是个道地的北京人。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服用的是道地的苗族绣花。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱了一首道地的陕北民歌。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们说道地的中文。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜都是道地的湖南味道。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看一场道地的京剧。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的广东话说得很道地。", "target_word": "道地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "真正的、纯正的，带有地方特色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确答案。道地读 dào dì（第四声），意思是真正的、纯正的。"}, {"text": "倒地", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，倒地意思是跌倒在地上。"}, {"text": "到底", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，到底意思是究竟、终究。"}, {"text": "大地", "is_correct": false, "explanation": "大地读 dà dì，韵母 a 与 dào 的 ao 不同，意思是地面、土地。"}, {"text": "大帝", "is_correct": false, "explanation": "大帝读 dà dì，韵母与 dào 不同，意思是对帝王的尊称，如彼得大帝。"}, {"text": "大敌", "is_correct": false, "explanation": "大敌读 dà dí，第二音节 dí 为第二声，与 dì（第四声）声调不同，意思是强大的敌人。"}], "explanations": {"道地": "正确答案。道地读 dào dì（第四声），意思是真正的、纯正的。", "倒地": "dǎo（第三声）与 dào（第四声）声调不同，倒地意思是跌倒在地上。", "到底": "dǐ（第三声）与 dì（第四声）声调不同，到底意思是究竟、终究。", "大地": "大地读 dà dì，韵母 a 与 dào 的 ao 不同，意思是地面、土地。", "大帝": "大帝读 dà dì，韵母与 dào 不同，意思是对帝王的尊称，如彼得大帝。", "大敌": "大敌读 dà dí，第二音节 dí 为第二声，与 dì（第四声）声调不同，意思是强大的敌人。"}, "sentence_index": null, "correct_answer": "道地"}, "level_3": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确。“道地”修饰北京话，表示纯正的北京口音。"}, {"text": "笨重", "is_correct": false, "explanation": "语义：“笨重”形容物体沉重而不灵便，不能用来形容口音。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：“潮湿”形容空气或物体含水多，不能用来形容说话的口音。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”形容人的身材，不能用来形容口音。"}], "explanations": {"道地": "正确。“道地”修饰北京话，表示纯正的北京口音。", "笨重": "语义：“笨重”形容物体沉重而不灵便，不能用来形容口音。", "潮湿": "语义：“潮湿”形容空气或物体含水多，不能用来形容说话的口音。", "矮小": "体貌：“矮小”形容人的身材，不能用来形容口音。"}, "sentence_index": 0, "correct_answer": "道地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月的房租很道地。", "explanation": "这里应该用〈便宜〉。道地说的是正宗、有地方特色，不用来评价价格高低。"}, {"text": "他的身高很道地。", "explanation": "这里应该用〈高〉。道地不用来形容身高，身高要说“高”或“矮”。"}, {"text": "这封信寄得很道地。", "explanation": "这里应该用〈快〉。道地不用来形容速度，寄信快慢要说“快”或“慢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道地", "is_correct": true, "explanation": "正确。“道地”修饰中文，表示纯正、地道的中文。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”形容天气或温度低，不能用来形容语言。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势或坡度，不能用来形容语言。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或物的体型，不能用来形容中文。"}], "explanations": {"道地": "正确。“道地”修饰中文，表示纯正、地道的中文。", "寒冷": "语义：“寒冷”形容天气或温度低，不能用来形容语言。", "陡峭": "语义：“陡峭”形容地势或坡度，不能用来形容语言。", "高大": "体貌：“高大”形容人或物的体型，不能用来形容中文。"}, "sentence_index": 6, "correct_answer": "道地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个变化很道地。", "explanation": "这里应该用〈明显〉。道地用于正宗、有地方特色的事物，不用来形容变化是否明显。"}, {"text": "这个数字很道地。", "explanation": "这里应该用〈大〉。道地不用来形容数字的大小，数字的大小要说“大”或“小”。"}, {"text": "这份合同很道地。", "explanation": "这里应该用〈严谨〉。道地说的是正宗、有地方特色，不用来评价合同是否严谨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94088, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她的日语说很道地。", "corrected_sentence": "她的日语说得很道地。", "error_description": "“说很道地”漏了“得”，应为“说得很道地”：动词后带形容词作补语时，须用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
