INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94092, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "标点符号的一类，表示语句中的停顿，包括逗号、顿号、分号、句号等。", "primary_collocate": null, "pronunciation": "diǎn hào", "ipa": "tjɛn²¹⁴ xɑʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "逗号和句号都是点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点号表示句子里的停顿。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顿号也是一种点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "分号是点号，不是标号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了点号的用法。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话里的点号用错了。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点号包括逗号、顿号、分号和句号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写文章时，要注意用好点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "句子中间的停顿要用点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这一页有很多点号。", "target_word": "点号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "书面", "sense_fingerprint": "名词，标点符号中表示停顿的一类，包括逗号、顿号、分号、句号等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94092, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "点号", "is_correct": true, "explanation": "正确：逗号和句号都属于点号，是表示停顿的标点。"}, {"text": "汉字", "is_correct": false, "explanation": "语义：逗号和句号是标点符号，不是汉字。"}, {"text": "数字", "is_correct": false, "explanation": "语义：逗号和句号是标点符号，不是数字。"}, {"text": "偏旁", "is_correct": false, "explanation": "语义：逗号和句号不是汉字的组成部分，“逗号和句号都是偏旁”不成立。"}], "explanations": {"点号": "正确：逗号和句号都属于点号，是表示停顿的标点。", "汉字": "语义：逗号和句号是标点符号，不是汉字。", "数字": "语义：逗号和句号是标点符号，不是数字。", "偏旁": "语义：逗号和句号不是汉字的组成部分，“逗号和句号都是偏旁”不成立。"}, "sentence_index": 0, "correct_answer": "点号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "书名号是一种点号。", "explanation": "这里应该用〈标号〉。书名号属于标号，不属于点号；点号指逗号、句号等表示停顿的标点。"}, {"text": "引号是一种点号，用来标示引用的话。", "explanation": "这里应该用〈标号〉。引号属于标号，用来标示引用的话；点号指逗号、句号等表示停顿的标点。"}, {"text": "破折号是一种点号，用来表示解释或转折。", "explanation": "这里应该用〈标号〉。破折号属于标号，不属于点号；点号指逗号、句号等表示停顿的标点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94092, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "点号", "is_correct": true, "explanation": "正确：逗号、顿号、分号和句号都属于点号。"}, {"text": "词语", "is_correct": false, "explanation": "语义：逗号、顿号等是标点，不是词语，“词语包括逗号”不成立。"}, {"text": "字母", "is_correct": false, "explanation": "语义：标点符号不是字母，“字母包括逗号”不成立。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是用来演奏的器具，逗号、顿号等标点不是乐器，“乐器包括逗号”不成立。"}], "explanations": {"点号": "正确：逗号、顿号、分号和句号都属于点号。", "词语": "语义：逗号、顿号等是标点，不是词语，“词语包括逗号”不成立。", "字母": "语义：标点符号不是字母，“字母包括逗号”不成立。", "乐器": "语义：乐器是用来演奏的器具，逗号、顿号等标点不是乐器，“乐器包括逗号”不成立。"}, "sentence_index": 6, "correct_answer": "点号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "括号是一种点号，用来标示补充说明的内容。", "explanation": "这里应该用〈标号〉。括号属于标号，不属于点号；点号指逗号、句号等表示停顿的标点。"}, {"text": "间隔号是一种点号，用来分隔外国人名的音节。", "explanation": "这里应该用〈标号〉。间隔号属于标号，不属于点号；点号指逗号、句号等表示停顿的标点。"}, {"text": "连接号是一种点号，用来连接相关的词语。", "explanation": "这里应该用〈标号〉。连接号属于标号，不属于点号；点号指逗号、句号等表示停顿的标点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94092, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "文章末尾少了一只点号。", "corrected_sentence": "文章末尾少了一个点号。", "error_description": "量词错误：“点号”应该用量词“个”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94092, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这页纸上的一条点号写得很整齐。", "corrected_sentence": "这页纸上的一个点号写得很整齐。", "error_description": "量词错误：“点号”应该用量词“个”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
