INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94097, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "之上是说在某个东西的上面。", "primary_collocate": null, "pronunciation": "zhī shàng", "ipa": "ʈʂɨ˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这座高山之上终年积着白雪。", "target_word": "之上", "complexity_tier": "T3", "furigana": "zhè zuò gāo shān zhī shàng zhōng nián jī zhe bái xuě", "sentence_source": "generated"}, {"text": "云在山顶之上慢慢飘过。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屋顶之上有一只小鸟。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞到了云层之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水之上有一座小桥。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天空之上飘着几朵白云。", "target_word": "之上", "complexity_tier": "T3", "furigana": "tiān kōng zhī shàng piāo zhe jǐ duǒ bái yún", "sentence_source": "generated"}, {"text": "月亮升到了树林之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市之上飘着淡淡的雾。", "target_word": "之上", "complexity_tier": "T3", "furigana": "chéng shì zhī shàng piāo zhe dàn dàn de wù", "sentence_source": "generated"}, {"text": "我们的头顶之上是蓝蓝的天空。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大桥之上有很多汽车。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "具体位置：在某物的上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94097, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之上", "is_correct": true, "explanation": "正确：“之上”表示在高山的上方，雪积在山顶。"}, {"text": "之内", "is_correct": false, "explanation": "语义：积雪在山体内部说不通，雪是积在山的上部或表面的。"}, {"text": "外边", "is_correct": false, "explanation": "语域：“外边”口语色彩较重，且指山外，不合“山上积雪”的语境。"}, {"text": "之前", "is_correct": false, "explanation": "语义：“之前”指在山的前面，雪不会积在山前。"}], "explanations": {"之上": "正确：“之上”表示在高山的上方，雪积在山顶。", "之内": "语义：积雪在山体内部说不通，雪是积在山的上部或表面的。", "外边": "语域：“外边”口语色彩较重，且指山外，不合“山上积雪”的语境。", "之前": "语义：“之前”指在山的前面，雪不会积在山前。"}, "sentence_index": 0, "correct_answer": "之上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地下停车场在地面之上。", "explanation": "这里应该用〈之下〉。地下停车场在地面之下，之上表示在某物的上方，不能用来说地下的位置。"}, {"text": "他在厨房之上做饭。", "explanation": "这里应该用〈里〉。之上表示在某物的上方，不表示在场所内部做事；此处应说“在厨房里做饭”。"}, {"text": "我们三点之上见面。", "explanation": "“之上”表示空间位置，不表示时间；此处说的是时刻，应说“三点以后”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94097, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之上", "is_correct": true, "explanation": "正确：“之上”表示月亮从树林的上方升起。"}, {"text": "之下", "is_correct": false, "explanation": "语义：月亮不会从树林下方升起，“升到树林之下”与句意不合。"}, {"text": "底下", "is_correct": false, "explanation": "语域：“底下”是口语，且指下方，与“升到”的方向相反。"}, {"text": "外头", "is_correct": false, "explanation": "语域：“外头”口语色彩重，书面句中不合，且没有表示月亮升到的高处。"}], "explanations": {"之上": "正确：“之上”表示月亮从树林的上方升起。", "之下": "语义：月亮不会从树林下方升起，“升到树林之下”与句意不合。", "底下": "语域：“底下”是口语，且指下方，与“升到”的方向相反。", "外头": "语域：“外头”口语色彩重，书面句中不合，且没有表示月亮升到的高处。"}, "sentence_index": 6, "correct_answer": "之上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在房间之上读书。", "explanation": "这里应该用〈里〉。之上表示在某物的上方，不表示在场所内部做事；此处应说“在房间里读书”。"}, {"text": "湖面之上沉入了一块大石头。", "explanation": "这里应该用〈之下〉。石头沉入湖面之下，之上表示在上方，与“沉入”的方向矛盾。"}, {"text": "这场比赛在两点之上开始。", "explanation": "“之上”表示空间位置，不表示时间；此处说的是时刻，不能用“之上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94097, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鸟儿飞树林之上。", "corrected_sentence": "鸟儿飞在树林之上。", "error_description": "漏字：“飞在……之上”中的“在”不能省，应说“鸟儿飞在树林之上”，不能说“鸟儿飞树林之上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94097, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "湖面的之上飘着一层薄雾。", "corrected_sentence": "湖面之上飘着一层薄雾。", "error_description": "多余的“的”：“之”已经起连接作用，“之上”前不能再加“的”，应说“湖面之上”，不能说“湖面的之上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "之下", "is_correct": true, "explanation": "正确：在地位、程度上，“之下”与“之上”相对，表示低于某物。"}, {"text": "以内", "is_correct": false, "explanation": "不是反义：“以内”表示在某界限之内，与地位或程度的高低无关。"}, {"text": "中间", "is_correct": false, "explanation": "不是反义：“中间”指位于两者之间，不与“之上”的高低义相对。"}, {"text": "内", "is_correct": false, "explanation": "不是反义：“内”指里面，与“之上”的高低义不相对。"}], "correct_answer": "之下", "explanations": {"之下": "正确：在地位、程度上，“之下”与“之上”相对，表示低于某物。", "以内": "不是反义：“以内”表示在某界限之内，与地位或程度的高低无关。", "中间": "不是反义：“中间”指位于两者之间，不与“之上”的高低义相对。", "内": "不是反义：“内”指里面，与“之上”的高低义不相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "之下", "is_correct": true, "explanation": "正确：在地位、程度上，“之下”与“之上”相对，表示低于某物。"}, {"text": "以外", "is_correct": false, "explanation": "不是反义：“以外”表示在某界限之外，与地位或程度的高低无关。"}, {"text": "里面", "is_correct": false, "explanation": "不是反义：“里面”指内部，与“之上”的高低义不相对。"}, {"text": "内侧", "is_correct": false, "explanation": "不是反义：“内侧”指靠里的一侧，与“之上”的程度高低无关。"}], "correct_answer": "之下", "explanations": {"之下": "正确：在地位、程度上，“之下”与“之上”相对，表示低于某物。", "以外": "不是反义：“以外”表示在某界限之外，与地位或程度的高低无关。", "里面": "不是反义：“里面”指内部，与“之上”的高低义不相对。", "内侧": "不是反义：“内侧”指靠里的一侧，与“之上”的程度高低无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "方位词，表示在某物的上方，或在某种程度、范围之外更高处。", "primary_collocate": null, "pronunciation": "zhī shàng", "ipa": "ʈʂɨ˥ ʂɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "在他心里，家人在工作之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家利益在个人利益之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "健康应该放在金钱之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试他的成绩在平均水平之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的能力在我们所有人之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律之上没有任何人可以例外。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把朋友放在名声之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的要求在我的想象之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "安全在速度之上，开车别太快。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对父母来说，孩子的幸福在一切之上。", "target_word": "之上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "抽象高低：在某种程度、地位或范围之上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "之上", "is_correct": true, "explanation": "正确：“之上”表示家人比工作更重要。"}, {"text": "之内", "is_correct": false, "explanation": "语义：“工作之内”只表示范围，表达不了家人的主次，与句意不合。"}, {"text": "外头", "is_correct": false, "explanation": "语域：“外头”是口语，与书面的“之上”不合，且意思是工作外面，不表示主次。"}, {"text": "之中", "is_correct": false, "explanation": "语义：“之中”指身处工作之中，不表示家人的地位高于工作。"}], "explanations": {"之上": "正确：“之上”表示家人比工作更重要。", "之内": "语义：“工作之内”只表示范围，表达不了家人的主次，与句意不合。", "外头": "语域：“外头”是口语，与书面的“之上”不合，且意思是工作外面，不表示主次。", "之中": "语义：“之中”指身处工作之中，不表示家人的地位高于工作。"}, "sentence_index": 0, "correct_answer": "之上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地下停车场在地面之上。", "explanation": "这里应该用〈之下〉。地下停车场在地面之下，之上表示在某物的上方，不能用来说地下的位置。"}, {"text": "他的成绩在椅子之上。", "explanation": "这里用了具体位置义，“成绩”不能放在椅子上方；此句要表示抽象的高低。"}, {"text": "我们三点之上见面。", "explanation": "“之上”不能表示时间，此处说的是时刻，与表示成绩高低的抽象义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "之上", "is_correct": true, "explanation": "正确：“之上”表示朋友比名声更重要。"}, {"text": "底下", "is_correct": false, "explanation": "语义：“放在名声底下”表示把朋友置于名声之下，与句意“朋友比名声重要”相反。"}, {"text": "北边", "is_correct": false, "explanation": "语义：名声没有方位，“北边”与“名声”搭配不合。"}, {"text": "南边", "is_correct": false, "explanation": "语义：名声不能放在南边，此处说的是主次先后。"}], "explanations": {"之上": "正确：“之上”表示朋友比名声更重要。", "底下": "语义：“放在名声底下”表示把朋友置于名声之下，与句意“朋友比名声重要”相反。", "北边": "语义：名声没有方位，“北边”与“名声”搭配不合。", "南边": "语义：名声不能放在南边，此处说的是主次先后。"}, "sentence_index": 6, "correct_answer": "之上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子在房间之上玩耍。", "explanation": "这里应该用〈里〉。之上表示在某物的上方，不表示在场所内部玩耍；此处应说“在房间里玩耍”。"}, {"text": "湖水之上沉入了一块大石头。", "explanation": "这里应该用〈之下〉。石头沉入湖水之下，之上表示在上方，与“沉入”的方向矛盾。"}, {"text": "这场比赛在两点之上开始。", "explanation": "“之上”不能表示时间，此处说的是时刻，与表示主次的抽象义无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在我看来，健康比金钱之上。", "corrected_sentence": "在我看来，健康在金钱之上。", "error_description": "用词错误：“之上”前要用“在”引出比较的范围，不能用“比”，错误形式为“健康比金钱之上”，正确形式为“健康在金钱之上”，表示健康的重要性高于金钱。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94098, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "对我来说，时间金钱之上。", "corrected_sentence": "对我来说，时间在金钱之上。", "error_description": "漏字：“在……之上”的框架中“在”不能省，应说“时间在金钱之上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
