INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94101, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人民政府是管理一个地方、为大家办事的机关。", "primary_collocate": null, "pronunciation": "rén mín zhèng fǔ", "ipa": "ʐən˧˥ min˧˥ ʈʂəŋ˥˩ fu˨˩˦", "syllable_count": 4, "sentences": [{"text": "人民政府为大家办事。", "target_word": "人民政府", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们镇的人民政府在大路旁边。", "target_word": "人民政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路坏了，大家去找人民政府帮忙。", "target_word": "人民政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人民政府每天都很早开门。", "target_word": "人民政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在县人民政府工作，每天帮大家办事。", "target_word": "人民政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的人民政府想给孩子们盖一所新学校。", "target_word": "人民政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想了解本地的新规定，可以去问人民政府。", "target_word": "人民政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，人民政府请工人修好了路。", "target_word": "人民政府", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的人民政府为老人建了一个公园。", "target_word": "人民政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家有困难，就可以找人民政府。", "target_word": "人民政府", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "县人民政府", "label": "复合"}, {"form": "市人民政府", "label": "复合"}], "register": "正式", "sense_fingerprint": "管理一个地方、为大家办事的机关", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94101, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "猫", "is_correct": false, "explanation": "语义：猫是动物，不是机关，不能为大家办事。"}, {"text": "人民政府", "is_correct": true, "explanation": "正确：人民政府是管理地方事务的机关，可以为大家办事。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会办事。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“办事”要求有行为能力的主体，“天气”不能说为大家办事。"}], "explanations": {"猫": "语义：猫是动物，不是机关，不能为大家办事。", "人民政府": "正确：人民政府是管理地方事务的机关，可以为大家办事。", "桌子": "语义：桌子是家具，不会办事。", "天气": "搭配：“办事”要求有行为能力的主体，“天气”不能说为大家办事。"}, "sentence_index": 0, "correct_answer": "人民政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起案子已经由县人民政府审理。", "explanation": "这里应该用〈人民法院〉。审理案件是法院的工作，人民政府管理地方事务，不审理案件。"}, {"text": "这名嫌疑人由县人民政府起诉。", "explanation": "这里应该用〈人民检察院〉。起诉是检察院的职能，人民政府不负责起诉。"}, {"text": "我的新朋友叫人民政府。", "explanation": "“人民政府”是机关名称，不能用作人名。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94101, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不会回答问题，不能去问。"}, {"text": "人民政府", "is_correct": true, "explanation": "正确：人民政府掌握本地规定，可以去问。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是材料，不能回答关于规定的问题。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“去问”的对象要能提供信息，饭店一般不回答规定方面的问题，搭配不当。"}], "explanations": {"石头": "语义：石头不会回答问题，不能去问。", "人民政府": "正确：人民政府掌握本地规定，可以去问。", "玻璃": "语义：玻璃是材料，不能回答关于规定的问题。", "饭店": "搭配：“去问”的对象要能提供信息，饭店一般不回答规定方面的问题，搭配不当。"}, "sentence_index": 6, "correct_answer": "人民政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "生病了，就去人民政府看医生。", "explanation": "这里应该用〈医院〉。人民政府是管理地方事务的机关，不是看病的地方。"}, {"text": "妈妈在厨房里做了一个人民政府。", "explanation": "“做”的对象应是食物或物品，人民政府是机关，不能这样做出来。"}, {"text": "这块石头的颜色是人民政府。", "explanation": "“人民政府”指机关，不能用来表示颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94101, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "县里有一本人民政府。", "corrected_sentence": "县里有一个人民政府。", "error_description": "错误形式：“一本”；正确形式：“一个”。“人民政府”前的量词应是〈个〉，“本”用于书籍等，不能用于机关。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94101, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们镇的人民政府的很近。", "corrected_sentence": "我们镇的人民政府很近。", "error_description": "错误形式：“我们镇的人民政府的很近”；正确形式：“我们镇的人民政府很近”。“人民政府”后多了一个“的”，“的”后面接形容词谓语“很近”时不能用，应去掉。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
