INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修正是把不对的地方改成对的。", "primary_collocate": null, "pronunciation": "xiū zhèng", "ipa": "ɕi̯oʊ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他把试卷上的错字修正了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "发现问题后，我们马上修正。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑修正了文章里的错字。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个说明有错，请你修正。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她修正了自己的发音。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师修正了图纸上的数字。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们自己修正答案。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他修正过这篇文章三次。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者把新闻里的错误修正了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误我已经修正好了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修正了", "label": "体标"}, {"form": "修正过", "label": "体标"}], "register": "书面", "sense_fingerprint": "把不对的地方改成对的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修正", "is_correct": true, "explanation": "正确。“修正”表示改正错字，与“错字”搭配。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：“朗读”指大声读出文字，不能用来表示改正错字。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化物品，不能用来表示改正错字。"}, {"text": "收割", "is_correct": false, "explanation": "搭配：“收割”用于庄稼，不能说收割错字。"}], "explanations": {"修正": "正确。“修正”表示改正错字，与“错字”搭配。", "朗读": "语义：“朗读”指大声读出文字，不能用来表示改正错字。", "装饰": "语义：“装饰”指美化物品，不能用来表示改正错字。", "收割": "搭配：“收割”用于庄稼，不能说收割错字。"}, "sentence_index": 0, "correct_answer": "修正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人修正了坏掉的洗衣机。", "explanation": "这里应该用〈修理〉。修正指改正错误或偏差，不用于修复坏掉的机器。"}, {"text": "师傅修正了开裂的墙壁。", "explanation": "这里应该用〈修补〉。修正指改正错误或偏差，不用于修补破损的墙面。"}, {"text": "医生修正了他的感冒。", "explanation": "这里应该用〈治疗〉。修正指改正错误，不用于治疗疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修正", "is_correct": true, "explanation": "正确。“修正”表示改正答案中的错误，与“答案”搭配。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽培植物，不能用来表示改正答案。"}, {"text": "收拾", "is_correct": false, "explanation": "搭配：“收拾”用于房间、行李等，不能说收拾答案。"}, {"text": "剪", "is_correct": false, "explanation": "搭配：“剪”用于布料、纸张等实物，不能说剪答案。"}], "explanations": {"修正": "正确。“修正”表示改正答案中的错误，与“答案”搭配。", "种": "语义：“种”指栽培植物，不能用来表示改正答案。", "收拾": "搭配：“收拾”用于房间、行李等，不能说收拾答案。", "剪": "搭配：“剪”用于布料、纸张等实物，不能说剪答案。"}, "sentence_index": 6, "correct_answer": "修正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "理发师修正了他的头发。", "explanation": "这里应该用〈修剪〉。修剪指剪去多余的枝叶或头发，修正指改正错误，不用于剪头发。"}, {"text": "建筑队修正了一座桥。", "explanation": "这里应该用〈修建〉。修建指建造或修筑工程，修正指改正错误，不能用于建造桥梁。"}, {"text": "学生修正了三门课程。", "explanation": "这里应该用〈修习〉。修习指学习课程，修正指改正错误或偏差，学生学习课程要说“修习”，不用“修正”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈刚才把菜谱上的错字修正。", "corrected_sentence": "妈妈刚才把菜谱上的错字修正了。", "error_description": "“把”字句的谓语动词后须有补语或“了”等成分；“刚才”指已完成的动作，所以应补上“了”，说“修正了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94103, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这段代码他修正很快。", "corrected_sentence": "这段代码他修正得很快。", "error_description": "“修正很快”漏了“得”，应为“修正得很快”：动词后带形容词作补语时，须用“得”连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
