INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改正错误或偏差，使之正确、合适。", "primary_collocate": null, "pronunciation": "xiū zhèng", "ipa": "ɕi̯oʊ˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "老师修正了作文里的错误。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要修正今年的计划。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你修正一下这张地图上的错误。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家修正了原来的看法。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要及时修正自己的方向。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他发现数字错了，马上修正了。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生修正了治疗方案。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理修正了报告里的数据。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在飞行中修正了航线。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府已经修正了这条规定。", "target_word": "修正", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "修正了", "label": "体标"}, {"form": "修正过", "label": "体标"}], "register": "书面", "sense_fingerprint": "改正错误或偏差，使之正确合适", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "修正", "is_correct": true, "explanation": "正确。“修正”表示改正错误，与“作文里的错误”搭配。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赏识美好的事物，不能用来表示改正错误。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：“修剪”用于枝叶、头发，不能说修剪错误。"}, {"text": "赞美", "is_correct": false, "explanation": "语义：“赞美”的对象是人或美好的事物，不能用来赞美错误。"}], "explanations": {"修正": "正确。“修正”表示改正错误，与“作文里的错误”搭配。", "欣赏": "语义：“欣赏”指赏识美好的事物，不能用来表示改正错误。", "修剪": "搭配：“修剪”用于枝叶、头发，不能说修剪错误。", "赞美": "语义：“赞美”的对象是人或美好的事物，不能用来赞美错误。"}, "sentence_index": 0, "correct_answer": "修正"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人修正了坏掉的自行车。", "explanation": "这里应该用〈修理〉。修正指改正错误或偏差，不用于修复坏掉的机器。"}, {"text": "我们修正了工作环境。", "explanation": "这里应该用〈改善〉。修正用于错误、计划、看法等，不用于改进环境状况。"}, {"text": "他修正了漏雨的屋顶。", "explanation": "这里应该用〈修补〉。修正指纠正错误或偏差，不用于修补破损的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "修正", "is_correct": true, "explanation": "正确。“修正”表示修改不妥之处，与“治疗方案”搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发声演唱，不能用来形容对方案的处理。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是药、食物，不能说吃治疗方案。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能打扫方案。"}], "explanations": {"修正": "正确。“修正”表示修改不妥之处，与“治疗方案”搭配。", "唱": "语义：“唱”指发声演唱，不能用来形容对方案的处理。", "吃": "搭配：“吃”的对象是药、食物，不能说吃治疗方案。", "打扫": "搭配：“打扫”的对象是场所或物品，不能打扫方案。"}, "sentence_index": 6, "correct_answer": "修正"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工匠修正了古老的瓷器。", "explanation": "这里应该用〈修复〉。修正指改正错误或偏差，不用于修复破损的器物。"}, {"text": "他的健康终于修正了。", "explanation": "这里应该用〈恢复〉。修正用于错误或偏差，不用于身体或健康状况的恢复。"}, {"text": "施工队修正了旧房子。", "explanation": "这里应该用〈翻新〉。修正指改正错误，不用于房屋的整修或翻修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师修正作业很仔细。", "corrected_sentence": "老师修正作业得很仔细。", "error_description": "“修正作业很仔细”漏了“得”，应为“修正作业得很仔细”：动词后带形容词作补语时，须用“得”连接。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会计昨天修正表格里的金额。", "corrected_sentence": "会计昨天修正了表格里的金额。", "error_description": "“昨天修正表格里的金额”漏了“了”，应为“昨天修正了表格里的金额”：“昨天”指已完成的动作，动词后须用“了”表示完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进站", "is_correct": true, "explanation": "进站与出站相对：一个是进入车站，一个是离开车站，构成反义。"}, {"text": "吃饭", "is_correct": false, "explanation": "与“出站”没有反义关系，不是它任何义项的反义词。"}, {"text": "睡觉", "is_correct": false, "explanation": "与“出站”没有反义关系，二者语义无对立。"}, {"text": "登机", "is_correct": false, "explanation": "登机指上飞机，与“出站”没有反义关系。"}], "correct_answer": "进站", "explanations": {"进站": "进站与出站相对：一个是进入车站，一个是离开车站，构成反义。", "吃饭": "与“出站”没有反义关系，不是它任何义项的反义词。", "睡觉": "与“出站”没有反义关系，二者语义无对立。", "登机": "登机指上飞机，与“出站”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进站", "is_correct": true, "explanation": "进站与出站相对：一个是进入车站，一个是离开车站，构成反义。"}, {"text": "游泳", "is_correct": false, "explanation": "与“出站”没有反义关系，二者语义无对立。"}, {"text": "写信", "is_correct": false, "explanation": "与“出站”没有反义关系，不是它任何义项的反义词。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“出站”没有反义关系，二者语义无对立。"}], "correct_answer": "进站", "explanations": {"进站": "进站与出站相对：一个是进入车站，一个是离开车站，构成反义。", "游泳": "与“出站”没有反义关系，二者语义无对立。", "写信": "与“出站”没有反义关系，不是它任何义项的反义词。", "跳舞": "与“出站”没有反义关系，二者语义无对立。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "离开车站，或列车驶出车站。", "primary_collocate": null, "pronunciation": "chū zhàn", "ipa": "ʈʂʰu˥ ʈʂan˥˩", "syllable_count": 2, "sentences": [{"text": "火车慢慢出站了。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "列车出站后，速度越来越快。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这趟高铁刚出站，我们没赶上。", "target_word": "出站", "complexity_tier": "T3", "furigana": "chū zhàn", "sentence_source": "generated"}, {"text": "地铁刚出站，天就黑了。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乘客们从北门出站，坐上了出租车。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出站时，手机没电了。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "快车先出站，慢车还在等着。", "target_word": "出站", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "列车还没出站，乘客不能下车。", "target_word": "出站", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我一出站，就看见了接我的人。", "target_word": "出站", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人拿着票，跟大家一起出站。", "target_word": "出站", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出了站", "label": "体标"}, {"form": "出站口", "label": "复合"}], "register": "中性", "sense_fingerprint": "人离开车站或列车驶出车站", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d7132db-349d-4d06-b68d-82e6dd273dcc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出站", "is_correct": true, "explanation": "出站指列车驶出车站，与“火车慢慢”相符。"}, {"text": "散步", "is_correct": false, "explanation": "语义：火车不会散步，与句子的主语不搭。"}, {"text": "起床", "is_correct": false, "explanation": "语义：火车不会起床，动作的主体与句子不合。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽是植物的生长，火车不会发芽，句子不成立。"}], "explanations": {"出站": "出站指列车驶出车站，与“火车慢慢”相符。", "散步": "语义：火车不会散步，与句子的主语不搭。", "起床": "语义：火车不会起床，动作的主体与句子不合。", "发芽": "语义：发芽是植物的生长，火车不会发芽，句子不成立。"}, "sentence_index": 0, "correct_answer": "出站"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去年出站留学了。", "explanation": "这里应该用〈出国〉。出站只指离开车站，不指出国留学。"}, {"text": "他康复以后就出站了。", "explanation": "这里应该用〈出院〉。出站只指离开车站，不能用于病人离开医院。"}, {"text": "演员在台上讲完话，就出站了。", "explanation": "这里应该用〈出场〉。出站只指离开车站，不能指演员登台或退场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出站", "is_correct": true, "explanation": "出站指列车驶出车站，与“快车先”“慢车还在等着”相符。"}, {"text": "上车", "is_correct": false, "explanation": "配价：“上车”的主体须是乘客，快车不能“上车”。"}, {"text": "打牌", "is_correct": false, "explanation": "语义：快车不会打牌，与句中列车的语境不合。"}, {"text": "挂号", "is_correct": false, "explanation": "语义：快车不会挂号，句子不成立。"}], "explanations": {"出站": "出站指列车驶出车站，与“快车先”“慢车还在等着”相符。", "上车": "配价：“上车”的主体须是乘客，快车不能“上车”。", "打牌": "语义：快车不会打牌，与句中列车的语境不合。", "挂号": "语义：快车不会挂号，句子不成立。"}, "sentence_index": 6, "correct_answer": "出站"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书明年出站。", "explanation": "这里应该用〈出版〉。出站只指人或列车离开车站，不能用于书籍。"}, {"text": "他的手指被刀划伤，出站了。", "explanation": "这里应该用〈出血〉。出站不能用来描述伤口流出血液。"}, {"text": "这一局他三振就出站了。", "explanation": "这里应该用〈出局〉。出站只指离开车站，不能指棒球比赛中被淘汰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "列车出站着，车厢里的广播就响了起来。", "corrected_sentence": "列车出站了，车厢里的广播就响了起来。", "error_description": "错误形式：「出站着」。正确形式：「出站了」。「着」表示持续或状态，与一次性的离站动作不合，完成的离站要用「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他以前出站过，所以知道出口在哪儿。", "corrected_sentence": "他以前出过站，所以知道出口在哪儿。", "error_description": "体标“过”要紧跟动词，应说“出过站”，不能说“出站过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1358a500-c269-4b5e-bade-b7e509877f63') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后果", "is_correct": true, "explanation": "“后果”与“前因”相对，指事情发生之后产生的结果。"}, {"text": "方法", "is_correct": false, "explanation": "“方法”指解决问题的途径，与“前因”没有反义关系。"}, {"text": "地点", "is_correct": false, "explanation": "“地点”指位置场所，与“前因”没有反义关系。"}, {"text": "工具", "is_correct": false, "explanation": "“工具”指用来做事的器具，与“前因”没有反义关系。"}], "correct_answer": "后果", "explanations": {"后果": "“后果”与“前因”相对，指事情发生之后产生的结果。", "方法": "“方法”指解决问题的途径，与“前因”没有反义关系。", "地点": "“地点”指位置场所，与“前因”没有反义关系。", "工具": "“工具”指用来做事的器具，与“前因”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "后果", "is_correct": true, "explanation": "“后果”与“前因”相对，指事情发生之后产生的结果。"}, {"text": "时间", "is_correct": false, "explanation": "“时间”指时刻或时长，与“前因”没有反义关系。"}, {"text": "天气", "is_correct": false, "explanation": "“天气”指一定时期内的冷热阴晴，与“前因”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”指家具，与“前因”没有反义关系。"}], "correct_answer": "后果", "explanations": {"后果": "“后果”与“前因”相对，指事情发生之后产生的结果。", "时间": "“时间”指时刻或时长，与“前因”没有反义关系。", "天气": "“天气”指一定时期内的冷热阴晴，与“前因”没有反义关系。", "桌子": "“桌子”指家具，与“前因”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "前因是一件事发生以前的原因。", "primary_collocate": null, "pronunciation": "qián yīn", "ipa": "tɕʰjɛn˧˥ in˥", "syllable_count": 2, "sentences": [{"text": "这件事的前因，老师不太清楚。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先说说事情的前因，我再帮你想办法。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这件事的前因都告诉了警察。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要明白现在的问题，先要了解它的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场争吵的前因其实很简单。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只听到结果，不知道前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她问了很久，才知道事情的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书先写了故事的前因，再写结果。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每件事都有前因，也有后果。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者正在调查火灾的前因。", "target_word": "前因", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "一件事发生以前的原因，常与后果相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef677c3c-1a6b-46ad-b43b-3ee3b8f93f4d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "前因", "is_correct": true, "explanation": "“前因”指事情发生前的原因，与“老师不太清楚”相符。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的钱数，不能指事情的起因。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的身体高矮，不能用于事情。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指事物的色彩，不能指事情的起因。"}], "explanations": {"前因": "“前因”指事情发生前的原因，与“老师不太清楚”相符。", "价格": "语义：“价格”指商品的钱数，不能指事情的起因。", "身高": "体貌：“身高”指人的身体高矮，不能用于事情。", "颜色": "语义：“颜色”指事物的色彩，不能指事情的起因。"}, "sentence_index": 0, "correct_answer": "前因"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部小说的前因是一个悲伤的结局。", "explanation": "这里应该用〈结局〉。前因指事情发生以前的原因，说故事最后的结果要用“结局”。"}, {"text": "这次事故造成的前因很严重。", "explanation": "这里应该用〈后果〉。“造成”后面接结果，“前因”指事情发生前的原因，两者方向相反。"}, {"text": "他买这台电脑的前因很便宜。", "explanation": "这里应该用〈价格〉。前因指事情发生前的原因，说东西便宜与否要用“价格”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "前因", "is_correct": true, "explanation": "“前因”指事情的起因，与“问了很久才知道”的语境相符。"}, {"text": "报酬", "is_correct": false, "explanation": "语义：“报酬”指劳动所得，不是事情的缘由。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”用于物体，不说事情的重量。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”指物体的大小，不用于事情。"}], "explanations": {"前因": "“前因”指事情的起因，与“问了很久才知道”的语境相符。", "报酬": "语义：“报酬”指劳动所得，不是事情的缘由。", "重量": "搭配：“重量”用于物体，不说事情的重量。", "体积": "搭配：“体积”指物体的大小，不用于事情。"}, "sentence_index": 6, "correct_answer": "前因"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的前因老师住在北京。", "explanation": "这里应该用〈以前的〉。“前因”指事情的原因，不能用来修饰人。"}, {"text": "这种药的前因很好。", "explanation": "这里应该用〈效果〉。“前因”不能用来评价药的作用，描述药效要用“效果”。"}, {"text": "他的前因非常明确：考上大学。", "explanation": "这里应该用〈目标〉。“前因”指事情发生前的原因，说人的追求和计划要用“目标”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我还没有弄清楚这次争吵的一只前因。", "corrected_sentence": "我还没有弄清楚这次争吵的一个前因。", "error_description": "“前因”是抽象名词，计量要用“个”，“只”用于动物等，应说“一个前因”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94111, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他查了很久，才弄清楚这件事的一张前因。", "corrected_sentence": "他查了很久，才弄清楚这件事的前因。", "error_description": "“前因”是抽象名词，不能用“张”计量（“张”多用于纸张、桌子等），应去掉“一张”，说“这件事的前因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c8ea670-3fdd-4b30-b6b5-cba590d3a6fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
