INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94115, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94115, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示就算发生某种情况，结论也不会改变。", "primary_collocate": null, "pronunciation": "jí biàn", "ipa": "tɕi³⁵ pjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "即便下雨，我也要去跑步。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便很累，他也没有休息。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便是周末，爸爸也要上班。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便你不同意，我也会去。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便天气很冷，孩子们也在外面玩。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便再忙，她每天也要看书。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便没有钱，他也不愿向别人借钱。", "target_word": "即便", "complexity_tier": "T3", "furigana": "jí biàn méi yǒu qián, tā yě bú yuàn xiàng bié rén jiè qián.", "sentence_source": "generated"}, {"text": "即便老师不在，同学们也会安静地学习。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便路很远，我们也要走过去。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便他说了很多次，我还是不相信。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "即便是", "label": "复合"}], "register": "书面", "sense_fingerprint": "连词，就算出现某种情况，结果也不变，常与“也”连用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94115, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即便", "is_correct": true, "explanation": "“即便”引出让步条件，后句“也要去跑步”说明下雨并不改变结论，与空格处的连词吻合。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，与后句“也要去跑步”的让步语气冲突。"}, {"text": "由于", "is_correct": false, "explanation": "语域：“由于”偏书面正式，此句口语化，而且它引出的仍是原因，与“也要去跑步”冲突。"}, {"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一条件，说只有下雨才去跑步，与“也要去”的语气不合。"}], "explanations": {"即便": "“即便”引出让步条件，后句“也要去跑步”说明下雨并不改变结论，与空格处的连词吻合。", "因为": "语义：“因为”引出原因，与后句“也要去跑步”的让步语气冲突。", "由于": "语域：“由于”偏书面正式，此句口语化，而且它引出的仍是原因，与“也要去跑步”冲突。", "只有": "语义：“只有”表示唯一条件，说只有下雨才去跑步，与“也要去”的语气不合。"}, "sentence_index": 0, "correct_answer": "即便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "比赛取消了，即便下雨。", "explanation": "这里应该用〈因为〉。比赛取消是因为下雨，是因果关系；“即便”表示下雨也不影响结论，与“取消”的因果关系矛盾。"}, {"text": "他英语很好，即便数学也很好。", "explanation": "这里应该用〈而且〉。前后两句是并列补充，“即便”表示让步，而“数学也很好”并不出乎意料，不能用让步。"}, {"text": "他吃了饭，即便出门了。", "explanation": "这里应该用〈然后〉。这句讲先后动作，“即便”只能引出让步，不能表示动作的顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94115, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即便", "is_correct": true, "explanation": "“即便”表示即使没有钱，结论也不变，“他也不愿借钱”与之呼应。"}, {"text": "除非", "is_correct": false, "explanation": "语义：“除非”表示唯一的条件，说除非没有钱才不借，与“也不愿”的让步意思不合。"}, {"text": "不过", "is_correct": false, "explanation": "语法：“不过”是转折连词，需连接前后两个分句，不能直接充当条件分句的引导词。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”要接在前一个分句的转折之后，单独接“没有钱”这样的条件，句子不通。"}], "explanations": {"即便": "“即便”表示即使没有钱，结论也不变，“他也不愿借钱”与之呼应。", "除非": "语义：“除非”表示唯一的条件，说除非没有钱才不借，与“也不愿”的让步意思不合。", "不过": "语法：“不过”是转折连词，需连接前后两个分句，不能直接充当条件分句的引导词。", "然而": "搭配：“然而”要接在前一个分句的转折之后，单独接“没有钱”这样的条件，句子不通。"}, "sentence_index": 6, "correct_answer": "即便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花开了，即便春天来了。", "explanation": "这里应该用〈因为〉。花开是春天来了的结果，是因果关系；“即便”表示结论不受影响，用在这里与因果关系矛盾。"}, {"text": "我会唱歌，即便会跳舞。", "explanation": "这里应该用〈并且〉。两项能力是并列的，没有让步关系，“即便”用在这里不通。"}, {"text": "他接到电话，即便出门了。", "explanation": "这里应该用〈于是〉。前一件事引起后一个动作，是承接关系；“即便”只表示让步，不能用来承接动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94115, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "即便外面下着雨，所以我也要去打球。", "corrected_sentence": "即便外面下着雨，我也要去打球。", "error_description": "错误：“即便”表示让步，不能与表示结果的“所以”搭配。正确：“即便外面下着雨，我也要去打球。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94115, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "即便身体不舒服，所以她坚持上班。", "corrected_sentence": "即便身体不舒服，她也坚持上班。", "error_description": "错误：“即便”表示让步，不能与表示结果的“所以”搭配。正确：“即便身体不舒服，她也坚持上班。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94116, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
