INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94116, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示假设让步，相当于“即使”。", "primary_collocate": null, "pronunciation": "jí biàn", "ipa": "tɕi³⁵ pjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "即便明天下雪，比赛也不会改期。", "target_word": "即便", "complexity_tier": "T3", "furigana": "jí biàn míng tiān xià xuě, bǐ sài yě bú huì gǎi qī.", "sentence_source": "generated"}, {"text": "即便是小事，他也做得很认真。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便价格很高，很多人也想买。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便你现在道歉，也已经太晚了。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便是冬天，这里的花也开着。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便不饿，早饭也一定要吃。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便他很聪明，不努力也学不好。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便住得很近，我们也很少见面。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便是夜里，城市里也很热闹。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即便考试没通过，你也不要难过。", "target_word": "即便", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "即便是", "label": "复合"}], "register": "书面", "sense_fingerprint": "连词，先假设并让步，后面说出不受影响的结论，相当于“即使”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '829b3cd6-c5a4-42fd-b8c9-9e04b05f9127') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94116, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "即便", "is_correct": true, "explanation": "“即便”表示假设让步，后句“比赛也不会改期”说明即使下雪结论也不变。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出原因，“比赛也不会改期”与“因为下雪”的因果关系不成立。"}, {"text": "由于", "is_correct": false, "explanation": "语域：“由于”偏书面正式，此句语气较口语，且引出的仍是原因，与“也不会改期”不合。"}, {"text": "只有", "is_correct": false, "explanation": "语义：“只有”表示唯一条件，说只有明天下雪比赛才不改期，与句意相反。"}], "explanations": {"即便": "“即便”表示假设让步，后句“比赛也不会改期”说明即使下雪结论也不变。", "因为": "语义：“因为”引出原因，“比赛也不会改期”与“因为下雪”的因果关系不成立。", "由于": "语域：“由于”偏书面正式，此句语气较口语，且引出的仍是原因，与“也不会改期”不合。", "只有": "语义：“只有”表示唯一条件，说只有明天下雪比赛才不改期，与句意相反。"}, "sentence_index": 0, "correct_answer": "即便"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他没复习，即便考试不及格。", "explanation": "这里应该用〈所以〉。考试不及格是没复习的结果，是因果关系；“即便”表示结论不受影响，与“不及格”的因果关系矛盾。"}, {"text": "她会弹钢琴，即便会唱歌。", "explanation": "这里应该用〈而且〉。“弹钢琴”和“唱歌”是并列的两项能力，没有让步关系，“即便”用在这里不通。"}, {"text": "他写完作业，即便去睡觉了。", "explanation": "这里应该用〈然后〉。这句讲先后动作，“即便”只能引出让步，不能表示动作的顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94116, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "即便", "is_correct": true, "explanation": "“即便”表示即使他很聪明，结论也不变，“不努力也学不好”与之呼应。"}, {"text": "除非", "is_correct": false, "explanation": "语义：“除非”表示唯一条件，说除非他很聪明才学得好，与“不努力也学不好”的让步意思不合。"}, {"text": "一旦", "is_correct": false, "explanation": "搭配：“一旦”要接“就”引出新条件下的结果，此处“不努力也学不好”与之不搭。"}, {"text": "只要", "is_correct": false, "explanation": "语义：“只要”引出充分条件，句意变为“只要他聪明，不努力也学不好”，与原句的让步关系不符。"}], "explanations": {"即便": "“即便”表示即使他很聪明，结论也不变，“不努力也学不好”与之呼应。", "除非": "语义：“除非”表示唯一条件，说除非他很聪明才学得好，与“不努力也学不好”的让步意思不合。", "一旦": "搭配：“一旦”要接“就”引出新条件下的结果，此处“不努力也学不好”与之不搭。", "只要": "语义：“只要”引出充分条件，句意变为“只要他聪明，不努力也学不好”，与原句的让步关系不符。"}, "sentence_index": 6, "correct_answer": "即便"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很冷，即便我们没出去。", "explanation": "这里应该用〈因此〉。没出去是天气冷的结果，是因果关系；“即便”表示结论不受影响，与这里的因果关系矛盾。"}, {"text": "这家店离地铁近，即便环境很好。", "explanation": "这里应该用〈并且〉。两项优点是并列补充，没有让步关系，“即便”引出的让步在这里不通。"}, {"text": "他听到敲门声，即便开了门。", "explanation": "这里应该用〈于是〉。前一件事引起后一个动作，是承接关系；“即便”只表示让步，不能用来承接动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94116, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "即便明天下雨，所以我们也要出发。", "corrected_sentence": "即便明天下雨，我们也要出发。", "error_description": "错误：“即便”表示让步，不能与表示结果的“所以”搭配。正确：“即便明天下雨，我们也要出发。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94116, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "即便的很累，我还是要去。", "corrected_sentence": "即便很累，我还是要去。", "error_description": "错误形式：“即便的很累”，“即便”是连词，后面直接接分句，不能加“的”。正确形式：“即便很累，我还是要去”，“即便”位于让步分句句首，与后句“还是要去”配合表示即使很累仍然坚持。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55d7d6f3-2e89-4581-a175-6e24eb5567ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
