INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94117, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94117, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "又一次是说同样的事情再来一回。", "primary_collocate": null, "pronunciation": "yòu yí cì", "ipa": "iou˥˩ i˧˥ tsʰɹ̩˥˩", "syllable_count": 3, "sentences": [{"text": "他今天又一次迟到了。", "target_word": "又一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我又一次忘了带钥匙。", "target_word": "又一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈又一次说起小时候的事。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题他又一次做错了。", "target_word": "又一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "昨天下雨，今天又一次下雨了。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她又一次给我打电话，问我去不去。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师又一次讲了这个问题。", "target_word": "又一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟又一次把杯子打破了。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们又一次在公园里见面了。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又一次告诉我，明天要早点来。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "同样的事情再发生一回，多指已经发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e60ece-b0ef-49ed-9e2f-beaff451da86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94117, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从来", "is_correct": false, "explanation": "语义：“从来”指一贯如此或从未发生，与“今天”这一次具体的迟到不符。"}, {"text": "又一次", "is_correct": true, "explanation": "“又一次”表示又发生一回，符合句意。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的某个时候，与“今天”冲突。"}, {"text": "重新", "is_correct": false, "explanation": "搭配：“重新”多用于重做、重来，不用于“迟到”这类再次出现的事。"}], "explanations": {"从来": "语义：“从来”指一贯如此或从未发生，与“今天”这一次具体的迟到不符。", "又一次": "“又一次”表示又发生一回，符合句意。", "曾经": "语义：“曾经”指过去的某个时候，与“今天”冲突。", "重新": "搭配：“重新”多用于重做、重来，不用于“迟到”这类再次出现的事。"}, "sentence_index": 0, "correct_answer": "又一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "明天他又一次来看你。", "explanation": "这里应该用〈再〉。又一次只用于说已经发生过的事，说将来的事要用〈再〉。"}, {"text": "他又一次迟到了三次。", "explanation": "这里应该用〈又〉。又一次只表示再一回，不能与〈三次〉这类数量词连用。"}, {"text": "这是他第一次来北京，又一次来到北京。", "explanation": "这里应删去〈又一次〉。〈又一次〉表示同样的事已发生过，而这句说的是首次，二者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94117, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”指从未发生，与“讲了”的已发生矛盾。"}, {"text": "又一次", "is_correct": true, "explanation": "“又一次”表示再一回，符合句意。"}, {"text": "即将", "is_correct": false, "explanation": "搭配：“即将”表示将要，不与“了”搭配。"}, {"text": "将来", "is_correct": false, "explanation": "语义：“将来”指未来，与“讲了”的已发生矛盾。"}], "explanations": {"从不": "语义：“从不”指从未发生，与“讲了”的已发生矛盾。", "又一次": "“又一次”表示再一回，符合句意。", "即将": "搭配：“即将”表示将要，不与“了”搭配。", "将来": "语义：“将来”指未来，与“讲了”的已发生矛盾。"}, "sentence_index": 6, "correct_answer": "又一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每次都又一次迟到。", "explanation": "这里应删去〈又一次〉。〈又一次〉只表示再一回，与表示多次的意思矛盾。"}, {"text": "他从来又一次告诉我，明天要早点来。", "explanation": "这里应删去〈又一次〉。〈又一次〉表示已经发生过的重复，与〈从未发生〉的意思矛盾。"}, {"text": "这是他第一次夸我，却又一次夸我。", "explanation": "这里不能用〈又一次〉：〈又一次〉表示此前已发生过，与“这是第一次”的首次意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94117, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这周他又一次了忘了带作业。", "corrected_sentence": "这周他又一次忘了带作业。", "error_description": "错误形式：「又一次了忘了带作业」。正确形式：「又一次忘了带作业」。「了」表示动作完成，应放在动词之后，不能插在「又一次」与动词之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94117, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次考试他又一次又取得了高分。", "corrected_sentence": "这次考试他又一次取得了高分。", "error_description": "错误形式：「又一次又取得了高分」。正确形式：「又一次取得了高分」。「又一次」本身已含「又」的意思，后面不能再加「又」，造成重复。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "再一次，表示同一动作或事件重复发生。", "primary_collocate": null, "pronunciation": "yòu yí cì", "ipa": "iou˥˩ i˧˥ tsʰɹ̩˥˩", "syllable_count": 3, "sentences": [{"text": "比赛中，这个队又一次赢了。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又一次站在了老地方。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机又一次坏了，真让人生气。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月，公司又一次提高了价格。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又一次失败了，但没有放弃。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车又一次晚点了，大家都在等。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，花又一次开了。", "target_word": "又一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她又一次拿到了第一名。", "target_word": "又一次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市又一次下起了大雪。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又一次打开门，还是没人在家。", "target_word": "又一次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "同一动作或事件重复发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e60ece-b0ef-49ed-9e2f-beaff451da86') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "从不", "is_correct": false, "explanation": "语义：“从不”指从未发生，与“赢了”的已发生矛盾。"}, {"text": "每次", "is_correct": false, "explanation": "搭配：“每次”需与“都、就”搭配，不能单独修饰“赢了”。"}, {"text": "又一次", "is_correct": true, "explanation": "“又一次”表示同一事件又发生一回，符合句意。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指很久以前，与“比赛中”的当前时间不符。"}], "explanations": {"从不": "语义：“从不”指从未发生，与“赢了”的已发生矛盾。", "每次": "搭配：“每次”需与“都、就”搭配，不能单独修饰“赢了”。", "又一次": "“又一次”表示同一事件又发生一回，符合句意。", "从前": "语义：“从前”指很久以前，与“比赛中”的当前时间不符。"}, "sentence_index": 0, "correct_answer": "又一次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是公司第一次提价，又一次提高了价格。", "explanation": "这里应删去〈又一次〉。〈又一次〉表示同样的事已发生过，与句中首次提价的意思矛盾。"}, {"text": "公司从来又一次提高价格。", "explanation": "这里应删去〈又一次〉。〈又一次〉表示已经发生过的重复，与〈从未发生〉的意思矛盾。"}, {"text": "这个月，公司又一次提高了三次价格。", "explanation": "这里不宜用〈又一次〉。它只指再一回，与表示多次的数量意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "特意", "is_correct": false, "explanation": "搭配：“特意”需要有意识的主语，不说花“特意”开。"}, {"text": "又一次", "is_correct": true, "explanation": "“又一次”表示同一事件又发生一回，符合句意。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”指从未发生，与“开了”的已发生矛盾。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的某个时候，与“春天来了”的当下时间不符。"}], "explanations": {"特意": "搭配：“特意”需要有意识的主语，不说花“特意”开。", "又一次": "“又一次”表示同一事件又发生一回，符合句意。", "从来": "语义：“从来”指从未发生，与“开了”的已发生矛盾。", "曾经": "语义：“曾经”指过去的某个时候，与“春天来了”的当下时间不符。"}, "sentence_index": 6, "correct_answer": "又一次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从来又一次打开门，还是没人在家。", "explanation": "这里应删去〈又一次〉。〈又一次〉表示已经发生过的重复，与〈从未发生〉的意思矛盾。"}, {"text": "他又一次打开门，每次都没人在家。", "explanation": "这里不宜用〈又一次〉。它只指再一回，与表示多次的意思矛盾。"}, {"text": "这是他第一次来这里，又一次没人在家。", "explanation": "这里应删去〈又一次〉。〈又一次〉表示同样的事已发生过，与首次的意思矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他又一次又弄丢了自行车钥匙。", "corrected_sentence": "他又一次弄丢了自行车钥匙。", "error_description": "错误：「又一次」后面又多加了一个副词「又」，造成叠用。正确形式：「他又一次弄丢了自行车钥匙」。「又一次」是固定的副词结构，中间不能再加「又」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一年他又一次了获得奖学金。", "corrected_sentence": "这一年他又一次获得奖学金。", "error_description": "错误形式：「又一次了获得奖学金」。正确形式：「又一次获得奖学金」。「了」表示动作完成，应放在动词之后，不能插在「又一次」与动词之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a422f960-8a0e-41f0-a443-5ad30fcbf808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
