INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94119, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "可分是可以分开。", "primary_collocate": null, "pronunciation": "kě fēn", "ipa": "kʰɤ˨˩˦ fən˥", "syllable_count": 2, "sentences": [{"text": "这两块积木是可分的，用手一拉就开。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个玩具的身体是可分的，能拆开洗。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两层纸粘得不紧，是可分的。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的收纳盒是可分的，上下两层能拿开。", "target_word": "可分", "complexity_tier": "T3", "furigana": "wǒ de shōu nà hé shì kě fēn de，shàng xià liǎng céng néng ná kāi。", "sentence_source": "generated"}, {"text": "这种桌子的腿是可分的，搬家很方便。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个零件是可分的，不用工具就能拆开。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的书包是可分的，上面一层能拿下来。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条项链是可分的，中间有个扣子。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋糕盒的盖子和盒身是可分的。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双手套是可分的，手指部分可以摘下。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可分的", "label": "定语形式"}, {"form": "不可分", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "可分：东西可以拆开、分开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee3e7df-b1b0-4578-906e-2115242cea45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94119, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "可分", "is_correct": true, "explanation": "可分是可以分开，与“用手一拉就开”相符。"}, {"text": "牢固", "is_correct": false, "explanation": "语义：“牢固”指连接紧、不易分开，与“用手一拉就开”矛盾。"}, {"text": "完整", "is_correct": false, "explanation": "语义：“完整”指整体没有分开，与“用手一拉就开”的情况矛盾。"}, {"text": "坚不可摧", "is_correct": false, "explanation": "语域：“坚不可摧”是书面色彩很浓的成语，描述积木过于夸张；且与“一拉就开”语义冲突。"}], "explanations": {"可分": "可分是可以分开，与“用手一拉就开”相符。", "牢固": "语义：“牢固”指连接紧、不易分开，与“用手一拉就开”矛盾。", "完整": "语义：“完整”指整体没有分开，与“用手一拉就开”的情况矛盾。", "坚不可摧": "语域：“坚不可摧”是书面色彩很浓的成语，描述积木过于夸张；且与“一拉就开”语义冲突。"}, "sentence_index": 0, "correct_answer": "可分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个人的声音是可分的，闭上眼也能听清。", "explanation": "这里应该用〈可分辨〉。可分指物件能拆开；辨认两个人的声音要用〈可分辨〉。"}, {"text": "这台冰箱是可分的，可以分三个月付清。", "explanation": "这里应该用〈可分期〉。可分指物件能拆开；分期付款要用〈可分期〉。"}, {"text": "这两种病的症状是可分的，医生一看就知道。", "explanation": "这里应该用〈可区分〉。可分指物件能拆开；看出症状之间的不同要用〈可区分〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94119, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "可分", "is_correct": true, "explanation": "可分是可以分开，与“上面一层能拿下来”相符。"}, {"text": "稳重", "is_correct": false, "explanation": "搭配：“稳重”形容人的性格，不能用来说书包。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“勇敢”形容人的品质，用在书包上不通。"}, {"text": "密封", "is_correct": false, "explanation": "语义：“密封”指封死不能打开，与“上面一层能拿下来”矛盾。"}], "explanations": {"可分": "可分是可以分开，与“上面一层能拿下来”相符。", "稳重": "搭配：“稳重”形容人的性格，不能用来说书包。", "勇敢": "搭配：“勇敢”形容人的品质，用在书包上不通。", "密封": "语义：“密封”指封死不能打开，与“上面一层能拿下来”矛盾。"}, "sentence_index": 6, "correct_answer": "可分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这封信的字迹是可分的，一看就认得出是谁写的。", "explanation": "这里应该用〈可辨认〉。可分指物件能拆开；认出字迹是谁写的要用〈可辨认〉。"}, {"text": "这个标志是可分的，远远就能认出来。", "explanation": "这里应该用〈可识别〉。可分指物件能拆开；远处认出标志要用〈可识别〉。"}, {"text": "这两种茶叶的味道是可分的，喝一口就能辨别。", "explanation": "这里应该用〈可辨别〉。可分指物件能拆开；辨别两种茶叶的味道要用〈可辨别〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94119, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木板是可分地，拆下来就能搬走。", "corrected_sentence": "这块木板是可分的，拆下来就能搬走。", "error_description": "错误形式是“可分地”，正确形式是“可分的”。“可分”作谓语形容词时后面应用“的”；“地”只用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94119, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个衣柜是可分地，拆开后能搬进电梯。", "corrected_sentence": "这个衣柜是可分的，拆开后能搬进电梯。", "error_description": "错误形式是“可分地”，正确形式是“可分的”。“可分”作谓语形容词时后面应用“的”；“地”只修饰动词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8643841-5a78-4c34-bf55-856825e4348a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
