INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (94120, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "能够分开、可以被分成几部分的。", "primary_collocate": null, "pronunciation": "kě fēn", "ipa": "kʰɤ˨˩˦ fən˥", "syllable_count": 2, "sentences": [{"text": "这个任务是可分的，可以分成三步做。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔钱是可分的，可以分给几个人。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇课文是可分的，一共分成四段。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个蛋糕是可分的，八个人都能吃到。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件工作是可分的，我们三人各做一部分。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是可分的，能分成上下两部分。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地是可分的，可以分给两个孩子。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套书是可分的，不用一次买全。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的假期是可分的，可以分两次休。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间是可分的，中间能加一道墙。", "target_word": "可分", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可分的", "label": "定语形式"}, {"form": "不可分", "label": "否定形式"}], "register": "中性", "sense_fingerprint": "可分：整体可以被分成几部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee3e7df-b1b0-4578-906e-2115242cea45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
